import { Book } from "@/lib/types";

export const luke: Book = {
  id: "luke",
  name: "Lukas",
  shortName: "Lk",
  testament: "new",
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Da es nun schon viele unternommen haben, einen Bericht von den Ereignissen zu verfassen, die sich unter uns zugetragen haben*, *", heading: "Vorwort", footnotes: ["w. die unter uns erfüllt worden sind; o. zur Vollendung gekommen sind", "℘ ⇨Esyn: Synopse Nr. 125"] },
      { number: 2, text: "wie sie uns die überliefert haben, die von Anfang an Augenzeugen* und Diener des Wortes gewesen sind,", footnotes: ["℘ Joh 15,27; Apg 1,21.22; Hebr 2,3; 1Jo 1,1"] },
      { number: 3, text: "hat es auch mir gut geschienen, der ich allem von Anfang an genau gefolgt bin, es dir, hochedler Theophilus*, der Reihe nach zu schreiben,", footnotes: ["℘ Apg 1,1"] },
      { number: 4, text: "damit du die Zuverlässigkeit der Dinge erkennst, in denen du unterrichtet worden bist." },
      { number: 5, text: "Es war in den Tagen des Herodes*, des Königs von Judäa, ein Priester mit Namen Zacharias, aus der Abteilung des Abija*; und seine Frau war aus den Töchtern Aarons und ihr Name Elisabeth.", heading: "Ankündigung der Geburt des Johannes", footnotes: ["Herodes d. Gr., unter röm. Oberherrschaft König der Juden (37—4 v. Chr.). Jesus wurde etwa im Jahr 6 vor christl. Zeitrechnung geboren.\n℘ Mt 2,1", "℘ 1Chr 24,10.19; Neh 12,17 ⇨Esyn: Synopse Nr. 2"] },
      { number: 6, text: "Beide aber waren gerecht vor Gott und wandelten untadelig in allen Geboten und Satzungen des Herrn*.", footnotes: ["℘ 1Mo 7,1; 5Mo 10,12; 1Kö 15,5; Hi 1,1.8; Ps 119,1"] },
      { number: 7, text: "Und sie hatten kein Kind, weil Elisabeth unfruchtbar war*; und beide waren in ihren Tagen weit vorgerückt*.", footnotes: ["℘ 1Mo 11,30; 25,21; 29,31; Ri 13,2; 1Sam 1,5", "℘ 1Mo 17,17"] },
      { number: 8, text: "Es geschah aber, als er in der Ordnung seiner Abteilung den priesterlichen Dienst vor Gott verrichtete*,", footnotes: ["℘ 1Chr 24,1.3"] },
      { number: 9, text: "traf ihn nach der Gewohnheit des Priestertums das Los*, in den Tempel des Herrn zu gehen, um zu räuchern*.", footnotes: ["℘ 1Chr 24,5", "℘ 2Mo 30,1.7"] },
      { number: 10, text: "Und die ganze Menge des Volkes stand betend draußen zur Stunde des Räucherns." },
      { number: 11, text: "Ihm erschien aber ein Engel des Herrn* und stand zur Rechten des Räucheraltars.", footnotes: ["℘ Mt 1,20"] },
      { number: 12, text: "Und als Zacharias <ihn> sah, wurde er bestürzt, und Furcht kam über ihn*.", footnotes: ["℘ Kap. 2,9; Ri 6,22; Apg 10,4"] },
      { number: 13, text: "Der Engel aber sprach zu ihm: Fürchte dich nicht*, Zacharias! Denn dein Flehen ist erhört*, und Elisabeth, deine Frau, wird dir einen Sohn gebären, und du sollst seinen Namen Johannes nennen*.", footnotes: ["℘ V. 30", "℘ Dan 10,12", "℘ V. 60.63; Kap. 3,2; 1Mo 17,19; Mt 3,1"] },
      { number: 14, text: "Und er wird dir <zur> Freude und <zum> Jubel sein, und viele werden sich über seine Geburt freuen*.", footnotes: ["℘ V. 58"] },
      { number: 15, text: "Denn er wird groß sein vor dem Herrn*; weder Wein noch starkes Getränk wird er trinken* und schon von Mutterleibe an mit Heiligem Geist erfüllt werden*.", footnotes: ["℘ V. 32; Kap. 7,28; Mt 11,11", "℘ 4Mo 6,3; Ri 13,4.5; Mt 11,18", "℘ V. 41.67; Kap. 2,25"] },
      { number: 16, text: "Und viele der Söhne Israels wird er zu dem Herrn, ihrem Gott, bekehren*.", footnotes: ["℘ Mt 3,5.6"] },
      { number: 17, text: "Und er wird vor ihm hergehen* in dem Geist und der Kraft des Elia*, um der Väter Herzen zu bekehren zu den Kindern* und Ungehorsame zur Gesinnung von Gerechten, um dem Herrn ein zugerüstetes Volk zu bereiten*.", footnotes: ["℘ V. 76; Kap. 7,27; Mal 3,1", "℘ Mt 11,14", "℘ Mal 3,24", "℘ V. 77"] },
      { number: 18, text: "Und Zacharias sprach zu dem Engel: Woran soll ich dies erkennen*? Denn ich bin ein alter Mann, und meine Frau ist weit vorgerückt in ihren Tagen*.", footnotes: ["℘ 1Mo 15,8; Jes 38,22", "℘ 1Mo 17,17"] },
      { number: 19, text: "Und der Engel antwortete und sprach zu ihm: Ich bin Gabriel*, der vor Gott steht*, und ich bin gesandt worden, zu dir zu reden und dir diese gute Botschaft zu verkündigen*.", footnotes: ["℘ V. 26; Dan 8,16; 9,21", "℘ Offb 8,2", "℘ Ps 103,20"] },
      { number: 20, text: "Und siehe, du wirst stumm sein und nicht sprechen können bis zu dem Tag, da dies geschehen wird, dafür, dass du meinen Worten nicht geglaubt hast, die sich zu ihrer Zeit erfüllen werden." },
      { number: 21, text: "Und das Volk wartete auf Zacharias, und sie wunderten sich, dass er so lange im Tempel verweilte*.", footnotes: ["℘ 3Mo 9,23"] },
      { number: 22, text: "Als er aber herauskam, konnte er nicht zu ihnen reden, und sie erkannten, dass er im Tempel ein Gesicht gesehen hatte. Und er winkte ihnen zu und blieb stumm." },
      { number: 23, text: "Und es geschah, als die Tage seines Dienstes zu Ende waren, ging er weg in sein Haus." },
      { number: 24, text: "Nach diesen Tagen aber wurde Elisabeth, seine Frau, schwanger* und zog sich fünf Monate zurück und sagte:", footnotes: ["w. Nach diesen Tagen aber empfing Elisabeth, seine Frau"] },
      { number: 25, text: "So hat mir der Herr getan in den Tagen, in denen er <mich> angesehen hat, um meine Schmach vor den Menschen wegzunehmen*.", footnotes: ["℘ 1Mo 30,23"] },
      { number: 26, text: "Im sechsten Monat aber wurde der Engel Gabriel* von Gott in eine Stadt von Galiläa, mit Namen Nazareth, gesandt*,", heading: "Ankündigung der Geburt Jesu", footnotes: ["℘ V. 19", "℘ Kap. 2,39.51; Mt 2,23 ⇨Esyn: Synopse Nr. 3"] },
      { number: 27, text: "zu einer Jungfrau, die einem Mann namens Josef, aus dem Haus Davids*, verlobt war, und der Name der Jungfrau war Maria*.", footnotes: ["℘ Kap. 2,4; 3,23; 4,22", "℘ Kap. 2,5; Mt 1,16.18"] },
      { number: 28, text: "Und er kam zu ihr hinein und sprach: Sei gegrüßt, Begnadete! Der Herr <ist> mit dir*.", footnotes: ["℘ V. 42; Ri 5,24"] },
      { number: 29, text: "Sie aber wurde bestürzt über das Wort und überlegte, was für ein Gruß dies sei." },
      { number: 30, text: "Und der Engel sprach zu ihr: Fürchte dich nicht*, Maria! Denn du hast Gnade bei Gott gefunden.", footnotes: ["℘ V. 13; Kap. 2,10"] },
      { number: 31, text: "Und siehe, du wirst schwanger werden* und einen Sohn gebären, und du sollst seinen Namen Jesus nennen*.", footnotes: ["w. du wirst im Leibe empfangen", "℘ Kap. 2,21; Mt 1,21-23"] },
      { number: 32, text: "Dieser wird groß sein und Sohn des Höchsten genannt werden*; und der Herr, Gott, wird ihm den Thron seines Vaters David geben*;", footnotes: ["℘ V. 15; Ps 2,7; Mk 5,7", "℘ Ps 132,11"] },
      { number: 33, text: "und er wird über das Haus Jakobs herrschen* in Ewigkeit*, und seines Königtums wird kein Ende sein*.", footnotes: ["o. König sein", "griech. Äonen", "℘ Ps 45,7; 2Sam 7,12-16; Jes 9,6; Dan 2,44; 7,14.27; Mi 4,7; Joh 12,34; 2Petr 1,11"] },
      { number: 34, text: "Maria aber sprach zu dem Engel: Wie wird dies zugehen*, da ich von keinem Mann weiß?", footnotes: ["℘ Joh 3,9"] },
      { number: 35, text: "Und der Engel antwortete und sprach zu ihr: Der Heilige Geist wird über dich kommen, und Kraft des Höchsten wird dich überschatten*; darum wird auch das Heilige*, das geboren werden wird, Sohn Gottes genannt werden*.", footnotes: ["℘ Jes 7,14; Mt 1,18.20", "℘ Joh 6,69; Apg 3,14; Offb 3,7", "℘ Kap. 3,22; 4,34.41; 8,28; 9,35; Mt 16,16; Joh 9,35; Hebr 1,1.5; Offb 2,18"] },
      { number: 36, text: "Und siehe, Elisabeth, deine Verwandte, auch sie erwartet einen Sohn in ihrem Alter, und dies ist der sechste Monat bei ihr, die unfruchtbar genannt war." },
      { number: 37, text: "Denn kein Wort, das von Gott kommt, wird kraftlos sein*.", footnotes: ["℘ Kap. 18,27; Mt 19,26; Mk 10,27"] },
      { number: 38, text: "Maria aber sprach: Siehe, <ich bin> die Magd* des Herrn; es geschehe mir nach deinem Wort! Und der Engel schied von ihr.", footnotes: ["w. Sklavin"] },
      { number: 39, text: "Maria aber machte sich in diesen Tagen auf und ging mit Eile in das Gebirge, in eine Stadt Judas; *", heading: "Maria bei Elisabeth — Lobpreis der Maria", footnotes: ["℘ ⇨Esyn: Synopse Nr. 4"] },
      { number: 40, text: "und sie kam in das Haus des Zacharias und begrüßte die Elisabeth." },
      { number: 41, text: "Und es geschah, als Elisabeth den Gruß der Maria hörte, hüpfte das Kind in ihrem Leib; und Elisabeth wurde mit Heiligem Geist erfüllt*", footnotes: ["℘ V. 15"] },
      { number: 42, text: "und rief mit lauter Stimme und sprach: Gesegnet <bist> du unter den Frauen, und gesegnet <ist> die Frucht deines Leibes*!", footnotes: ["℘ V. 28"] },
      { number: 43, text: "Und woher <geschieht> mir dies, dass die Mutter meines Herrn zu mir kommt?" },
      { number: 44, text: "Denn siehe, als die Stimme deines Grußes in meine Ohren drang, hüpfte das Kind vor Freude* in meinem Leib.", footnotes: ["w. in Jubel"] },
      { number: 45, text: "Und glückselig, die geglaubt hat, denn es wird zur Erfüllung kommen, was von dem Herrn zu ihr geredet ist!" },
      { number: 46, text: "*Und Maria sprach: Meine Seele erhebt den Herrn,", footnotes: ["℘ V. 46-55: vgl. 1Sam 2,1-10"] },
      { number: 47, text: "und mein Geist hat gejubelt über Gott, meinen Retter.*", footnotes: ["℘ Ps 16,9; 35,9; Hab 3,18"] },
      { number: 48, text: "Denn er hat hingeblickt auf die Niedrigkeit seiner Magd*; denn siehe, von nun an werden mich glückselig preisen alle Geschlechter*.", footnotes: ["w. Sklavin", "℘ Kap. 11,27; 1Mo 30,13"] },
      { number: 49, text: "Denn Großes hat der Mächtige* an mir getan*, und heilig ist sein Name*.", footnotes: ["℘ 1Mo 17,1", "℘ Ps 126,3", "℘ Ps 111,9"] },
      { number: 50, text: "Und seine Barmherzigkeit ist von Geschlecht zu Geschlecht über die, welche ihn fürchten*.", footnotes: ["℘ Ps 103,13.17"] },
      { number: 51, text: "Er hat Macht geübt mit seinem Arm*; er hat zerstreut*, die in der Gesinnung ihres Herzens hochmütig sind*.", footnotes: ["℘ 2Mo 15,6", "℘ Ps 89,11", "℘ 2Sam 22,28; Dan 4,34"] },
      { number: 52, text: "Er hat Mächtige von Thronen hinabgestoßen* und Niedrige erhöht*.", footnotes: ["℘ Hi 12,19", "℘ Hi 5,11; Ps 107,41; Hes 21,31"] },
      { number: 53, text: "Hungrige hat er mit Gütern erfüllt* und Reiche leer fortgeschickt.", footnotes: ["℘ Ps 107,9"] },
      { number: 54, text: "Er hat sich Israels, seines Knechtes, angenommen*, um der Barmherzigkeit zu gedenken*", footnotes: ["℘ Jes 41,8-10", "℘ Ps 25,6; 98,3"] },
      { number: 55, text: "— wie er zu unseren Vätern geredet hat — gegenüber Abraham und seinen Nachkommen* in Ewigkeit*.* —", footnotes: ["w. seinem Samen", "griech. Äon", "℘ V. 72; 1Mo 17,7; Ps 105,42; Mi 7,20"] },
      { number: 56, text: "Und Maria blieb ungefähr drei Monate bei ihr; und sie kehrte zu ihrem Haus zurück." },
      { number: 57, text: "Für Elisabeth aber erfüllte sich die Zeit, dass sie gebären sollte, und sie gebar einen Sohn. *", heading: "Geburt des Johannes — Lobpreis des Zacharias", footnotes: ["℘ ⇨Esyn: Synopse Nr. 5"] },
      { number: 58, text: "Und ihre Nachbarn und Verwandten hörten, dass der Herr seine Barmherzigkeit an ihr groß gemacht habe, und sie freuten sich mit ihr*.", footnotes: ["℘ V. 14"] },
      { number: 59, text: "Und es geschah am achten Tag, da kamen sie, das Kind zu beschneiden*; und sie nannten es nach dem Namen seines Vaters Zacharias.", footnotes: ["℘ Kap. 2,21; 1Mo 17,12; 3Mo 12,3"] },
      { number: 60, text: "Und seine Mutter antwortete und sprach: Nein, sondern er soll Johannes heißen*.", footnotes: ["℘ V. 13"] },
      { number: 61, text: "Und sie sprachen zu ihr: Niemand ist in deiner Verwandtschaft, der diesen Namen trägt." },
      { number: 62, text: "Sie winkten aber seinem Vater zu, wie er etwa wolle, dass er heißen sollte." },
      { number: 63, text: "Und er forderte ein Täfelchen und schrieb darauf: Johannes ist sein Name*. Und sie wunderten sich alle.", footnotes: ["℘ V. 13"] },
      { number: 64, text: "Sogleich aber wurde sein Mund geöffnet und seine Zunge <gelöst>, und er redete und lobte Gott*.", footnotes: ["℘ Ps 51,17"] },
      { number: 65, text: "Und Furcht kam über alle, die um sie her wohnten*; und auf dem ganzen Gebirge von Judäa wurden alle diese Dinge besprochen.", footnotes: ["℘ Kap. 7,16"] },
      { number: 66, text: "Und alle, die es hörten, nahmen es zu Herzen* und sprachen. Was wird wohl aus diesem Kind werden? Denn auch des Herrn Hand war mit ihm*.", footnotes: ["℘ Kap. 2,19.51", "℘ Apg 11,21"] },
      { number: 67, text: "Und Zacharias, sein Vater, wurde mit Heiligem Geist erfüllt und weissagte* und sprach:", footnotes: ["℘ V. 15; 2Petr 1,21"] },
      { number: 68, text: "Gepriesen sei der Herr, der Gott Israels*, dass er sein Volk angesehen und <ihm> Erlösung geschaffen hat*.", footnotes: ["℘ Ps 72,18", "℘ Ps 111,9"] },
      { number: 69, text: "Er hat uns ein Horn des Heils* aufgerichtet im Hause Davids, seines Knechtes*,", footnotes: ["o. der Rettung\n℘ Kap. 2,30; 3,6; 1Sam 2,10; Ps 18,3", "℘ Ps 132,17"] },
      { number: 70, text: "wie er geredet hat durch den Mund seiner heiligen Propheten von Ewigkeit* her*:", footnotes: ["griech. Äon", "℘ Jer 23,5; Röm 1,2"] },
      { number: 71, text: "Rettung von unseren Feinden und von der Hand aller, die uns hassen*;", footnotes: ["℘ Ps 18,49; 44,8; Jes 35,4; 49,25; Jer 30,10; Zef 3,15"] },
      { number: 72, text: "um Barmherzigkeit zu üben an unseren Vätern und seines heiligen Bundes zu gedenken*,", footnotes: ["℘ V. 55; 3Mo 26,42; Ps 105,8; Hes 16,60; Gal 3,17"] },
      { number: 73, text: "des Eides, den er Abraham, unserem Vater, geschworen hat*; <und> uns zu geben,", footnotes: ["℘ 1Mo 22,16.17; Mi 7,20; Hebr 6,17"] },
      { number: 74, text: "dass wir, gerettet aus der Hand unserer Feinde, ohne Furcht ihm dienen sollen*", footnotes: ["℘ Zef 3,16"] },
      { number: 75, text: "in Heiligkeit und Gerechtigkeit vor ihm alle unsere Tage*.", footnotes: ["℘ Eph 4,24; Tit 2,12"] },
      { number: 76, text: "Und du, Kind, wirst ein Prophet des Höchsten genannt werden*; denn du wirst vor dem Angesicht des Herrn hergehen, seine Wege zu bereiten*,", footnotes: ["℘ Kap. 20,6; Mt 11,9", "℘ V. 17; Kap. 3,4"] },
      { number: 77, text: "um seinem Volk Erkenntnis des Heils* zu geben in Vergebung ihrer Sünden*,", footnotes: ["o. der Rettung", "℘ Kap. 3,3; Jer 31,34"] },
      { number: 78, text: "durch die herzliche Barmherzigkeit* unseres Gottes*, mit der uns der Aufgang aus der Höhe besuchen wird*,", footnotes: ["w. die Eingeweide der Barmherzigkeit", "℘ Jes 63,7", "℘ Jes 60,1.2; Mal 3,20"] },
      { number: 79, text: "um denen zu leuchten*, die in Finsternis und Todesschatten sitzen*, und unsere Füße zu richten auf den Weg des Friedens*. —", footnotes: ["℘ Eph 5,14", "℘ Kap. 2,32; Ps 107,10; Jes 42,7; Mt 4,16", "℘ Jes 59,8"] },
      { number: 80, text: "Das Kind aber wuchs und erstarkte im Geist* und war in der Einöde* bis zum Tag seines Auftretens vor Israel*.", footnotes: ["℘ Kap. 2,40", "w. in den Wüsten", "℘ Kap. 3,2"] },
    ]},
    { number: 2, verses: [
      { number: 1, text: "*Es geschah aber in jenen Tagen, dass eine Verordnung vom Kaiser Augustus* ausging, den ganzen Erdkreis einzuschreiben*. *", heading: "Die Geburt Jesu", footnotes: ["℘ Mt 1,18-25", "erster römischer Kaiser (31 v. Chr. bis 14 n. Chr.) namens Octavian. »Augustus« (= Erhabener) war der ihm vom römischen Senat verliehene Ehrentitel.", "Aufstellung von Bevölkerungslisten zur Steuereinschätzung durch die römischen Behörden", "℘ ⇨Esyn: Synopse Nr. 7"] },
      { number: 2, text: "Diese Einschreibung geschah als erste, als Quirinius Statthalter von Syrien war*.", footnotes: ["℘ Apg 5,37"] },
      { number: 3, text: "Und alle gingen hin, um sich einschreiben zu lassen, ein jeder in seine <Vater>stadt." },
      { number: 4, text: "Es ging aber auch Josef von Galiläa, aus der Stadt Nazareth, hinauf nach Judäa, in die Stadt Davids, die Bethlehem heißt, weil er aus dem Haus und Geschlecht Davids war*,", footnotes: ["℘ Kap. 1,27; Mt 2,5.6; Joh 7,42"] },
      { number: 5, text: "um sich einschreiben zu lassen mit Maria, seiner Verlobten, die schwanger war*.", footnotes: ["℘ Kap. 1,27.31"] },
      { number: 6, text: "Und es geschah, als sie dort waren, wurden ihre Tage erfüllt, dass sie gebären sollte;" },
      { number: 7, text: "und sie gebar ihren erstgeborenen Sohn* und wickelte ihn in Windeln und legte ihn in eine Krippe, weil in der Herberge kein Raum für sie war*.", footnotes: ["℘ Jes 9,5; Mt 2,1; Gal 4,4", "℘ Kap. 9,58"] },
      { number: 8, text: "Und es waren Hirten in derselben Gegend, die auf freiem Feld blieben und des Nachts Wache hielten über ihre Herde. *", heading: "Besuch der Hirten", footnotes: ["℘ ⇨Esyn: Synopse Nr. 8"] },
      { number: 9, text: "Und ein Engel des Herrn trat zu ihnen, und die Herrlichkeit des Herrn umleuchtete sie, und sie fürchteten sich mit großer Furcht*.", footnotes: ["℘ Kap. 1,11.12"] },
      { number: 10, text: "Und der Engel sprach zu ihnen: Fürchtet euch nicht*! Denn siehe, ich verkündige euch große Freude*, die für das ganze Volk sein wird*.", footnotes: ["℘ Kap. 1,13.30; Mt 28,5", "o. ich verkündige euch gute Botschaft von einer großen Freude", "℘ Kap. 24,52; Jes 9,2"] },
      { number: 11, text: "Denn euch ist heute ein Retter* geboren, der ist Christus, <der> Herr*, in Davids Stadt.", footnotes: ["℘ Mt 1,21", "℘ Apg 2,36; 1Kor 8,6; Phil 2,11"] },
      { number: 12, text: "Und dies sei euch das Zeichen: Ihr werdet ein Kind* finden, in Windeln gewickelt und in einer Krippe liegend.", footnotes: ["w. einen Säugling"] },
      { number: 13, text: "Und plötzlich war bei dem Engel eine Menge der himmlischen Heerscharen*, die Gott lobten* und sprachen:", footnotes: ["w. eines himmlischen Heeres\n℘ Dan 7,10", "℘ Ps 103,21"] },
      { number: 14, text: "Herrlichkeit Gott in der Höhe*, und Friede auf Erden* in* den Menschen <des> Wohlgefallens!", footnotes: ["℘ Kap. 19,38", "℘ Jes 9,5.6; 57,19", "o. unter"] },
      { number: 15, text: "Und es geschah, als die Engel von ihnen hinweg in den Himmel auffuhren, dass die Hirten zueinander sagten: Lasst uns doch hingehen nach Bethlehem und diese Sache sehen, die geschehen ist und die der Herr uns kundgetan hat." },
      { number: 16, text: "Und sie kamen eilend und fanden Maria und Josef, und das Kind* in der Krippe liegend*.", footnotes: ["w. einen Säugling", "℘ Mt 2,11"] },
      { number: 17, text: "Als sie es aber gesehen hatten, machten sie das Wort bekannt, das über dieses Kind zu ihnen geredet worden war." },
      { number: 18, text: "Und alle, die es hörten, wunderten sich über das, was ihnen von den Hirten gesagt wurde." },
      { number: 19, text: "Maria aber bewahrte alle diese Worte und erwog sie in ihrem Herzen*.", footnotes: ["℘ Kap. 1,66; 1Mo 37,11"] },
      { number: 20, text: "Und die Hirten kehrten zurück, priesen und lobten Gott für alles, was sie gehört und gesehen hatten, wie es ihnen gesagt worden war." },
      { number: 21, text: "Und als acht Tage vollendet waren, dass man ihn beschneiden sollte*, da wurde sein Name Jesus* genannt, der von dem Engel genannt worden war, ehe er im Mutterleib empfangen wurde*.", heading: "Darstellung im Tempel — Lobpreis Simeons — Die Prophetin Hanna", footnotes: ["℘ Kap. 1,59", "griech. Form des aram. jeschua (= Josua), d. h. Jahwe ist Rettung", "℘ Kap. 1,31; Mt 1,21.25 ⇨Esyn: Synopse Nr. 9"] },
      { number: 22, text: "Und als die Tage ihrer Reinigung nach dem Gesetz Moses vollendet waren*, brachten sie ihn nach Jerusalem hinauf, um ihn dem Herrn darzustellen", footnotes: ["℘ 3Mo 12,4.6"] },
      { number: 23, text: "— wie im Gesetz des Herrn geschrieben steht: »Alle männliche Erstgeburt* soll dem Herrn heilig heißen*« —", footnotes: ["w. Alles Männliche, das den Mutterschoß öffnet", "℘ 2Mo 13,2"] },
      { number: 24, text: "und ein Schlachtopfer zu geben nach dem, was im Gesetz des Herrn gesagt ist: ein Paar Turteltauben oder zwei junge Tauben*.", footnotes: ["℘ 3Mo 12,8; Gal 4,4"] },
      { number: 25, text: "Und siehe, es war in Jerusalem ein Mensch, mit Namen Simeon; und dieser Mensch war gerecht und gottesfürchtig und wartete auf den Trost Israels*; und der Heilige Geist war auf ihm*.", footnotes: ["℘ V. 38; Jes 40,1; 49,13; 52,9", "℘ Kap. 1,15"] },
      { number: 26, text: "Und ihm war von dem Heiligen Geist eine göttliche Zusage zuteilgeworden*, dass er den Tod nicht sehen solle, ehe er den Christus des Herrn gesehen habe.", footnotes: ["o. vom Heiligen Geist offenbart worden"] },
      { number: 27, text: "Und er kam durch den Geist in den Tempel. Und als die Eltern das Kind Jesus hereinbrachten, um mit ihm nach der Gewohnheit des Gesetzes zu tun," },
      { number: 28, text: "da nahm auch er es in seine Arme und lobte Gott und sprach:" },
      { number: 29, text: "Nun, Herr, entlässt du deinen Knecht* nach deinem Wort in Frieden*;", footnotes: ["w. Sklaven", "℘ 1Mo 46,30"] },
      { number: 30, text: "denn meine Augen haben dein Heil* gesehen*,", footnotes: ["o. deine Rettung", "℘ Kap. 1,69"] },
      { number: 31, text: "das du bereitet hast im Angesicht aller Völker*:", footnotes: ["℘ Jes 52,10"] },
      { number: 32, text: "ein Licht* zur Offenbarung für die Nationen* und zur Herrlichkeit deines Volkes Israel*.", footnotes: ["℘ Kap. 1,79; Apg 26,23", "℘ Jes 42,6; Apg 13,47", "℘ Jes 46,13; 60,19; Zef 3,14-20"] },
      { number: 33, text: "Und sein Vater und seine Mutter wunderten sich über das, was über ihn geredet wurde." },
      { number: 34, text: "Und Simeon segnete sie und sprach zu Maria, seiner Mutter: Siehe, dieser ist gesetzt zum Fall und Aufstehen vieler in Israel* und zu einem Zeichen, dem widersprochen wird*", footnotes: ["℘ Jes 8,14.15; Röm 9,32.33", "℘ Hebr 12,3"] },
      { number: 35, text: "— aber auch deine eigene Seele wird ein Schwert durchdringen —, damit Überlegungen aus vielen Herzen offenbar werden." },
      { number: 36, text: "Und es war eine Prophetin Hanna, eine Tochter Phanuëls, aus dem Stamm Asser. Diese war in ihren Tagen weit vorgerückt; sie hatte sieben Jahre mit ihrem Mann gelebt von ihrer Jungfrauschaft an;" },
      { number: 37, text: "und sie war eine Witwe von vierundachtzig Jahren, die wich nicht vom Tempel und diente <Gott> Nacht und Tag mit Fasten und Flehen*.", footnotes: ["℘ 1Tim 5,5"] },
      { number: 38, text: "Und sie trat zur selben Stunde herbei, lobte Gott und redete von ihm zu allen, die auf die Erlösung Jerusalems warteten*.", footnotes: ["℘ V. 25; Kap. 24,21"] },
      { number: 39, text: "Und als sie alles vollendet hatten nach dem Gesetz des Herrn, kehrten sie nach Galiläa zurück in ihre Stadt Nazareth*.", heading: "Rückkehr nach Nazareth — Als Zwölfjähriger im Tempel", footnotes: ["℘ Kap. 1,26 ⇨Esyn: Synopse Nr. 11"] },
      { number: 40, text: "Das Kind aber wuchs und erstarkte, erfüllt mit Weisheit, und Gottes Gnade war auf ihm*.", footnotes: ["℘ V. 52; Kap. 1,80; Jes 11,2"] },
      { number: 41, text: "Und seine Eltern gingen alljährlich am Passahfest nach Jerusalem*.", footnotes: ["℘ 2Mo 23,14.15; Joh 2,13 ⇨Esyn: Synopse Nr. 12"] },
      { number: 42, text: "Und als er zwölf Jahre alt war, gingen sie hinauf nach der Gewohnheit des Festes;" },
      { number: 43, text: "und als sie die Tage vollendet hatten*, blieb bei ihrer Rückkehr der Knabe Jesus in Jerusalem zurück, und seine Eltern wussten es nicht.", footnotes: ["℘ 2Mo 12,18"] },
      { number: 44, text: "Da sie aber meinten, er sei unter der Reisegesellschaft, kamen sie eine Tagereise* weit und suchten ihn unter den Verwandten und Bekannten;", footnotes: ["d. h. 7—8 Stunden Fußweg"] },
      { number: 45, text: "und als sie ihn nicht fanden, kehrten sie nach Jerusalem zurück und suchten ihn." },
      { number: 46, text: "Und es geschah, dass sie ihn nach drei Tagen im Tempel fanden, wie er inmitten der Lehrer saß und ihnen zuhörte und sie befragte." },
      { number: 47, text: "Alle aber, die ihn hörten, gerieten außer sich über sein Verständnis und seine Antworten*.", footnotes: ["℘ Kap. 4,22.32; Ps 119,99; Joh 7,15"] },
      { number: 48, text: "Und als sie ihn sahen, wurden sie bestürzt; und seine Mutter sprach zu ihm: Kind, warum hast du uns das getan? Siehe, dein Vater und ich haben dich mit Schmerzen gesucht." },
      { number: 49, text: "Und er sprach zu ihnen: Was <ist der Grund dafür>, dass ihr mich gesucht habt? Wusstet ihr nicht, dass ich in dem sein muss, was meines Vaters ist*?", footnotes: ["℘ Ps 26,8; Joh 2,16"] },
      { number: 50, text: "Und sie verstanden das Wort nicht, das er zu ihnen redete*.", footnotes: ["℘ Kap. 9,45; 18,34"] },
      { number: 51, text: "Und er ging mit ihnen hinab und kam nach Nazareth*, und er war ihnen untertan*. Und seine Mutter bewahrte alle diese Worte in ihrem Herzen*.", footnotes: ["℘ Kap. 1,26", "℘ Eph 6,1.2", "℘ V. 19"] },
      { number: 52, text: "Und Jesus nahm zu an Weisheit und Alter und Gunst bei Gott und Menschen*.", footnotes: ["℘ V. 40; 1Sam 2,26; Spr 3,4"] },
    ]},
    { number: 3, verses: [
      { number: 1, text: "*Aber im fünfzehnten Jahr der Regierung des Kaisers Tiberius, als Pontius Pilatus Statthalter von Judäa war* und Herodes* Vierfürst* von Galiläa* und sein Bruder Philippus* Vierfürst* von Ituräa und der Landschaft Trachonitis und Lysanias Vierfürst von Abilene*,", heading: "Johannes der Täufer", footnotes: ["℘ Mt 3,1-12; Mk 1,1-8; (Joh 1,19-28)", "Tiberius war Kaiser von 14—37 n. Chr., Pilatus kaiserlicher Statthalter von 26—36 n. Chr. in Judäa und Samaria.", "Herodes Antipas, Sohn Herodes' d. Gr., unter röm. Oberherrschaft Fürst von Galiläa und Peräa (4 v. Chr. bis 39 n. Chr.).", "griech. Tetrarch; ursprünglich Titel eines Fürsten, der über den vierten Teil eines Reiches regierte, später überhaupt für Fürsten geringerer Bedeutung verwendet", "℘ Kap. 23,6.7; Mt 14,1", "jüngster Sohn Herodes' d. Gr., unter röm. Oberherrschaft Fürst in Nordostpalästina, Gründer von Cäsarea Philippi, verheiratet mit der Tochter der Herodias (vgl. Mt 14,1—12)\n℘ Mt 14,3 ⇨Esyn: Synopse Nr. 13", "jüngster Sohn Herodes' d. Gr., unter röm. Oberherrschaft Fürst in Nordostpalästina, Gründer von Cäsarea Philippi, verheiratet mit der Tochter der Herodias (vgl. Mt 14,1—12)", "Landschaft in Syrien"] },
      { number: 2, text: "unter dem Hohenpriester Hannas und Kaiphas*, geschah das Wort Gottes zu Johannes, dem Sohn des Zacharias*, in der Wüste*.", footnotes: ["℘ Mt 26,3; Joh 11,49; Apg 4,6", "℘ Kap. 1,13", "℘ Kap. 1,80 ⇨Esyn: Synopse Nr. 32"] },
      { number: 3, text: "Und er kam in die ganze Landschaft am Jordan und predigte die Taufe der Buße zur Vergebung der Sünden*;", footnotes: ["℘ Kap. 1,77; Apg 10,37"] },
      { number: 4, text: "wie geschrieben steht im Buch der Worte Jesajas, des Propheten: »Stimme eines Rufenden in der Wüste: Bereitet den Weg des Herrn, macht seine Pfade gerade*!", footnotes: ["℘ Kap. 1,76"] },
      { number: 5, text: "Jedes Tal wird ausgefüllt und jeder Berg und Hügel erniedrigt werden, und das Krumme wird zum geraden <Weg> und die holperigen zu ebenen Wegen werden*;", footnotes: ["℘ Jes 49,11"] },
      { number: 6, text: "und alles Fleisch wird das Heil* Gottes sehen*.«", footnotes: ["o. die Rettung", "℘ Kap. 1,69; Ps 98,3; Jes 40,3-5; Tit 2,11"] },
      { number: 7, text: "Er sprach nun zu den Volksmengen, die hinausgingen, um von ihm getauft zu werden: Otternbrut! Wer hat euch gewiesen, dem kommenden Zorn zu entfliehen*?*", footnotes: ["o. Wer hat euch gezeigt, dass ihr dem kommenden Zorn entfliehen werdet", "℘ Mt 23,33 ⇨Esyn: Synopse Nr. 14"] },
      { number: 8, text: "Bringt nun der Buße würdige Früchte*; und beginnt nicht bei euch selbst zu sagen: Wir haben Abraham zum Vater*! Denn ich sage euch, dass Gott dem Abraham aus diesen Steinen Kinder zu erwecken vermag.", footnotes: ["℘ Apg 26,20", "℘ Joh 8,39"] },
      { number: 9, text: "Schon ist aber die Axt an die Wurzel der Bäume gelegt, jeder Baum nun, der nicht gute Frucht bringt, wird abgehauen und ins Feuer geworfen*.", footnotes: ["℘ Mt 7,19"] },
      { number: 10, text: "Und die Volksmengen fragten ihn und sprachen: Was sollen wir denn tun*?", footnotes: ["℘ Apg 2,37 ⇨Esyn: Synopse Nr. 15"] },
      { number: 11, text: "Er aber antwortete und sprach zu ihnen: Wer zwei Unterkleider hat, gebe dem ab, der keins hat; und wer Speise hat, tue ebenso!" },
      { number: 12, text: "Es kamen aber auch Zöllner, um getauft zu werden*; und sie sprachen zu ihm: Lehrer, was sollen wir tun*?", footnotes: ["℘ Kap. 7,29", "℘ Apg 2,37"] },
      { number: 13, text: "Er aber sprach zu ihnen: Fordert nicht mehr, als euch bestimmt ist!" },
      { number: 14, text: "Es fragten ihn aber auch Soldaten und sprachen: Und wir, was sollen wir tun? Und er sprach zu ihnen: Tut niemand Gewalt, und erpresst niemanden, und begnügt euch mit eurem Sold*!", footnotes: ["℘ 1Tim 6,8"] },
      { number: 15, text: "Als aber das Volk in Erwartung war und alle in ihren Herzen wegen Johannes überlegten, ob er nicht etwa der Christus sei, *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 16"] },
      { number: 16, text: "antwortete Johannes allen und sprach: Ich zwar taufe euch mit* Wasser; es kommt aber ein Stärkerer als ich, und ich bin nicht würdig, <ihm> den Riemen seiner Sandalen zu lösen*; er wird euch mit Heiligem Geist* und Feuer taufen.", footnotes: ["o. in", "℘ Joh 1,27", "℘ Apg 1,5"] },
      { number: 17, text: "Seine Worfschaufel ist in seiner Hand, seine Tenne zu reinigen und den Weizen in seine Scheune zu sammeln; die Spreu aber wird er verbrennen mit unauslöschlichem Feuer." },
      { number: 18, text: "Indem er <es> nun auch mit vielem anderen ermahnte, verkündigte er dem Volk gute Botschaft*.", footnotes: ["℘ Joh 3,27-36"] },
      { number: 19, text: "*Herodes aber, der Vierfürst, der von ihm zurechtgewiesen wurde wegen der Herodias*, der Frau seines Bruders*, und wegen alles Bösen, das Herodes getan hatte, *", footnotes: ["℘ Mt 14,3-5; Mk 6,17-20", "Enkeltochter Herodes' d. Gr. und Stiefnichte ihrer beiden Ehegatten; s. Anm. zu Mt 14,3", "Gemeint ist Herodes Philippus, Sohn Herodes' d. Gr.; s. Anm. zu Mt 14,3.", "℘ ⇨Esyn: Synopse Nr. 17"] },
      { number: 20, text: "fügte allem auch dies hinzu, dass er Johannes ins Gefängnis einschloss*.", footnotes: ["℘ Mt 11,2; Joh 3,24"] },
      { number: 21, text: "*Es geschah aber, als das ganze Volk getauft wurde und Jesus getauft war und betete, dass der Himmel geöffnet wurde *", heading: "Die Taufe Jesu", footnotes: ["℘ Mt 3,13-17; Mk 1,9-11; Joh 1,29-34", "℘ ⇨Esyn: Synopse Nr. 18"] },
      { number: 22, text: "und der Heilige Geist in leiblicher Gestalt wie eine Taube auf ihn herabstieg und eine Stimme aus dem Himmel kam: Du bist mein geliebter Sohn*, an dir habe ich Wohlgefallen gefunden*.", footnotes: ["℘ Kap. 1,35", "℘ Mt 12,18 ⇨Esyn: Synopse Nr. 302"] },
      { number: 23, text: "*Und er selbst, Jesus, war ungefähr dreißig Jahre alt, als er auftrat*, und war, wie man meinte, ein Sohn des Josef*, des Eli,", heading: "Der Stammbaum Jesu", footnotes: ["℘ 1Mo 5; 11,10-26; 1Chr 1,1-4.24-28.34; 2,1-15; Mt 1,1-16", "w. als er anfing", "℘ Kap. 1,27; Joh 1,45 ⇨Esyn: Synopse Nr. 19"] },
      { number: 24, text: "des Mattat, des Levi, des Melchi, des Jannai, des Josef," },
      { number: 25, text: "des Mattitja, des Amos, des Nahum, des Hesli, des Naggai," },
      { number: 26, text: "des Mahat, des Mattitja, des Schimi, des Josech, des Joda," },
      { number: 27, text: "des Johanan, des Resa, des Serubbabel, des Schealtiël*, des Neri,", footnotes: ["℘ 1Chr 3,17; Esr 3,2"] },
      { number: 28, text: "des Melchi, des Addi, des Kosam, des Elmadam, des Er," },
      { number: 29, text: "des Joschua, des Eliëser, des Jorim, des Mattat, des Levi," },
      { number: 30, text: "des Simeon, des Juda, des Josef, des Jonam, des Eljakim," },
      { number: 31, text: "des Melea, des Menna, des Mattata, des Nathan*, des David*,", footnotes: ["℘ 2Sam 5,14", "℘ 1Sam 16,13"] },
      { number: 32, text: "des Isai*, des Obed, des Boas, des Salma, des Nachschon*,", footnotes: ["℘ 1Sam 16,1", "℘ 4Mo 1,7"] },
      { number: 33, text: "des Amminadab*, des Admin, des Arni, des Hezron, des Perez*, des Juda*,", footnotes: ["℘ 4Mo 2,3", "℘ 1Mo 38,29; 46,12; Rt 4,17-22; 1Chr 4,1", "℘ 1Mo 29,35"] },
      { number: 34, text: "des Jakob*, des Isaak*, des Abraham*, des Terach, des Nahor,", footnotes: ["℘ 1Mo 25,26", "℘ 1Mo 17,19; 21,3", "℘ 1Mo 17,5; Neh 9,7"] },
      { number: 35, text: "des Serug, des Regu, des Peleg, des Eber, des Schelach," },
      { number: 36, text: "des Kenan, des Arpachschad, des Sem, des Noah, des Lamech," },
      { number: 37, text: "des Metuschelach, des Henoch, des Jered, des Mahalalel, des Kenan," },
      { number: 38, text: "des Enosch, des Set*, des Adam, des Gottes*.", footnotes: ["℘ 1Mo 4,25.26", "℘ 1Mo 1,27; 2,7"] },
    ]},
    { number: 4, verses: [
      { number: 1, text: "*Jesus aber, voll Heiligen Geistes, kehrte vom Jordan zurück und wurde durch den Geist in der Wüste vierzig Tage umhergeführt*", heading: "Die Versuchung Jesu", footnotes: ["℘ Mt 4,1-11; Mk 1,12.13", "℘ 5Mo 9,9 ⇨Esyn: Synopse Nr. 20"] },
      { number: 2, text: "und von dem Teufel versucht. Und er aß in jenen Tagen nichts; und als sie zu Ende waren, hungerte ihn*.", footnotes: ["℘ Mt 21,18"] },
      { number: 3, text: "Und der Teufel sprach zu ihm: Wenn du Gottes Sohn bist, so sprich zu diesem Stein, dass er Brot werde." },
      { number: 4, text: "Und Jesus antwortete ihm: Es steht geschrieben: »Nicht vom Brot allein soll der Mensch leben*.«", footnotes: ["℘ 5Mo 8,3\nAndere Handschr. fügen hinzu: sondern von jedem Wort Gottes"] },
      { number: 5, text: "Und er führte ihn auf einen hohen Berg und zeigte ihm in einem Augenblick alle Reiche* des Erdkreises.", footnotes: ["o. Königsherrschaften"] },
      { number: 6, text: "Und der Teufel sprach zu ihm: Dir will ich alle diese Macht und ihre Herrlichkeit geben; denn mir ist sie übergeben, und wem immer ich will, gebe ich sie*.", footnotes: ["℘ Offb 13,2"] },
      { number: 7, text: "Wenn du nun vor mir anbeten willst, soll das alles dein sein." },
      { number: 8, text: "Und Jesus antwortete ihm und sprach: Es steht geschrieben: »Du sollst den Herrn, deinen Gott, anbeten und ihm allein dienen*.«", footnotes: ["℘ 5Mo 6,13; Offb 19,10"] },
      { number: 9, text: "Und er führte ihn nach Jerusalem und stellte ihn auf die Zinne des Tempels und sprach zu ihm: Wenn du Gottes Sohn bist, so wirf dich von hier hinab;" },
      { number: 10, text: "denn es steht geschrieben: »Er wird seinen Engeln über dir befehlen, dass sie dich bewahren;" },
      { number: 11, text: "und sie werden dich auf den Händen tragen, damit du nicht etwa deinen Fuß an einen Stein stößt*.«", footnotes: ["℘ Ps 91,11.12"] },
      { number: 12, text: "Und Jesus antwortete und sprach zu ihm: Es ist gesagt: »Du sollst den Herrn, deinen Gott, nicht versuchen*.«", footnotes: ["℘ 5Mo 6,16"] },
      { number: 13, text: "Und als der Teufel jede Versuchung vollendet hatte, wich er für eine Zeit von ihm." },
      { number: 14, text: "*Und Jesus kehrte in der Kraft des Geistes nach Galiläa zurück*, und die Kunde von ihm ging hinaus durch die ganze Umgegend.", heading: "Unglaube in Nazareth", footnotes: ["℘ V. 14.15: Mt 4,12-17; Mk 1,14.15; V. 16-30: vgl. Mt 13,54-58; Mk 6,1-6", "℘ Joh 4,3.43 ⇨Esyn: Synopse Nr. 32"] },
      { number: 15, text: "Und er lehrte in ihren Synagogen*, geehrt von allen.", footnotes: ["Versammlungsstätten der jüdischen Gemeinde; s. auch Anm. zu Mt 4,23\n℘ V. 44; Mt 4,23"] },
      { number: 16, text: "Und er kam nach Nazareth, wo er erzogen worden war*; und er ging nach seiner Gewohnheit am Sabbattag in die Synagoge und stand auf, um vorzulesen*.", footnotes: ["℘ Mt 2,23", "℘ Apg 13,15 ⇨Esyn: Synopse Nr. 33"] },
      { number: 17, text: "Und es wurde ihm das Buch des Propheten Jesaja gereicht; und als er das Buch aufgerollt hatte, fand er die Stelle, wo geschrieben war:" },
      { number: 18, text: "»Der Geist des Herrn ist auf mir, weil er mich gesalbt hat*, Armen gute Botschaft zu verkündigen*; er hat mich gesandt*, Gefangenen Freiheit* auszurufen* und Blinden, dass sie wieder sehen, Zerschlagene in Freiheit* hinzusenden*,", footnotes: ["℘ Apg 4,27", "℘ Kap. 6,20; 7,22; Mt 11,5", "℘ V. 43; Joh 5,36", "w. Freilassung, Erlass <der Schuld>", "℘ Jes 49,9", "w. Freilassung, Erlass <der Schuld>", "℘ Jes 29,18; 42,7"] },
      { number: 19, text: "auszurufen ein angenehmes Jahr des Herrn.«*", footnotes: ["℘ 3Mo 25,10; Jes 61,1.2"] },
      { number: 20, text: "Und als er das Buch zugerollt hatte, gab er es dem Diener zurück und setzte sich; und aller Augen in der Synagoge waren auf ihn gerichtet." },
      { number: 21, text: "Er fing aber an, zu ihnen zu sagen: Heute ist diese Schrift vor euren Ohren erfüllt." },
      { number: 22, text: "Und alle gaben ihm Zeugnis und wunderten sich über die Worte der Gnade, die aus seinem Mund hervorgingen*; und sie sprachen: Ist dieser nicht der Sohn Josefs*?", footnotes: ["℘ V. 32; Kap. 2,47; Eph 4,29", "℘ Kap. 1,27; Joh 6,42 ⇨Esyn: Synopse Nr. 240"] },
      { number: 23, text: "Und er sprach zu ihnen: Ihr werdet jedenfalls dieses Sprichwort* zu mir sagen: Arzt, heile dich selbst! Alles, was wir gehört haben, <dass es> in Kapernaum geschehen <sei>, tu auch hier in deiner Vaterstadt!", footnotes: ["w. Gleichnis"] },
      { number: 24, text: "Er sprach aber: Wahrlich, ich sage euch, dass kein Prophet in seiner Vaterstadt angenehm ist*.", footnotes: ["℘ Joh 4,44"] },
      { number: 25, text: "In Wahrheit aber sage ich euch: Viele Witwen waren in den Tagen Elias in Israel, als der Himmel drei Jahre und sechs Monate verschlossen war, so dass eine große Hungersnot über das ganze Land kam*;", footnotes: ["℘ 1Kö 17,1; 18,2; Jak 5,17"] },
      { number: 26, text: "und zu keiner von ihnen wurde Elia gesandt als nur nach Sarepta in Sidon zu einer Frau, einer Witwe*.", footnotes: ["℘ 1Kö 17,9"] },
      { number: 27, text: "Und viele Aussätzige* waren zur Zeit des Propheten Elisa in Israel*, und keiner von ihnen wurde gereinigt als nur Naaman, der Syrer*.", footnotes: ["»Aussatz« umfasste in bibl. Zeit mehrere Hautkrankheiten; s. auch Anm. zu Mt 8,2", "℘ 2Kö 7,3", "℘ 2Kö 5,14"] },
      { number: 28, text: "Und alle in der Synagoge wurden von Wut erfüllt, als sie dies hörten." },
      { number: 29, text: "Und sie standen auf und stießen ihn zur Stadt hinaus und führten ihn bis an den Rand des Berges, auf dem ihre Stadt erbaut war, um ihn so hinabzustürzen." },
      { number: 30, text: "Er aber schritt durch ihre Mitte hindurch und ging weg*.", footnotes: ["℘ Joh 8,20"] },
      { number: 31, text: "*Und er kam nach Kapernaum hinab*, einer Stadt in Galiläa, und lehrte sie an den Sabbaten*.", heading: "Heilung eines Besessenen", footnotes: ["℘ Mk 1,21-28", "℘ Joh 2,12", "℘ Kap. 6,6; 13,10 ⇨Esyn: Synopse Nr. 35"] },
      { number: 32, text: "Und sie erstaunten sehr über seine Lehre*, denn sein Wort war mit Vollmacht*.", footnotes: ["℘ V. 22", "℘ Kap. 24,19; Jer 23,29"] },
      { number: 33, text: "Und es war in der Synagoge ein Mensch, der einen Geist eines unreinen Dämons hatte, und er schrie auf mit lauter Stimme *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 36"] },
      { number: 34, text: "und sprach: Ach, was haben wir mit dir zu schaffen, Jesus, Nazarener? Bist du gekommen, uns zu verderben*? Ich kenne dich, wer du bist: der Heilige Gottes*.", footnotes: ["℘ Kap. 8,28", "℘ Kap. 1,35"] },
      { number: 35, text: "Und Jesus bedrohte ihn und sprach: Verstumme und fahre aus von ihm! Und als der Dämon ihn mitten unter sie geworfen hatte, fuhr er von ihm aus*, ohne ihm Schaden zu tun.", footnotes: ["℘ Mt 8,16"] },
      { number: 36, text: "Und Entsetzen kam über alle, und sie redeten untereinander und sprachen: Was ist dies für ein Wort? Denn mit Vollmacht und Kraft gebietet er den unreinen Geistern, und sie fahren aus." },
      { number: 37, text: "Und die Kunde von ihm ging hinaus in jeden Ort der Umgegend." },
      { number: 38, text: "*Er machte sich aber auf von der Synagoge und kam in das Haus Simons. Die Schwiegermutter des Simon aber war von einem starken Fieber befallen, und sie baten ihn für sie. *", heading: "Heilung der Schwiegermutter des Petrus", footnotes: ["℘ Mt 8,14.15; Mk 1,29-31", "℘ ⇨Esyn: Synopse Nr. 37"] },
      { number: 39, text: "Und er beugte sich über sie, bedrohte das Fieber, und es verließ sie; sie aber stand sogleich auf und diente ihnen." },
      { number: 40, text: "*Als aber die Sonne unterging, brachten alle, die an mancherlei Krankheiten Leidende hatten, sie zu ihm; er aber legte jedem von ihnen die Hände auf und heilte sie*.", heading: "Heilungen und Predigt", footnotes: ["℘ Mt 4,23-25; 8,16.17; Mk 1,32-39", "℘ Kap. 13,13; Mk 8,23.25 ⇨Esyn: Synopse Nr. 38"] },
      { number: 41, text: "Und auch Dämonen fuhren von vielen aus, indem sie schrien und sprachen: Du bist der Sohn Gottes*. Und er bedrohte sie und ließ sie nicht reden, weil sie wussten, dass er der Christus war*.", footnotes: ["℘ Kap. 1,35; Mt 8,29", "℘ Mk 3,11.12 ⇨Esyn: Synopse Nr. 113"] },
      { number: 42, text: "Als es aber Tag geworden war, ging er hinaus und begab sich an einen einsamen Ort; und die Volksmengen suchten ihn auf und kamen bis zu ihm, und sie hielten ihn auf, dass er nicht von ihnen ginge. *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 39"] },
      { number: 43, text: "Er aber sprach zu ihnen: Ich muss auch den anderen Städten die gute Botschaft vom Reich* Gottes verkündigen*, denn dazu bin ich gesandt worden*.", footnotes: ["o. von der Königsherrschaft", "o. das Reich Gottes <als Evangelium> verkündigen", "℘ V. 18; Kap. 8,1"] },
      { number: 44, text: "Und er predigte in den Synagogen von Galiläa*.", footnotes: ["Nach anderen alten Handschr.: Judäa\n℘ V. 15 ⇨Esyn: Synopse Nr. 40"] },
    ]},
    { number: 5, verses: [
      { number: 1, text: "*Es geschah aber, als die Volksmenge auf ihn andrängte, um das Wort Gottes zu hören, dass er an dem See Genezareth stand*.", heading: "Fischzug des Petrus — Die ersten Jünger", footnotes: ["℘ Mt 4,18-22; Mk 1,16-20", "℘ Kap. 12,1; Mk 2,2 ⇨Esyn: Synopse Nr. 41"] },
      { number: 2, text: "Und er sah zwei Boote am See liegen; die Fischer aber waren aus ihnen ausgestiegen und wuschen die Netze." },
      { number: 3, text: "Er aber stieg in eins der Boote, das Simon gehörte, und bat ihn, ein wenig vom Land hinauszufahren; und er setzte sich und lehrte die Volksmengen vom Boot aus*.", footnotes: ["℘ Mt 13,2"] },
      { number: 4, text: "Als er aber aufhörte zu reden, sprach er zu Simon: Fahre hinaus auf die Tiefe, und lasst eure Netze zu einem Fang hinab*!", footnotes: ["℘ Joh 21,6"] },
      { number: 5, text: "Und Simon antwortete und sprach zu ihm: Meister, wir haben uns die ganze Nacht hindurch bemüht und nichts gefangen*, aber auf dein Wort will ich die Netze hinablassen.", footnotes: ["℘ Joh 21,3"] },
      { number: 6, text: "Und als sie dies getan hatten, umschlossen sie eine große Menge Fische*, und ihre Netze rissen.", footnotes: ["℘ Joh 21,6"] },
      { number: 7, text: "Und sie winkten ihren Gefährten in dem anderen Boot, dass sie kämen und ihnen hülfen; und sie kamen, und sie füllten beide Boote, so dass sie zu sinken drohten." },
      { number: 8, text: "Als aber Simon Petrus es sah, fiel er zu den Knien Jesu nieder und sprach: Geh von mir hinaus! Denn ich bin ein sündiger Mensch, Herr." },
      { number: 9, text: "Denn Entsetzen hatte ihn erfasst und alle, die bei ihm waren, über den Fischfang, den sie getan hatten;" },
      { number: 10, text: "ebenso aber auch Jakobus und Johannes, die Söhne des Zebedäus, die Gefährten* von Simon waren. Und Jesus sprach zu Simon: Fürchte dich nicht! Von nun an wirst du Menschen fangen.", footnotes: ["o. Teilhaber"] },
      { number: 11, text: "Und als sie die Boote ans Land gebracht hatten, verließen sie alles und folgten ihm nach*.", footnotes: ["℘ V. 28; Kap. 14,33; 18,28"] },
      { number: 12, text: "*Und es geschah, als er in einer der Städte war, siehe, da war ein Mann voller Aussatz*; und als er Jesus sah, fiel er auf sein Angesicht und bat ihn und sprach: Herr, wenn du willst, kannst du mich reinigen. *", heading: "Heilung eines Aussätzigen", footnotes: ["℘ Mt 8,1-4; Mk 1,40-45", "»Aussatz« umfasste in bibl. Zeit mehrere Hautkrankheiten; s. auch Anm. zu Mt 8,2", "℘ ⇨Esyn: Synopse Nr. 42"] },
      { number: 13, text: "Und er streckte die Hand aus, rührte ihn an und sprach: Ich will. Sei gereinigt! Und sogleich wich der Aussatz von ihm." },
      { number: 14, text: "Und er gebot ihm, es niemand zu sagen*: Geh aber hin und zeige dich dem Priester und opfere für deine Reinigung, wie Mose geboten hat, ihnen zum Zeugnis*!", footnotes: ["℘ Kap. 8,56; 9,21", "℘ Kap. 17,14"] },
      { number: 15, text: "Aber die Rede über ihn verbreitete sich umso mehr; und große Volksmengen versammelten sich, <ihn> zu hören und von ihren Krankheiten geheilt zu werden*.", footnotes: ["℘ Kap. 6,17; Mt 4,24.25"] },
      { number: 16, text: "Er aber zog sich zurück und war in einsamen Gegenden und betete*.", footnotes: ["℘ Kap. 6,12; 9,18.28; 11,1; Mt 14,23"] },
      { number: 17, text: "*Und es geschah an einem der Tage, dass er lehrte, und es saßen da Pharisäer* und Gesetzeslehrer, die aus jedem Dorf von Galiläa und Judäa und aus Jerusalem gekommen waren; und des Herrn Kraft war da, damit er heilte*.", heading: "Heilung eines Gelähmten", footnotes: ["℘ Mt 9,1-8; Mk 2,1-12", "religiöse Partei im Judentum, die auf genaue Einhaltung des Gesetzes Wert legte; s. auch Anm. zu Mt 3,7", "℘ Kap. 6,19; 8,46 ⇨Esyn: Synopse Nr. 43"] },
      { number: 18, text: "Und siehe, Männer bringen auf einem Bett einen Menschen, der gelähmt war*; und sie suchten ihn hineinzubringen und vor ihn zu legen.", footnotes: ["℘ Apg 9,33"] },
      { number: 19, text: "Und da sie nicht fanden, auf welchem <Weg> sie ihn hineinbringen sollten, wegen der Volksmenge, stiegen sie auf das Dach und ließen ihn durch die Ziegel hinab mit dem Bett in die Mitte vor Jesus." },
      { number: 20, text: "Und als er ihren Glauben sah*, sprach er: Mensch, deine Sünden sind dir vergeben*.", footnotes: ["℘ Jak 2,18", "℘ Kap. 7,48.49"] },
      { number: 21, text: "Und die Schriftgelehrten und die Pharisäer fingen an zu überlegen und sagten: Wer ist dieser, der <solche> Lästerungen redet? Wer kann Sünden vergeben außer Gott allein*?", footnotes: ["℘ Kap. 7,48.49"] },
      { number: 22, text: "Als aber Jesus ihre Überlegungen erkannte*, antwortete und sprach er zu ihnen: Was überlegt ihr in euren Herzen?", footnotes: ["℘ Kap. 6,8; 9,47; 11,17; 16,15; 1Chr 28,9"] },
      { number: 23, text: "Was ist leichter zu sagen: Dir sind deine Sünden vergeben, oder zu sagen: Steh auf und geh umher?" },
      { number: 24, text: "Damit ihr aber wisst, dass der Sohn des Menschen Vollmacht hat, auf der Erde Sünden zu vergeben — sprach er zu dem Gelähmten: Ich sage dir, steh auf und nimm dein Bett auf und geh nach Hause!" },
      { number: 25, text: "Und sogleich stand er vor ihnen auf, nahm auf, worauf er gelegen hatte, und ging hin in sein Haus* und verherrlichte Gott.", footnotes: ["℘ Apg 9,34"] },
      { number: 26, text: "Und Staunen ergriff alle, und sie verherrlichten Gott* und wurden mit Furcht erfüllt und sprachen: Wir haben heute außerordentliche Dinge gesehen.", footnotes: ["℘ Kap. 7,16; 17,15; 18,43; Apg 4,21"] },
      { number: 27, text: "*Und danach ging er hinaus und sah einen Zöllner, mit Namen Levi, am Zollhaus sitzen und sprach zu ihm: Folge mir nach*!", heading: "Berufung des Levi", footnotes: ["℘ Mt 9,9-13; Mk 2,13-17", "℘ Kap. 9,59; Joh 1,43 ⇨Esyn: Synopse Nr. 44"] },
      { number: 28, text: "Und er verließ alles, stand auf und folgte ihm nach*.", footnotes: ["℘ V. 11"] },
      { number: 29, text: "Und Levi machte ihm ein großes Mahl in seinem Haus; und <da> war eine große Menge von Zöllnern und anderen, die mit ihnen zu Tisch lagen." },
      { number: 30, text: "Und die Pharisäer und ihre Schriftgelehrten murrten gegen seine Jünger und sprachen: Warum esst und trinkt ihr mit den Zöllnern und Sündern*?", footnotes: ["℘ Kap. 7,34; 15,2; 19,7"] },
      { number: 31, text: "Und Jesus antwortete und sprach zu ihnen: Nicht die Gesunden brauchen einen Arzt, sondern die Kranken;" },
      { number: 32, text: "ich bin nicht gekommen, Gerechte zu rufen, sondern Sünder zur Buße*.", footnotes: ["℘ Kap. 15,7.10"] },
      { number: 33, text: "*Sie aber sprachen zu ihm: Die Jünger des Johannes fasten oft und verrichten Gebete, ebenso auch die der Pharisäer; die deinen aber essen und trinken! *", heading: "Die Frage nach dem Fasten", footnotes: ["℘ Mt 9,14-17; Mk 2,18-22", "℘ ⇨Esyn: Synopse Nr. 45"] },
      { number: 34, text: "Jesus aber sprach zu ihnen: Könnt ihr etwa die Hochzeitsgäste* fasten lassen, während der Bräutigam bei ihnen ist?", footnotes: ["w. Söhne des Brautgemachs; d. h. der dem Bräutigam am nächsten stehende unentbehrliche Teil der Hochzeitsgäste"] },
      { number: 35, text: "Es werden aber Tage kommen, und dann, wenn der Bräutigam von ihnen weggenommen sein wird, in jenen Tagen werden sie fasten." },
      { number: 36, text: "Er sagte aber auch ein Gleichnis zu ihnen: Niemand schneidet einen Flicken von einem neuen Gewand und setzt ihn auf ein altes Gewand; sonst wird er sowohl das neue zerschneiden, wie auch der Flicken von dem neuen zum alten nicht passen wird." },
      { number: 37, text: "Und niemand füllt neuen Wein in alte Schläuche; sonst wird der neue Wein die Schläuche zerreißen, und er selbst wird verschüttet werden, und die Schläuche werden verderben;" },
      { number: 38, text: "sondern neuen Wein füllt man in neue Schläuche." },
      { number: 39, text: "Und niemand will, wenn er alten getrunken hat, neuen, denn er spricht: Der alte ist milde." },
    ]},
    { number: 6, verses: [
      { number: 1, text: "*Und es geschah am Sabbat*, dass er durch die Saaten ging und seine Jünger die Ähren abpflückten und aßen, indem sie sie mit den Händen zerrieben*.", heading: "Die Sabbatfrage", footnotes: ["℘ Mt 12,1-14; Mk 2,23-3,6", "Viele Handschr. haben hier: am zweitersten Sabbat (d. i. wahrscheinlich der auf den Sabbat der Passahwoche folgende Sabbat)", "℘ 5Mo 23,26 ⇨Esyn: Synopse Nr. 46"] },
      { number: 2, text: "Einige der Pharisäer aber sprachen zu ihnen: Warum tut ihr, was am Sabbat nicht zu tun erlaubt ist?" },
      { number: 3, text: "Und Jesus antwortete und sprach zu ihnen: Habt ihr auch dieses nicht gelesen, was David tat, als ihn und die, die bei ihm waren, hungerte?" },
      { number: 4, text: "Wie er in das Haus Gottes ging und die Schaubrote nahm und aß und auch denen gab, die bei ihm waren — die doch außer den Priestern allein niemand essen darf*?", footnotes: ["℘ 1Sam 21,7"] },
      { number: 5, text: "Und er sprach zu ihnen: Der Sohn des Menschen ist Herr des Sabbats." },
      { number: 6, text: "Es geschah aber auch an einem anderen Sabbat, dass er in die Synagoge ging und lehrte*; und es war dort ein Mensch, dessen rechte Hand verdorrt war.", footnotes: ["℘ Kap. 4,31 ⇨Esyn: Synopse Nr. 47"] },
      { number: 7, text: "Die Schriftgelehrten und die Pharisäer aber lauerten darauf, ob er am Sabbat heilen würde*, damit sie eine Beschuldigung gegen ihn fänden*.", footnotes: ["℘ Kap. 13,14", "℘ Kap. 10,25; 11,54; 14,1; 20,20; Ps 37,32"] },
      { number: 8, text: "Er aber kannte ihre Überlegungen* und sprach zu dem Menschen, der die verdorrte Hand hatte: Steh auf und stelle dich in die Mitte! Er aber stand auf und stellte sich hin.", footnotes: ["℘ Kap. 5,22"] },
      { number: 9, text: "Jesus sprach nun zu ihnen: Ich frage euch, ob es erlaubt ist, am Sabbat Gutes zu tun oder Böses zu tun, Leben zu retten oder zu verderben*.", footnotes: ["℘ Kap. 13,15.16; 14,3"] },
      { number: 10, text: "Und nachdem er sie alle ringsum angeblickt hatte, sprach er zu ihm: Strecke deine Hand aus! Und er tat es; und seine Hand wurde wiederhergestellt*.", footnotes: ["℘ 1Kö 13,6"] },
      { number: 11, text: "Sie aber wurden mit Unverstand erfüllt und besprachen sich untereinander, was sie Jesus tun sollten*.", footnotes: ["℘ Joh 11,47; Apg 4,16"] },
      { number: 12, text: "*Und es geschah in diesen Tagen, dass er auf den Berg hinausging, um zu beten*; und er verbrachte die Nacht im Gebet zu Gott*.", heading: "Berufung der zwölf Apostel", footnotes: ["℘ Mt 10,1-4; Mk 3,13-19; (Apg 1,13)", "℘ Kap. 5,16", "℘ Ps 109,4 ⇨Esyn: Synopse Nr. 49"] },
      { number: 13, text: "Und als es Tag wurde, rief er seine Jünger herbei und erwählte aus ihnen zwölf, die er auch Apostel* nannte*:", footnotes: ["d. h. Gesandte, o. Boten", "℘ Kap. 9,1; Apg 1,2"] },
      { number: 14, text: "Simon, den er auch Petrus nannte, und Andreas, seinen Bruder, und Jakobus und Johannes und Philippus und Bartholomäus *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 21"] },
      { number: 15, text: "und Matthäus und Thomas und Jakobus, des Alphäus' <Sohn>, und Simon, genannt Eiferer*,", footnotes: ["griech. zelotes, d. h. ein ehemaliger Anhänger der Zelotenpartei; die Zeloten wollten die römische Herrschaft mit Gewalt beseitigen; s. auch Anm. zu Mt 10,4"] },
      { number: 16, text: "und Judas, des Jakobus' <Sohn>*, und Judas Iskariot*, der <zum> Verräter wurde*.", footnotes: ["o. <Bruder>", "Der Beiname bedeutete wahrscheinlich »Mann aus Kariot« und diente viell. zur Unterscheidung von dem anderen Jünger namens Judas (vgl. Joh 14,22).", "℘ Kap. 22,4.48"] },
      { number: 17, text: "*Und als er mit ihnen herabgestiegen war, trat er auf einen ebenen Platz und eine große Schar seiner Jünger und eine große Menge des Volkes von ganz Judäa und Jerusalem und von der Seeküste von Tyrus und Sidon, *", heading: "Krankenheilungen", footnotes: ["℘ Mt 12,15-21; Mk 3,7-12", "℘ ⇨Esyn: Synopse Nr. 77"] },
      { number: 18, text: "die kamen, ihn zu hören und von ihren Krankheiten geheilt zu werden; und die von unreinen Geistern Geplagten wurden geheilt*.", footnotes: ["℘ Apg 10,38"] },
      { number: 19, text: "Und die ganze Volksmenge suchte ihn anzurühren, denn Kraft ging von ihm aus und heilte alle*.", footnotes: ["o. und er heilte alle\n℘ Kap. 5,17; Mt 9,21"] },
      { number: 20, text: "*Und er erhob seine Augen zu seinen Jüngern und sprach: Glückselig ihr Armen*, denn euer ist das Reich* Gottes*.", heading: "Seligpreisungen — Weherufe", footnotes: ["℘ Mt 5,1-12", "℘ Kap. 4,18", "o. die Königsherrschaft", "℘ Kap. 12,32; 22,29 ⇨Esyn: Synopse Nr. 78"] },
      { number: 21, text: "Glückselig, die ihr jetzt hungert, denn ihr werdet gesättigt werden. Glückselig, die ihr jetzt weint, denn ihr werdet lachen*.", footnotes: ["℘ Ps 126,5.6"] },
      { number: 22, text: "Glückselig seid ihr, wenn die Menschen euch hassen werden und wenn sie euch absondern und schmähen und euren Namen als böse verwerfen werden um des Sohnes des Menschen willen*.", footnotes: ["℘ Jes 66,5; Mt 10,22; 1Kor 4,13"] },
      { number: 23, text: "Freut euch* an jenem Tag und hüpft! Denn siehe, euer Lohn ist groß in dem Himmel; denn ebenso taten ihre Väter den Propheten*.", footnotes: ["℘ Apg 5,41", "℘ Mt 21,35"] },
      { number: 24, text: "Aber wehe euch Reichen! Denn ihr habt euren Trost dahin*.", footnotes: ["℘ Kap. 16,25; Jak 5,1 ⇨Esyn: Synopse Nr. 79"] },
      { number: 25, text: "Wehe euch, die ihr voll seid, denn ihr werdet hungern. Wehe euch, die ihr jetzt lacht, denn ihr werdet trauern und weinen*.", footnotes: ["℘ Jak 4,9"] },
      { number: 26, text: "Wehe, wenn alle Menschen gut von euch reden, denn ebenso taten ihre Väter den falschen Propheten*.", footnotes: ["℘ Jer 5,31; Mi 2,11"] },
      { number: 27, text: "*Aber euch, die ihr hört, sage ich: Liebt eure Feinde; tut wohl denen, die euch hassen*;", heading: "Rechtes Vergelten: Feindesliebe", footnotes: ["℘ Mt 5,38-48", "℘ 2Mo 23,4; Spr 25,21 ⇨Esyn: Synopse Nr. 80"] },
      { number: 28, text: "segnet, die euch fluchen*; betet für die, die euch beleidigen*!", footnotes: ["℘ 1Petr 3,9", "℘ Kap. 23,34"] },
      { number: 29, text: "Dem, der dich auf die Backe schlägt, biete auch die andere dar; und dem, der dir den Mantel nimmt, verweigere auch das Untergewand nicht*!", footnotes: ["℘ 1Kor 6,7"] },
      { number: 30, text: "Gib jedem, der dich bittet*; und von dem, der dir das Deine nimmt, fordere es nicht zurück!", footnotes: ["℘ 5Mo 15,7"] },
      { number: 31, text: "Und wie ihr wollt, dass euch die Menschen tun sollen, tut ihnen ebenso!*", footnotes: ["℘ Mt 7,12"] },
      { number: 32, text: "Und wenn ihr liebt, die euch lieben, was für einen Dank habt ihr? Denn auch die Sünder lieben, die sie lieben." },
      { number: 33, text: "Und wenn ihr denen Gutes tut, die euch Gutes tun, was für einen Dank habt ihr? Auch die Sünder tun dasselbe." },
      { number: 34, text: "Und wenn ihr denen leiht, von denen ihr <wieder> zu empfangen hofft, was für einen Dank habt ihr? Auch Sünder leihen Sündern, damit sie das Gleiche wieder empfangen*.", footnotes: ["℘ Kap. 14,12"] },
      { number: 35, text: "Doch liebt eure Feinde, und tut Gutes, und leiht, ohne etwas wieder zu erhoffen! Und euer Lohn wird groß sein*, und ihr werdet Söhne des Höchsten sein; denn er ist gütig gegen die Undankbaren und Bösen.", footnotes: ["℘ Kap. 14,14"] },
      { number: 36, text: "*Seid* nun barmherzig, wie auch euer Vater barmherzig ist*!", heading: "Warnung vor dem Richten", footnotes: ["℘ Mt 7,1-5.15-20", "o. Werdet", "℘ Jak 3,17"] },
      { number: 37, text: "Und richtet nicht, und ihr werdet nicht gerichtet werden; und verurteilt nicht, und ihr werdet nicht verurteilt werden. Lasst los, und ihr werdet losgelassen werden*.", footnotes: ["o. Sprecht frei, und ihr werdet freigesprochen werden\n℘ Mt 6,14 ⇨Esyn: Synopse Nr. 81"] },
      { number: 38, text: "Gebt, und es wird euch gegeben werden: ein gutes, gedrücktes und gerütteltes und überlaufendes Maß wird man in euren Schoß geben; denn mit demselben Maß, mit dem ihr messt, wird euch wieder gemessen werden*.", footnotes: ["℘ 2Kor 9,6"] },
      { number: 39, text: "Er sagte aber auch ein Gleichnis zu ihnen: Kann etwa ein Blinder einen Blinden leiten? Werden nicht beide in eine Grube fallen*?", footnotes: ["℘ Mt 15,14"] },
      { number: 40, text: "Ein Jünger ist nicht über dem Lehrer*; jeder aber, der vollendet* ist, wird sein wie sein Lehrer.", footnotes: ["℘ Mt 10,24 ⇨Esyn: Synopse Nr. 322", "o. zugerüstet"] },
      { number: 41, text: "Was aber siehst du den Splitter, der in deines Bruders Auge ist, den Balken aber, der in deinem eigenen Auge ist, nimmst du nicht wahr?" },
      { number: 42, text: "Wie kannst du zu deinem Bruder sagen: Bruder, erlaube, ich will den Splitter herausziehen, der in deinem Auge ist, während du selbst den Balken in deinem Auge nicht siehst? Heuchler, ziehe zuerst den Balken aus deinem Auge! Und dann wirst du klar sehen, um den Splitter herauszuziehen, der in deines Bruders Auge ist." },
      { number: 43, text: "Denn es gibt keinen guten Baum, der faule Frucht bringt, auch wieder keinen faulen Baum, der gute Frucht bringt*;", footnotes: ["℘ Mt 12,33 ⇨Esyn: Synopse Nr. 82"] },
      { number: 44, text: "denn jeder Baum wird an seiner eigenen Frucht erkannt; denn von Dornen sammelt man nicht Feigen, auch liest man von einem Dornbusch keine Trauben*.", footnotes: ["℘ Jak 3,12"] },
      { number: 45, text: "Der gute Mensch bringt aus dem guten Schatz seines Herzens das Gute hervor, und der böse bringt aus dem bösen das Böse hervor; denn aus der Fülle des Herzens redet sein Mund*.", footnotes: ["℘ Mt 12,34.35"] },
      { number: 46, text: "*Was nennt ihr mich aber: Herr, Herr!, und tut nicht, was ich sage*?", heading: "Gleichnis vom Haus auf dem Felsen", footnotes: ["℘ Mt 7,21-27", "℘ Mal 1,6; 1Jo 2,4 ⇨Esyn: Synopse Nr. 83"] },
      { number: 47, text: "Jeder, der zu mir kommt und meine Worte hört und sie tut — ich will euch zeigen, wem er gleich ist." },
      { number: 48, text: "Er ist einem Menschen gleich, der ein Haus baute, grub und vertiefte und den Grund auf den Felsen legte; als aber eine Flut kam, stieß der Strom an jenes Haus und konnte es nicht erschüttern, weil es gut gebaut war*.", footnotes: ["Nach anderen Handschr.: denn es war auf den Felsen gegründet"] },
      { number: 49, text: "Der aber gehört und nicht getan hat, ist einem Menschen gleich*, der ein Haus auf die Erde baute ohne Grundmauer; der Strom stieß daran, und sogleich fiel es, und der Sturz jenes Hauses war groß.", footnotes: ["℘ Jak 1,23"] },
    ]},
    { number: 7, verses: [
      { number: 1, text: "*Nachdem er aber alle seine Worte vor den Ohren des Volkes vollendet hatte, ging er hinein nach Kapernaum. *", heading: "Heilung des Dieners eines Hauptmanns", footnotes: ["℘ Mt 8,5-13; vgl. Joh 4,43-54", "℘ ⇨Esyn: Synopse Nr. 85"] },
      { number: 2, text: "Eines Hauptmanns Knecht* aber, der ihm wert war, war krank und lag im Sterben.", footnotes: ["w. Sklave; so auch V. 3 und 10"] },
      { number: 3, text: "Als er aber von Jesus hörte, sandte er Älteste der Juden zu ihm und bat ihn, dass er komme und seinen Knecht gesund mache." },
      { number: 4, text: "Als diese aber zu Jesus hinkamen, baten sie ihn inständig und sprachen: Er ist würdig, dass du ihm dies gewährst," },
      { number: 5, text: "denn er liebt unsere Nation, und er selbst hat uns die Synagoge erbaut*.", footnotes: ["℘ Apg 10,2"] },
      { number: 6, text: "Jesus aber ging mit ihnen. Als er aber schon nicht mehr weit von dem Haus entfernt war, sandte der Hauptmann Freunde zu ihm und ließ ihm sagen: Herr, bemühe dich nicht! Denn ich bin nicht würdig, dass du unter mein Dach trittst." },
      { number: 7, text: "Darum habe ich mich selbst auch nicht für würdig gehalten, zu dir zu kommen, sondern sprich ein Wort, und mein Diener wird* gesund werden.", footnotes: ["mit mehreren alten Handschr.: mein Diener soll"] },
      { number: 8, text: "Denn auch ich bin ein Mensch, der unter Befehlsgewalt* steht, und ich habe Soldaten unter mir; und ich sage zu diesem: Geh hin!, und er geht; und zu einem anderen: Komm!, und er kommt; und zu meinem Sklaven: Tu dies!, und er tut es.", footnotes: ["o. Macht, Vollmacht"] },
      { number: 9, text: "Als aber Jesus dies hörte, wunderte er sich über ihn; und er wandte sich zu der Volksmenge, die ihm folgte, und sprach: Ich sage euch, selbst nicht in Israel habe ich so großen Glauben gefunden." },
      { number: 10, text: "Und als die Abgesandten in das Haus zurückkehrten, fanden sie den Knecht gesund." },
      { number: 11, text: "Und es geschah bald darauf, dass er in eine Stadt ging, genannt Nain, und seine Jünger und eine große Volksmenge gingen mit ihm. *", heading: "Auferweckung des Jünglings von Nain", footnotes: ["℘ ⇨Esyn: Synopse Nr. 86"] },
      { number: 12, text: "Als er sich aber dem Tor der Stadt näherte, siehe, da wurde ein Toter herausgetragen, der einzige* Sohn seiner Mutter, und sie war eine Witwe*; und eine zahlreiche Volksmenge aus der Stadt war mit ihr.", footnotes: ["im Griech. dasselbe Wort wie »eingeboren« in Joh 1,14.18; s. Anm. dort\n℘ Kap. 8,42; 9,38; Sach 12,10", "℘ 1Kö 17,9.17"] },
      { number: 13, text: "Und als der Herr sie sah, wurde er innerlich bewegt* über sie und sprach zu ihr: Weine nicht*!", footnotes: ["℘ Kap. 10,33; 15,20; Mt 9,36", "℘ Kap. 8,52"] },
      { number: 14, text: "Und er trat hinzu und rührte die Bahre an, die Träger aber standen still; und er sprach: Jüngling, ich sage dir, steh auf*!", footnotes: ["℘ Kap. 8,54; Joh 11,43; Apg 9,40"] },
      { number: 15, text: "Und der Tote setzte sich auf* und fing an zu reden; und er gab ihn seiner Mutter*.", footnotes: ["℘ Kap. 8,55; Mt 9,25", "℘ 1Kö 17,23; 2Kö 4,36; Hebr 11,35"] },
      { number: 16, text: "Alle aber ergriff Furcht; und sie verherrlichten Gott* und sprachen: Ein großer Prophet ist unter uns erweckt worden*, und Gott hat sein Volk besucht*.", footnotes: ["℘ Kap. 5,26", "℘ Kap. 24,19; Mt 21,11; Joh 4,19", "℘ Kap. 1,65.68"] },
      { number: 17, text: "Und diese Rede über ihn ging hinaus in ganz Judäa und in der ganzen Umgegend*.", footnotes: ["℘ Mt 9,26"] },
      { number: 18, text: "*Und dem Johannes berichteten seine Jünger über dies alles. *", heading: "Die Frage des Täufers — Jesu Antwort und Zeugnis über ihn", footnotes: ["℘ Mt 11,2-19", "℘ ⇨Esyn: Synopse Nr. 106"] },
      { number: 19, text: "Und Johannes rief zwei seiner Jünger herbei und sandte sie zum Herrn und <ließ ihm> sagen: Bist du der Kommende, oder sollen wir auf einen anderen warten?" },
      { number: 20, text: "Als aber die Männer zu ihm gekommen waren, sprachen sie: Johannes der Täufer hat uns zu dir gesandt und lässt <dir> sagen: Bist du der Kommende, oder sollen wir auf einen anderen warten?" },
      { number: 21, text: "In jener Stunde aber heilte er viele von Krankheiten und Plagen und bösen Geistern, und vielen Blinden schenkte er das Augenlicht*.", footnotes: ["w. zu sehen"] },
      { number: 22, text: "Jesus antwortete und sprach zu ihnen: Geht hin und verkündet Johannes, was ihr gesehen und gehört habt: Blinde sehen wieder, Lahme gehen, Aussätzige* werden gereinigt, Taube hören, Tote werden auferweckt, Armen wird gute Botschaft verkündigt*!", footnotes: ["»Aussatz« umfasste in bibl. Zeit mehrere Hautkrankheiten; s. auch Anm. zu Mt 8,2", "℘ Kap. 4,18; Mt 15,30; Jak 2,5 ⇨Esyn: Synopse Nr. 211"] },
      { number: 23, text: "Und glückselig ist, wer sich nicht an mir ärgert*.", footnotes: ["»ärgern«, w. zur Sünde verleiten; sich an Jesus ärgern, d. h. Anstoß nehmen und sich von ihm abwenden"] },
      { number: 24, text: "Als aber die Boten des Johannes weggegangen waren, fing er an, zu den Volksmengen über Johannes zu reden: Was seid ihr in die Wüste hinausgegangen anzuschauen? Ein Rohr, vom Wind hin und her bewegt? *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 107"] },
      { number: 25, text: "Oder* was seid ihr hinausgegangen zu sehen? Einen Menschen, mit weichen Kleidern angetan*? Siehe, die in herrlicher Kleidung und in Üppigkeit leben, sind an den königlichen Höfen.", footnotes: ["w. Aber", "℘ Mt 3,4"] },
      { number: 26, text: "Oder* was seid ihr hinausgegangen zu sehen? Einen Propheten? Ja, sage ich euch, und mehr als einen Propheten.", footnotes: ["w. Aber"] },
      { number: 27, text: "Dieser ist es, von dem geschrieben steht: »Siehe, ich sende meinen Boten vor deinem Angesicht her, der deinen Weg vor dir bereiten wird*.«", footnotes: ["℘ Kap. 1,17; Mal 3,1 ⇨Esyn: Synopse Nr. 13"] },
      { number: 28, text: "Denn ich sage euch: Unter den von Frauen Geborenen ist kein Größerer als Johannes der Täufer*; aber der Kleinste in dem Reich* Gottes ist größer als er.", footnotes: ["℘ Kap. 1,15", "o. in der Königsherrschaft"] },
      { number: 29, text: "Und das ganze Volk, das zuhörte, und die Zöllner haben Gott recht gegeben*, indem sie sich mit der Taufe des Johannes taufen ließen*;", footnotes: ["w. rechtfertigten Gott", "w. mit der Taufe des Johannes getauft wurden\n℘ Kap. 3,7.12"] },
      { number: 30, text: "die Pharisäer aber und die Gesetzesgelehrten haben den Ratschluss Gottes für sich selbst wirkungslos gemacht*, indem sie sich nicht von ihm taufen ließen*.", footnotes: ["o. haben Gottes Ratschluss für sie verworfen", "w. nicht von ihm getauft wurden\n℘ Mt 21,32"] },
      { number: 31, text: "Wem soll ich nun die Menschen dieses Geschlechts vergleichen? Und wem sind sie gleich?" },
      { number: 32, text: "Sie sind Kindern gleich, die auf dem Markt sitzen und einander zurufen und sagen: Wir haben euch gepfiffen, und ihr habt nicht getanzt; wir haben euch Klagelieder gesungen, und ihr habt nicht geweint." },
      { number: 33, text: "Denn Johannes der Täufer ist gekommen, der weder Brot aß noch Wein trank, und ihr sagt: Er hat einen Dämon*.", footnotes: ["℘ Kap. 11,15; Joh 7,20"] },
      { number: 34, text: "Der Sohn des Menschen ist gekommen, der da isst und trinkt, und ihr sagt: Siehe, ein Fresser und Weinsäufer, ein Freund von Zöllnern und Sündern*;", footnotes: ["℘ Kap. 5,30"] },
      { number: 35, text: "— und die Weisheit ist gerechtfertigt worden von allen ihren Kindern*.", footnotes: ["℘ Hos 14,10"] },
      { number: 36, text: "Es bat ihn aber einer der Pharisäer, dass er mit ihm essen möge; und er ging in das Haus des Pharisäers und legte sich zu Tisch*.", heading: "Jesu Salbung durch eine Sünderin", footnotes: ["℘ Kap. 11,37; 14,1 ⇨Esyn: Synopse Nr. 114"] },
      { number: 37, text: "Und siehe, <da war> eine Frau in der Stadt, die eine Sünderin war; und als sie erfahren hatte, dass er in dem Haus des Pharisäers zu Tisch lag, brachte sie eine Alabasterflasche mit Salböl*,", footnotes: ["℘ Mt 26,7"] },
      { number: 38, text: "trat von hinten an seine Füße heran*, weinte und fing an, seine Füße mit Tränen zu benetzen, und trocknete sie mit den Haaren ihres Hauptes. <Dann> küsste sie seine Füße* und salbte sie mit dem Salböl*.", footnotes: ["Der Vorgang erklärt sich aus der damaligen Sitte, dass man zu Tisch zu liegen pflegte.", "o. küsste sie seine Füße zärtlich o. mehrfach", "℘ Joh 12,3"] },
      { number: 39, text: "Als aber der Pharisäer, der ihn eingeladen hatte, das sah, sprach er bei sich selbst und sagte: Wenn dieser ein Prophet wäre, so würde er erkennen, wer und was für eine Frau <das ist>, die ihn anrührt; denn sie ist eine Sünderin." },
      { number: 40, text: "Und Jesus antwortete und sprach zu ihm: Simon, ich habe dir etwas zu sagen. Er aber sagt: Lehrer, sprich! —" },
      { number: 41, text: "Ein Gläubiger hatte zwei Schuldner; der eine schuldete fünfhundert Denare, der andere aber fünfzig;" },
      { number: 42, text: "da sie aber nicht zahlen konnten, schenkte er es beiden. Wer nun von ihnen wird ihn am meisten lieben?" },
      { number: 43, text: "Simon aber antwortete und sprach: Ich nehme an, <der,> dem er das meiste geschenkt hat. Er aber sprach zu ihm: Du hast recht geurteilt." },
      { number: 44, text: "Und sich zu der Frau wendend, sprach er zu Simon: Siehst du diese Frau? Ich bin in dein Haus gekommen, du hast mir kein Wasser für meine Füße gegeben; sie aber hat meine Füße mit Tränen benetzt und mit ihren Haaren getrocknet." },
      { number: 45, text: "Du hast mir keinen Kuss gegeben; sie aber hat, seitdem ich hereingekommen bin, nicht abgelassen, meine Füße zu küssen*.", footnotes: ["o. zärtlich zu küssen"] },
      { number: 46, text: "Du hast mein Haupt nicht mit Öl gesalbt; sie aber hat mit Salböl meine Füße gesalbt." },
      { number: 47, text: "Deswegen sage ich dir: Ihre vielen Sünden sind vergeben, denn sie hat viel geliebt; wem aber wenig vergeben wird, der liebt wenig." },
      { number: 48, text: "Er aber sprach zu ihr: Deine Sünden sind vergeben*.", footnotes: ["℘ Kap. 5,20.21; Mk 2,5"] },
      { number: 49, text: "Und die, die mit zu Tisch lagen, fingen an, bei sich selbst zu sagen: Wer ist dieser, der auch Sünden vergibt*?", footnotes: ["℘ Kap. 5,20.21; Mk 2,5"] },
      { number: 50, text: "Er sprach aber zu der Frau: Dein Glaube hat dich gerettet. Geh hin in Frieden*!", footnotes: ["℘ Kap. 8,48; 17,19; 18,42; Eph 2,8"] },
    ]},
    { number: 8, verses: [
      { number: 1, text: "Und es geschah danach, dass er nacheinander Städte und Dörfer* durchzog*, indem er predigte und die gute Botschaft vom Reich* Gottes verkündigte*; und die Zwölf mit ihm,", heading: "Die Jüngerinnen Jesu", footnotes: ["w. Stadt und Dorf", "℘ Kap. 13,22", "o. von der Königsherrschaft", "o. das Reich Gottes <als Evangelium> verkündigte\n℘ Kap. 4,43; 9,2; Mt 9,35; Mk 1,14 ⇨Esyn: Synopse Nr. 115"] },
      { number: 2, text: "und einige Frauen, die von bösen Geistern und Krankheiten geheilt worden waren: Maria, genannt Magdalena*, von der sieben Dämonen ausgefahren waren*,", footnotes: ["d. h. die aus Magdala (Ort am See Genezareth)", "℘ V. 30; Mt 27,55.56; Mk 16,9"] },
      { number: 3, text: "und Johanna, die Frau des Chuza, des Verwalters Herodes', und Susanna und viele andere*, die ihnen* mit ihrer Habe dienten*.", footnotes: ["℘ Kap. 23,49.55; 24,10", "mit anderen Handschr.: ihm", "℘ Mk 1,31"] },
      { number: 4, text: "*Als sich aber eine große Volksmenge versammelte und sie aus jeder Stadt zu ihm hinkamen, sprach er in einem Gleichnis: *", heading: "Gleichnis vom Sämann", footnotes: ["℘ Mt 13,1-23; Mk 4,1-20", "℘ ⇨Esyn: Synopse Nr. 122"] },
      { number: 5, text: "Der Sämann ging hinaus, seinen Samen zu säen; und indem er säte, fiel einiges an den Weg, und es wurde zertreten, und die Vögel des Himmels fraßen es auf." },
      { number: 6, text: "Und anderes fiel auf den Felsen; und als es aufging, verdorrte es, weil es keine Feuchtigkeit hatte." },
      { number: 7, text: "Und anderes fiel mitten unter die Dornen; und indem die Dornen mit aufwuchsen, erstickten sie es." },
      { number: 8, text: "Und anderes fiel in die gute Erde und ging auf und brachte hundertfache Frucht. Als er dies sagte, rief er aus: Wer Ohren hat zu hören, der höre*!", footnotes: ["℘ Kap. 14,35"] },
      { number: 9, text: "Seine Jünger aber fragten ihn, was dieses Gleichnis bedeute. *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 303"] },
      { number: 10, text: "Er aber sprach: Euch ist es gegeben, die Geheimnisse des Reiches* Gottes zu wissen, den Übrigen aber in Gleichnissen, damit sie sehend nicht sehen und hörend nicht verstehen*.", footnotes: ["o. der Königsherrschaft", "℘ Joh 12,40 ⇨Esyn: Synopse Nr. 248"] },
      { number: 11, text: "Dies aber ist die Bedeutung des Gleichnisses*: Der Same ist das Wort Gottes*.", footnotes: ["w. Dies aber ist das Gleichnis", "℘ 1Petr 1,23 ⇨Esyn: Synopse Nr. 124"] },
      { number: 12, text: "Die aber an dem Weg sind die, welche hören; dann kommt der Teufel und nimmt das Wort von ihren Herzen weg, damit sie nicht glauben und gerettet werden." },
      { number: 13, text: "Die aber auf dem Felsen sind die, welche, wenn sie hören, das Wort mit Freuden aufnehmen; und diese haben keine Wurzel; für eine Zeit glauben sie, und in der Zeit der Versuchung fallen sie ab." },
      { number: 14, text: "Das aber unter die Dornen fiel, sind die, welche gehört haben und hingehen und durch Sorgen und Reichtum und Vergnügungen des Lebens erstickt werden und nichts zur Reife bringen." },
      { number: 15, text: "Das in der guten Erde aber sind die, welche in einem redlichen und guten Herzen das Wort, nachdem sie es gehört haben*, bewahren* und Frucht bringen* mit Ausharren*.", footnotes: ["℘ 1Thes 2,13", "℘ Ps 119,11", "℘ Joh 15,16", "℘ Hebr 10,36"] },
      { number: 16, text: "*Niemand aber, der eine Lampe angezündet hat, bedeckt sie mit einem Gefäß oder stellt sie unter ein Bett, sondern er stellt sie auf ein Lampengestell, damit die Hereinkommenden das Licht sehen*.", heading: "Gleichnis von der Lampe", footnotes: ["℘ Mk 4,21-25", "℘ Kap. 11,33 ⇨Esyn: Synopse Nr. 125"] },
      { number: 17, text: "Denn es ist nichts verborgen, was nicht offenbar werden wird, auch <ist> nichts geheim, was nicht bekannt wird und ans Licht kommt*.", footnotes: ["℘ Kap. 12,2 ⇨Esyn: Synopse Nr. 196"] },
      { number: 18, text: "Seht nun zu, wie ihr hört! Denn wer hat, dem wird gegeben werden, und wer nicht hat, von dem wird selbst, was er zu haben meint, genommen werden*.", footnotes: ["℘ Kap. 19,26"] },
      { number: 19, text: "*Es kamen aber seine Mutter und seine Brüder zu ihm; und sie konnten wegen der Volksmenge nicht zu ihm gelangen. *", heading: "Die wahren Verwandten Jesu", footnotes: ["℘ Mt 12,46-50; Mk 3,31-35", "℘ ⇨Esyn: Synopse Nr. 135"] },
      { number: 20, text: "Und es wurde ihm berichtet: Deine Mutter und deine Brüder stehen draußen und wollen dich sehen." },
      { number: 21, text: "Er aber antwortete und sprach zu ihnen: Meine Mutter und meine Brüder sind die, welche das Wort Gottes hören und tun*.", footnotes: ["℘ Kap. 11,28; Mt 7,24"] },
      { number: 22, text: "*Und es geschah an einem der Tage, dass er in ein Boot stieg, er und seine Jünger; und er sprach zu ihnen: Lasst uns übersetzen an das jenseitige Ufer des Sees. Und sie fuhren ab. *", heading: "Stillung des Sturms", footnotes: ["℘ Mt 8,23-27; Mk 4,35-41", "℘ ⇨Esyn: Synopse Nr. 136"] },
      { number: 23, text: "Während sie aber fuhren, schlief er ein. Und es fiel ein Sturmwind auf den See, und das Boot füllte sich* <mit Wasser>, und sie waren in Gefahr.", footnotes: ["w. und sie wurden voll"] },
      { number: 24, text: "Sie traten aber hinzu und weckten ihn auf und sprachen: Meister, Meister, wir kommen um! Er aber stand auf, bedrohte den Wind und das Gewoge des Wassers*; und sie legten sich, und es trat Stille ein.", footnotes: ["℘ Ps 107,6"] },
      { number: 25, text: "Er aber sprach zu ihnen: Wo ist euer Glaube? Erschrocken aber erstaunten sie und sagten zueinander: Wer ist denn dieser, dass er auch den Winden und dem Wasser gebietet und sie ihm gehorchen*?", footnotes: ["℘ Kap. 9,43"] },
      { number: 26, text: "*Und sie fuhren nach der Landschaft der Gerasener, die Galiläa gegenüberliegt. *", heading: "Heilung eines besessenen Geraseners", footnotes: ["℘ Mt 8,28-34; Mk 5,1-20", "℘ ⇨Esyn: Synopse Nr. 137"] },
      { number: 27, text: "Als er aber an das Land gestiegen war, kam ihm ein Mann aus der Stadt entgegen, der Dämonen hatte und seit langer Zeit keine Kleider anzog und nicht im Haus blieb, sondern in den Grabstätten." },
      { number: 28, text: "Als er aber Jesus sah, schrie er auf und fiel vor ihm nieder und sprach mit lauter Stimme: Was habe ich mit dir zu schaffen, Jesus, Sohn Gottes, des Höchsten? Ich bitte dich, quäle mich nicht*.", footnotes: ["℘ Kap. 4,34"] },
      { number: 29, text: "Denn er hatte dem unreinen Geist geboten, von dem Menschen auszufahren*. Denn öfters hatte er ihn gepackt; und er war gebunden mit Ketten und Fußfesseln <und> bewacht <worden>, und er zerbrach die Fesseln und wurde von dem Dämon in die Wüsten getrieben*.", footnotes: ["℘ Mk 9,25", "℘ Kap. 9,39.42"] },
      { number: 30, text: "Jesus fragte ihn aber und sprach: Was ist dein Name? Er aber sprach: Legion. Denn viele Dämonen waren in ihn gefahren*.", footnotes: ["℘ V. 2"] },
      { number: 31, text: "Und sie baten ihn, dass er ihnen nicht gebieten möchte, in den Abgrund zu fahren*.", footnotes: ["℘ 2Petr 2,4; Offb 20,3"] },
      { number: 32, text: "Es war aber dort eine Herde von vielen Schweinen, die an dem Berg weideten. Und sie baten ihn, dass er ihnen erlauben möchte, in jene zu fahren. Und er erlaubte es ihnen." },
      { number: 33, text: "Die Dämonen aber fuhren von dem Menschen aus und fuhren in die Schweine, und die Herde stürzte sich den Abhang hinab in den See und ertrank." },
      { number: 34, text: "Als aber die Hüter sahen, was geschehen war, flohen sie und verkündeten es in der Stadt und auf dem Land." },
      { number: 35, text: "Die Leute aber gingen hinaus, um zu sehen, was geschehen war. Und sie kamen zu Jesus und fanden den Menschen, von dem die Dämonen ausgefahren waren, bekleidet und vernünftig zu den Füßen Jesu <sitzen>; und sie fürchteten sich." },
      { number: 36, text: "Die es aber gesehen hatten, verkündeten ihnen, wie der Besessene geheilt* worden war.", footnotes: ["w. gerettet"] },
      { number: 37, text: "Und die ganze Menge aus der Umgegend der Gerasener bat ihn, von ihnen wegzugehen*, denn sie waren von großer Furcht ergriffen. Er aber stieg in das Boot und kehrte wieder zurück.", footnotes: ["℘ Apg 16,39"] },
      { number: 38, text: "Der Mann aber, von dem die Dämonen ausgefahren waren, bat ihn, dass er bei ihm bleiben dürfe. Er aber entließ ihn und sprach:" },
      { number: 39, text: "Kehre in dein Haus zurück und erzähle, wie viel Gott an dir getan hat! Und er ging hin und rief aus durch die ganze Stadt, wie viel Jesus an ihm getan hatte*.", footnotes: ["℘ Ps 126,3; Dan 3,32"] },
      { number: 40, text: "*Es geschah aber, als Jesus zurückkehrte, nahm ihn die Volksmenge auf, denn alle erwarteten ihn. *", heading: "Heilung der blutflüssigen Frau — Auferweckung der Tochter des Jaïrus", footnotes: ["℘ Mt 9,18-26; Mk 5,21-43", "℘ ⇨Esyn: Synopse Nr. 138"] },
      { number: 41, text: "Und siehe, es kam ein Mann mit Namen Jaïrus — und er war Vorsteher der Synagoge — und fiel Jesus zu Füßen* und bat ihn, in sein Haus zu kommen;", footnotes: ["℘ Mt 17,14; Mk 7,25"] },
      { number: 42, text: "denn er hatte eine einzige* Tochter von etwa zwölf Jahren, und diese lag im Sterben. Während er aber hinging, drängten ihn die Volksmengen.", footnotes: ["w. im Griech. dasselbe Wort wie »eingeboren« in Joh 1,14.18; s. Anm. dort\n℘ Kap. 7,12"] },
      { number: 43, text: "Und eine Frau, die seit zwölf Jahren mit einem Blutfluss behaftet war und, obgleich sie ihren ganzen Lebensunterhalt an <die> Ärzte verwandt hatte, von niemand geheilt werden konnte," },
      { number: 44, text: "kam von hinten heran und rührte die Quaste* seines Gewandes an; und sogleich hörte ihr Blutfluss auf*.", footnotes: ["℘ 5Mo 22,12", "℘ Mk 3,10"] },
      { number: 45, text: "Und Jesus sprach: Wer ist es, der mich angerührt hat? Als aber alle es abstritten, sprach Petrus*: Meister, die Volksmengen drängen und drücken dich!*", footnotes: ["Einige alte Handschr. fügen hinzu: und die mit ihm waren", "Einige Handschr. fügen hinzu: und du sagst: Wer ist es, der mich angerührt hat?"] },
      { number: 46, text: "Jesus aber sprach: Es hat mich jemand angerührt; denn ich habe gespürt, dass Kraft von mir ausgegangen ist*.", footnotes: ["℘ Kap. 5,17"] },
      { number: 47, text: "Als die Frau aber sah, dass sie nicht verborgen blieb*, kam sie zitternd und fiel vor ihm nieder und berichtete vor dem ganzen Volk, um welcher Ursache willen sie ihn angerührt habe und wie sie sogleich geheilt worden sei.", footnotes: ["℘ Ps 38,10"] },
      { number: 48, text: "Er aber sprach zu ihr: Tochter, dein Glaube hat dich geheilt*. Geh hin in Frieden*!", footnotes: ["w. gerettet", "℘ Kap. 7,50"] },
      { number: 49, text: "Während er noch redete, kommt einer von dem <Haus des> Synagogenvorstehers und sagt zu ihm: Deine Tochter ist gestorben*. Bemühe den Lehrer nicht!", footnotes: ["℘ Joh 11,14"] },
      { number: 50, text: "Als aber Jesus es hörte, antwortete er ihm: Fürchte dich nicht, glaube nur! Und sie wird gerettet werden*.", footnotes: ["℘ Jes 59,1"] },
      { number: 51, text: "Als er aber in das Haus kam, erlaubte er niemand hineinzugehen außer Petrus und Johannes und Jakobus* und dem Vater des Kindes und der Mutter.", footnotes: ["℘ Kap. 9,28 ⇨Esyn: Synopse Nr. 160"] },
      { number: 52, text: "Alle aber weinten und beklagten sie. Er aber sprach: Weint nicht*! Denn sie ist nicht gestorben, sondern sie schläft.", footnotes: ["℘ Kap. 7,13"] },
      { number: 53, text: "Und sie lachten ihn aus, da sie wussten, dass sie gestorben war." },
      { number: 54, text: "Er aber ergriff ihre Hand und rief und sprach: Kind, steh auf*!", footnotes: ["℘ Kap. 7,14"] },
      { number: 55, text: "Und ihr Geist kehrte zurück, und sogleich stand sie auf*; und er befahl, ihr zu essen zu geben.", footnotes: ["℘ Mt 9,25"] },
      { number: 56, text: "Und ihre Eltern gerieten außer sich; er aber gebot ihnen, niemand zu sagen, was geschehen war*.", footnotes: ["℘ Kap. 5,14"] },
    ]},
    { number: 9, verses: [
      { number: 1, text: "*Als er aber die Zwölf zusammengerufen hatte*, gab er ihnen Kraft und Vollmacht über alle Dämonen und zur Heilung von Krankheiten.", heading: "Aussendung der zwölf Apostel", footnotes: ["℘ Mt 10,1.5-15; Mk 6,7-13; vgl. Kap. 10,1-12", "℘ Kap. 6,13 ⇨Esyn: Synopse Nr. 142"] },
      { number: 2, text: "Und er sandte sie, das Reich* Gottes zu predigen* und die Kranken gesund zu machen*.", footnotes: ["o. die Königsherrschaft", "℘ Kap. 8,1; Apg 28,31", "℘ Mk 3,14.15"] },
      { number: 3, text: "Und er sprach zu ihnen: Nehmt nichts mit auf den Weg: weder Stab noch Tasche noch Brot noch Geld, noch soll jemand zwei Unterkleider haben*!", footnotes: ["℘ Kap. 22,35"] },
      { number: 4, text: "Und in welches Haus ihr eintretet, dort bleibt, und von da geht weiter!" },
      { number: 5, text: "Und wo immer sie* euch nicht aufnehmen werden — geht fort aus jener Stadt und schüttelt auch den Staub von euren Füßen, zum Zeugnis gegen sie!", footnotes: ["w. Und so viele"] },
      { number: 6, text: "Sie gingen aber hinaus und durchzogen die Dörfer nacheinander, indem sie die gute Botschaft verkündigten und überall heilten*.", footnotes: ["℘ Mk 16,20"] },
      { number: 7, text: "*Es hörte aber Herodes*, der Vierfürst*, alles, was geschehen war, und er war in Verlegenheit, weil von einigen gesagt wurde, dass Johannes aus den Toten auferweckt worden sei; *", heading: "Jesus und Herodes", footnotes: ["℘ Mt 14,1.2; Mk 6,14-16", "Herodes Antipas (4 v. Chr. bis 39 n. Chr.); s. auch Anm. zu Mt 14,1", "griech. Tetrarch; ursprünglich Titel eines Fürsten, der über den vierten Teil eines Reiches regierte, später überhaupt für Fürsten geringerer Bedeutung verwendet", "℘ ⇨Esyn: Synopse Nr. 143"] },
      { number: 8, text: "von einigen aber, dass Elia erschienen, von anderen aber, dass einer der alten Propheten auferstanden sei*.", footnotes: ["℘ V. 19"] },
      { number: 9, text: "Und Herodes sprach: Johannes habe ich enthauptet*. Wer aber ist dieser, von dem ich solches höre? Und er suchte ihn zu sehen*.", footnotes: ["℘ Mt 14,10", "℘ Kap. 23,8"] },
      { number: 10, text: "*Und als die Apostel zurückkehrten, erzählten sie ihm alles, was sie getan hatten*; und er nahm sie mit und zog sich abseits zurück nach einer Stadt mit Namen Betsaida.", heading: "Speisung der Fünftausend", footnotes: ["℘ Mt 14,13-21; Mk 6,30-44; Joh 6,1-14; vgl. Mt 15,32-39; Mk 8,1-9", "℘ Kap. 10,17 ⇨Esyn: Synopse Nr. 146"] },
      { number: 11, text: "Als aber die Volksmengen es erfuhren, folgten sie ihm; und er nahm sie auf und redete zu ihnen vom Reich* Gottes, und die Heilung brauchten, machte er gesund.", footnotes: ["o. von der Königsherrschaft"] },
      { number: 12, text: "Der Tag aber begann sich zu neigen, und die Zwölf traten herbei und sprachen zu ihm: Entlass die Volksmenge, dass sie in die Dörfer ringsum und auf die Höfe gehen und Herberge und Speise finden! Denn hier sind wir an einem öden Ort." },
      { number: 13, text: "Er aber sprach zu ihnen: Gebt ihr ihnen zu essen! Sie aber sprachen: Wir haben nicht mehr als fünf Brote und zwei Fische — es sei denn, dass wir hingingen und für dieses ganze Volk Speise kauften." },
      { number: 14, text: "Denn es waren etwa fünftausend Männer. Er sprach aber zu seinen Jüngern: Lasst sie sich in Gruppen zu je fünfzig lagern!" },
      { number: 15, text: "Und sie taten so und ließen alle sich lagern." },
      { number: 16, text: "Er nahm aber die fünf Brote und die zwei Fische, blickte auf zum Himmel und segnete sie*; und er brach sie und gab sie den Jüngern, damit sie der Volksmenge vorlegten.", footnotes: ["℘ 1Sam 9,13; Apg 27,35"] },
      { number: 17, text: "Und sie aßen und wurden alle gesättigt; und es wurde aufgehoben, was ihnen an Brocken übrig geblieben war, zwölf Handkörbe <voll>." },
      { number: 18, text: "*Und es geschah, als er für sich allein betete*, waren die Jünger bei ihm; und er fragte sie und sprach: Was sagen die Volksmengen, wer ich bin?", heading: "Das Bekenntnis des Petrus — Erste Leidensankündigung — Bedingungen der Nachfolge", footnotes: ["℘ Mt 16,13-21; Mk 8,27-31", "℘ Kap. 5,16 ⇨Esyn: Synopse Nr. 158"] },
      { number: 19, text: "Sie aber antworteten und sprachen: Johannes der Täufer; andere aber: Elia; andere aber, dass einer der alten Propheten auferstanden sei*.", footnotes: ["℘ V. 7.8"] },
      { number: 20, text: "Er sprach aber zu ihnen: Ihr aber, was sagt ihr, wer ich bin? Petrus aber antwortete und sprach: Der Christus Gottes*.", footnotes: ["℘ Joh 6,69"] },
      { number: 21, text: "Er aber redete ihnen ernstlich zu und gebot ihnen, dies niemand zu sagen*,", footnotes: ["℘ Kap. 5,14"] },
      { number: 22, text: "und sprach: Der Sohn des Menschen muss vieles leiden und verworfen werden von den Ältesten und Hohenpriestern* und Schriftgelehrten und getötet und am dritten Tag auferweckt werden*.", footnotes: ["Nicht nur der amtierende Hohepriester, sondern alle männlichen Mitglieder der hohenpriesterlichen Familien wurden zu den »Hohenpriestern« gerechnet.", "℘ V. 44; Mt 16,21 ⇨Esyn: Synopse Nr. 159"] },
      { number: 23, text: "*Er sprach aber zu allen: Wenn jemand mir nachkommen will, verleugne er sich selbst und nehme sein Kreuz auf täglich und folge mir nach*!", footnotes: ["℘ Mt 16,24-28; Mk 8,34-9,1", "℘ Kap. 14,27; 2Kor 4,11 ⇨Esyn: Synopse Nr. 302"] },
      { number: 24, text: "Denn wer sein Leben* retten will, wird es verlieren; wer aber sein Leben* verliert um meinetwillen, der wird es retten*.", footnotes: ["o. seine Seele", "o. seine Seele", "℘ Kap. 17,33 ⇨Esyn: Synopse Nr. 235"] },
      { number: 25, text: "Denn was wird es einem Menschen nützen, wenn er die ganze Welt gewönne, sich selbst aber verlöre oder einbüßte?" },
      { number: 26, text: "Denn wer sich meiner und meiner Worte schämt, dessen wird der Sohn des Menschen sich schämen*, wenn er kommen wird in seiner Herrlichkeit und der des Vaters und der heiligen Engel*.", footnotes: ["℘ Kap. 12,9", "℘ Kap. 21,27"] },
      { number: 27, text: "Ich sage euch aber in Wahrheit: Es sind einige unter denen, die hier stehen, die den Tod nicht schmecken werden, bis sie das Reich* Gottes gesehen haben. *", footnotes: ["o. die Königsherrschaft", "℘ ⇨Esyn: Synopse Nr. 367"] },
      { number: 28, text: "*Es geschah aber etwa acht Tage nach diesen Worten, dass er Petrus und Johannes und Jakobus* mitnahm und auf den Berg stieg, um zu beten*.", heading: "Die Verklärung Jesu", footnotes: ["℘ Mt 17,1-9; Mk 9,2-10; 2Petr 1,16-18", "℘ Kap. 8,51", "℘ Kap. 5,16 ⇨Esyn: Synopse Nr. 161"] },
      { number: 29, text: "Und als er betete, veränderte sich das Aussehen seines Angesichts, und sein Gewand wurde weiß, strahlend." },
      { number: 30, text: "Und siehe, zwei Männer redeten mit ihm, es waren Mose* und Elia*.", footnotes: ["℘ 5Mo 34,5", "℘ 2Kö 2,11"] },
      { number: 31, text: "Diese erschienen in Herrlichkeit und besprachen seinen Ausgang, den er in Jerusalem erfüllen sollte*.", footnotes: ["℘ V. 51"] },
      { number: 32, text: "Petrus aber und die mit ihm waren, waren beschwert vom Schlaf*; als sie aber völlig aufgewacht waren, sahen sie seine Herrlichkeit und die zwei Männer, die bei ihm standen.", footnotes: ["℘ Mt 26,43"] },
      { number: 33, text: "Und es geschah, als sie von ihm schieden, sprach Petrus zu Jesus: Meister, es ist gut, dass wir hier sind; und lass uns drei Hütten machen, dir eine und Mose eine und Elia eine. Und er wusste nicht, was er sagte." },
      { number: 34, text: "Als er aber dies sagte, kam eine Wolke und überschattete sie. Sie fürchteten sich aber, als sie in die Wolke hineinkamen;" },
      { number: 35, text: "und es geschah eine Stimme aus der Wolke, die sagte: Dieser ist mein auserwählter* Sohn*, ihn hört!", footnotes: ["mit anderen Handschr.: geliebter", "℘ Kap. 1,35; Mk 1,11 ⇨Esyn: Synopse Nr. 302"] },
      { number: 36, text: "Und während die Stimme geschah, war Jesus wieder allein*. Und sie schwiegen und verkündeten in jenen Tagen niemand etwas von dem, was sie gesehen hatten.", footnotes: ["w. wurde Jesus allein gefunden"] },
      { number: 37, text: "*Es geschah aber am folgenden Tag, als sie von dem Berg herabgestiegen waren, da kam ihm eine große Volksmenge entgegen. *", heading: "Heilung eines Fallsüchtigen", footnotes: ["℘ Mt 17,14-21; Mk 9,14-29", "℘ ⇨Esyn: Synopse Nr. 163"] },
      { number: 38, text: "Und siehe, ein Mann aus der Volksmenge rief laut und sprach: Lehrer, ich bitte dich, blicke hin auf meinen Sohn, denn er ist mein einziger*;", footnotes: ["im Griech. dasselbe Wort wie »eingeboren« in Joh 1,14.18; s. Anm. dort\n℘ Kap. 7,12"] },
      { number: 39, text: "und siehe, ein Geist ergreift ihn, und plötzlich schreit er, und er zerrt ihn unter Schäumen, und kaum einmal lässt er von ihm ab, er reibt ihn auf*.", footnotes: ["℘ Kap. 8,29"] },
      { number: 40, text: "Und ich bat deine Jünger, dass sie ihn austreiben möchten, und sie konnten es nicht." },
      { number: 41, text: "Jesus aber antwortete und sprach: Ungläubiges* und verkehrtes Geschlecht*, bis wann soll ich bei euch sein und euch ertragen? Bring deinen Sohn her!", footnotes: ["℘ Kap. 24,11; Mk 16,14", "℘ Ps 78,8"] },
      { number: 42, text: "Aber noch während er herbeikam, warf ihn der Dämon nieder und zerrte ihn zusammen. Jesus aber bedrohte den unreinen Geist und heilte den Jungen und gab ihn seinem Vater zurück." },
      { number: 43, text: "Sie erstaunten aber alle sehr über die herrliche Größe Gottes*.*Als sich aber alle verwunderten über alles, was er tat, sprach er zu seinen Jüngern:", heading: "Zweite Leidensankündigung", footnotes: ["℘ Kap. 8,25; Mk 5,42 ⇨Esyn: Synopse Nr. 164", "℘ Mt 17,22.23; Mk 9,30-32"] },
      { number: 44, text: "Nehmt ihr diese Worte in eure Ohren, nämlich dass der Sohn des Menschen überliefert werden wird in die Hände der Menschen*.", footnotes: ["℘ V. 22"] },
      { number: 45, text: "Sie aber verstanden dieses Wort nicht, und es war vor ihnen verborgen, dass sie es nicht begriffen*; und sie fürchteten sich, ihn über dieses Wort zu fragen.", footnotes: ["℘ Kap. 2,50"] },
      { number: 46, text: "*Es stieg aber unter ihnen eine Überlegung auf, wer wohl der Größte unter ihnen sei*.", heading: "Maßstäbe für wahre Größe und den Dienst im Reich Gottes", footnotes: ["℘ Mt 18,1-5; Mk 9,33-37.38-41", "℘ Kap. 22,24 ⇨Esyn: Synopse Nr. 166"] },
      { number: 47, text: "Als Jesus aber die Überlegung ihres Herzens erkannte*, nahm er ein Kind und stellte es neben sich", footnotes: ["℘ Kap. 5,22"] },
      { number: 48, text: "und sprach zu ihnen: Wer dieses Kind aufnehmen wird in meinem Namen, nimmt mich auf, und wer mich aufnehmen wird, nimmt den auf, der mich gesandt hat*; denn wer der Kleinste ist unter euch allen, der ist groß*.", footnotes: ["℘ Kap. 10,16; Joh 13,20", "℘ Kap. 22,26"] },
      { number: 49, text: "Johannes aber antwortete und sprach: Meister, wir sahen jemand Dämonen austreiben in deinem Namen, und wir wehrten ihm, weil er <dir> nicht mit uns nachfolgt. *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 167"] },
      { number: 50, text: "Und Jesus sprach zu ihm: Wehrt nicht! Denn wer nicht gegen euch ist, ist für euch*.", footnotes: ["℘ Kap. 11,23"] },
      { number: 51, text: "Es geschah aber, als sich die Tage seiner Aufnahme erfüllten, da richtete er sein Angesicht fest darauf, nach Jerusalem zu gehen*.", heading: "Aufbruch nach Jerusalem — Ablehnung bei Samaritern", footnotes: ["℘ V. 31; Kap. 13,22; 17,11; 18,31; 19,28; Mt 16,21; Mk 10,32 ⇨Esyn: Synopse Nr. 174"] },
      { number: 52, text: "Und er sandte Boten vor seinem Angesicht her; und sie gingen hin und kamen in ein Dorf der Samariter, um für ihn <Unterkunft> zu bereiten*.", footnotes: ["℘ Kap. 10,1 ⇨Esyn: Synopse Nr. 175"] },
      { number: 53, text: "Und sie nahmen ihn nicht auf, weil sein Angesicht nach Jerusalem hin gerichtet war*.", footnotes: ["℘ Joh 4,9"] },
      { number: 54, text: "Als aber seine Jünger Jakobus und Johannes* das sahen, sprachen sie: Herr, willst du, dass wir sagen, dass Feuer vom Himmel herabfallen und sie verzehren soll*?", footnotes: ["℘ Mk 3,17", "Andere Handschr. fügen hinzu: wie auch Elia tat"] },
      { number: 55, text: "Er wandte sich aber um und schalt sie.*", footnotes: ["Andere Handschriften fügen hinzu: Wisst ihr nicht, welchen Geistes ihr seid? 56 Der Sohn des Menschen ist nicht gekommen, Menschenseelen zu verderben, sondern zu retten."] },
      { number: 56, text: "Und sie gingen nach einem anderen Dorf." },
      { number: 57, text: "*Es geschah aber, als sie auf dem Weg dahinzogen, sprach einer zu ihm: Ich will dir nachfolgen, wohin du auch gehst, Herr. *", heading: "Rechte Nachfolge", footnotes: ["℘ Mt 8,18-22", "℘ ⇨Esyn: Synopse Nr. 176"] },
      { number: 58, text: "Und Jesus sprach zu ihm: Die Füchse haben Höhlen und die Vögel des Himmels Nester; aber der Sohn des Menschen hat nicht, wo er sein Haupt hinlegt*.", footnotes: ["℘ Kap. 2,7.12"] },
      { number: 59, text: "Er sprach aber zu einem anderen: Folge mir nach*! Der aber sprach: Herr, erlaube mir, vorher hinzugehen und meinen Vater zu begraben.", footnotes: ["℘ Kap. 5,27"] },
      { number: 60, text: "Jesus aber sprach zu ihm: Lass die Toten ihre Toten begraben, du aber geh hin und verkündige das Reich* Gottes!", footnotes: ["o. die Königsherrschaft"] },
      { number: 61, text: "Es sprach aber auch ein anderer: Ich will dir nachfolgen, Herr; vorher aber erlaube mir, Abschied zu nehmen von denen, die in meinem Hause sind*.", footnotes: ["℘ 1Kö 19,20"] },
      { number: 62, text: "Jesus aber sprach zu ihm: Niemand, der seine Hand an den Pflug gelegt hat und zurückblickt, ist tauglich für das Reich* Gottes*.", footnotes: ["o. die Königsherrschaft", "℘ Phil 3,13; Hebr 10,38"] },
    ]},
    { number: 10, verses: [
      { number: 1, text: "*Nach diesem aber bestimmte der Herr siebzig andere und sandte sie zu je zwei vor seinem Angesicht her in jede Stadt und jeden Ort, wohin er selbst kommen wollte*.", heading: "Aussendung der siebzig Jünger", footnotes: ["℘ vgl. Kap. 9,1-6; Mt 10,5-15; Mk 6,7-13", "℘ Kap. 9,52 ⇨Esyn: Synopse Nr. 177"] },
      { number: 2, text: "Er sprach aber zu ihnen: Die Ernte zwar ist groß, die Arbeiter aber sind wenige. Bittet nun den Herrn der Ernte, dass er Arbeiter aussende in seine Ernte*!", footnotes: ["℘ Mt 9,37.38"] },
      { number: 3, text: "Geht hin! Siehe, ich sende euch wie Lämmer mitten unter Wölfe*.", footnotes: ["℘ Mt 10,16"] },
      { number: 4, text: "Tragt weder Börse noch Tasche noch Sandalen*, und grüßt niemand auf dem Weg*!", footnotes: ["℘ Kap. 22,35", "℘ 2Kö 4,29"] },
      { number: 5, text: "In welches Haus ihr aber eintretet, sprecht zuerst: Friede diesem Haus*!", footnotes: ["℘ 1Sam 25,6"] },
      { number: 6, text: "Und wenn dort ein Sohn des Friedens ist, so wird euer Friede auf ihm ruhen; wenn aber nicht, so wird er zu euch zurückkehren." },
      { number: 7, text: "In diesem Haus aber bleibt, und esst und trinkt, was sie haben! Denn der Arbeiter ist seines Lohnes wert*. Geht nicht aus einem Haus in ein anderes!", footnotes: ["℘ 1Kor 9,14"] },
      { number: 8, text: "Und in welche Stadt ihr kommt, und sie nehmen euch auf, <da> esst, was euch vorgesetzt wird," },
      { number: 9, text: "und heilt die Kranken darin und sprecht zu ihnen: Das Reich* Gottes ist nahe zu euch gekommen*.", footnotes: ["o. die Königsherrschaft", "℘ Kap. 16,16; Mt 3,2"] },
      { number: 10, text: "In welche Stadt ihr aber gekommen seid, und sie nehmen euch nicht auf, <da> geht hinaus auf ihre Straßen und sprecht:" },
      { number: 11, text: "Auch den Staub, der uns aus eurer Stadt an den Füßen hängt, schütteln wir gegen euch ab*; doch dies wisst, dass das Reich* Gottes nahe gekommen ist*.", footnotes: ["℘ Apg 13,51", "o. die Königsherrschaft", "℘ Kap. 16,16; Mt 3,2"] },
      { number: 12, text: "Ich sage euch, dass es Sodom an jenem Tag erträglicher ergehen wird als jener Stadt. *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 108"] },
      { number: 13, text: "*Wehe dir, Chorazin! Wehe dir, Betsaida! Denn wenn in Tyrus* und Sidon* die Wunderwerke* geschehen wären, die unter euch geschehen sind, längst hätten sie, in Sack und Asche sitzend, Buße getan*.", heading: "Weherufe über unbußfertige Städte", footnotes: ["℘ Mt 11,20-24", "℘ Hes 26,2.21", "℘ Hes 28,22", "o. Machttaten; griech. dynamis", "℘ Mt 10,15 ⇨Esyn: Synopse Nr. 178"] },
      { number: 14, text: "Doch Tyrus und Sidon wird es erträglicher ergehen im Gericht als euch." },
      { number: 15, text: "Und du, Kapernaum, wirst du etwa bis zum Himmel erhöht werden? Bis zum Hades* wirst du hinabgestoßen werden*.", footnotes: ["d. i. das Totenreich", "mit anderen Handschr.: wirst du hinabsteigen\n℘ Jes 14,15"] },
      { number: 16, text: "Wer euch hört, hört mich*; und wer euch verwirft, verwirft mich*; wer aber mich verwirft, verwirft den, der mich gesandt hat*.", footnotes: ["℘ Joh 13,20", "℘ Apg 9,4", "℘ Kap. 9,48; 2Mo 16,7; Joh 5,23; 1Thes 4,8 ⇨Esyn: Synopse Nr. 309"] },
      { number: 17, text: "*Die Siebzig aber kehrten mit Freuden zurück und sprachen: Herr, auch die Dämonen sind uns untertan in deinem Namen*.", heading: "Rückkehr der Siebzig — Lobpreis des Vaters", footnotes: ["℘ Mt 11,25-27", "℘ Kap. 9,10; Mk 6,13 ⇨Esyn: Synopse Nr. 180"] },
      { number: 18, text: "Er sprach aber zu ihnen: Ich schaute den Satan wie einen Blitz vom Himmel fallen*.", footnotes: ["℘ Offb 12,9 ⇨Esyn: Synopse Nr. 302"] },
      { number: 19, text: "Siehe, ich habe euch die Macht* gegeben*, auf Schlangen und Skorpione zu treten, und über die ganze Kraft des Feindes, und nichts soll euch schaden*.", footnotes: ["o. Vollmacht", "mit anderen alten Handschr.: ich gebe euch die Macht", "℘ Ps 91,13; Mk 16,18"] },
      { number: 20, text: "Doch darüber freut euch nicht, dass euch die Geister untertan sind; freut euch aber, dass eure Namen in den Himmeln angeschrieben sind*!", footnotes: ["℘ 2Mo 32,32; Ps 69,29; Dan 12,1; Phil 4,3; Hebr 12,23; Offb 3,5"] },
      { number: 21, text: "In dieser Stunde jubelte Jesus im Geist und sprach: Ich preise dich, Vater, Herr des Himmels und der Erde, dass du dies vor Weisen und Verständigen verborgen hast und hast es Unmündigen offenbart. Ja, Vater, denn so war es wohlgefällig vor dir. *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 181"] },
      { number: 22, text: "Alles ist mir übergeben von meinem Vater*; und niemand erkennt, wer der Sohn ist, als nur der Vater, und wer der Vater ist, als nur der Sohn und wem der Sohn <ihn> offenbaren will.", footnotes: ["℘ Mt 28,18"] },
      { number: 23, text: "Und er wandte sich zu den Jüngern allein und sprach: Glückselig die Augen, die sehen, was ihr seht*!", footnotes: ["℘ Mt 13,16.17 ⇨Esyn: Synopse Nr. 123"] },
      { number: 24, text: "Denn ich sage euch, dass viele Propheten und Könige begehrt haben, zu sehen, was ihr seht, und haben es nicht gesehen, und zu hören, was ihr hört, und haben es nicht gehört*.", footnotes: ["℘ Mt 13,16.17"] },
      { number: 25, text: "*Und siehe, ein Gesetzesgelehrter stand auf und versuchte ihn* und sprach: Lehrer, was muss ich getan haben, um ewiges Leben zu erben*?", heading: "Der barmherzige Samariter", footnotes: ["℘ vgl. Mt 22,34-40; Mk 12,28-34", "℘ Kap. 6,7; Joh 8,6", "℘ Kap. 18,18 ⇨Esyn: Synopse Nr. 182"] },
      { number: 26, text: "Er aber sprach zu ihm: Was steht in dem Gesetz geschrieben? Wie liest du?" },
      { number: 27, text: "Er aber antwortete und sprach: »Du sollst den Herrn, deinen Gott, lieben aus deinem ganzen Herzen und mit deiner ganzen Seele und mit deiner ganzen Kraft* und mit deinem ganzen Verstand* und deinen Nächsten wie dich selbst.«*", footnotes: ["℘ 2Kö 23,25", "℘ 5Mo 6,5", "℘ 3Mo 19,18"] },
      { number: 28, text: "Er sprach aber zu ihm: Du hast recht geantwortet; tu dies, und du wirst leben*.", footnotes: ["℘ Mt 19,17; Röm 10,5"] },
      { number: 29, text: "Indem er aber sich selbst rechtfertigen wollte*, sprach er zu Jesus: Und wer ist mein Nächster?", footnotes: ["℘ Kap. 16,15 ⇨Esyn: Synopse Nr. 183"] },
      { number: 30, text: "Jesus aber nahm <das Wort> und sprach: Ein Mensch ging von Jerusalem nach Jericho hinab und fiel unter Räuber, die ihn auch auszogen und ihm Schläge versetzten und weggingen und ihn halb tot liegen ließen." },
      { number: 31, text: "Zufällig aber ging ein Priester jenen Weg hinab; und als er <ihn> sah, ging er an der entgegengesetzten Seite vorüber." },
      { number: 32, text: "Ebenso aber kam auch ein Levit, der an den Ort gelangte, und er sah <ihn> und ging an der entgegengesetzten Seite vorüber." },
      { number: 33, text: "Aber ein Samariter, der auf der Reise war, kam zu ihm hin; und als er <ihn> sah, wurde er innerlich bewegt*;", footnotes: ["℘ Kap. 7,13 ⇨Esyn: Synopse Nr. 240"] },
      { number: 34, text: "und er trat hinzu und verband seine Wunden und goss Öl und Wein darauf*; und er setzte ihn auf sein eigenes Tier und führte ihn in eine Herberge und trug Sorge für ihn.", footnotes: ["℘ Ps 147,3"] },
      { number: 35, text: "Und am folgenden Morgen zog er zwei Denare heraus und gab sie dem Wirt und sprach: Trage Sorge für ihn! Und was du noch dazu verwenden wirst, werde ich dir bezahlen, wenn ich zurückkomme." },
      { number: 36, text: "Was meinst du, wer von diesen dreien der Nächste dessen gewesen ist, der unter die Räuber gefallen war?" },
      { number: 37, text: "Er aber sprach: Der die Barmherzigkeit an ihm übte. Jesus aber sprach zu ihm: Geh hin und handle du ebenso!" },
      { number: 38, text: "Es geschah aber, als sie ihres Weges zogen, dass er in ein Dorf kam; und eine Frau mit Namen Marta nahm ihn auf. *", heading: "Marta und Maria", footnotes: ["℘ ⇨Esyn: Synopse Nr. 184"] },
      { number: 39, text: "Und diese hatte eine Schwester, genannt Maria*, die sich auch zu den Füßen Jesu niedersetzte und seinem Wort zuhörte*.", footnotes: ["℘ Joh 11,1.2", "℘ 5Mo 33,3"] },
      { number: 40, text: "Marta aber war sehr beschäftigt mit vielem Dienen; sie trat aber hinzu und sprach: Herr, kümmert es dich nicht, dass meine Schwester mich allein gelassen hat zu dienen? Sage ihr doch, dass sie mir helfe!" },
      { number: 41, text: "Jesus aber antwortete und sprach zu ihr: Marta, Marta! Du bist besorgt und beunruhigt um viele Dinge;" },
      { number: 42, text: "eins aber ist nötig*. Maria aber hat das gute Teil erwählt, das nicht von ihr genommen werden wird.", footnotes: ["℘ Joh 6,27"] },
    ]},
    { number: 11, verses: [
      { number: 1, text: "*Und es geschah, als er an einem Ort war und betete*, da sprach, als er aufhörte, einer seiner Jünger zu ihm: Herr, lehre uns beten, wie auch Johannes seine Jünger lehrte!", heading: "Vom Gebet", footnotes: ["℘ V. 1-4: vgl. Mt 6,9-13; V. 5-13: vgl. Mt 7,7-11", "℘ Kap. 5,16 ⇨Esyn: Synopse Nr. 185"] },
      { number: 2, text: "Er sprach aber zu ihnen: Wenn ihr betet, so sprecht: Vater, geheiligt werde dein Name*; dein Reich* komme*;", footnotes: ["℘ Hes 36,23", "o. Königsherrschaft", "℘ Kap. 17,20; Jes 52,7"] },
      { number: 3, text: "unser nötiges Brot gib uns täglich*;", footnotes: ["℘ Spr 30,8"] },
      { number: 4, text: "und vergib uns unsere Sünden, denn auch wir selbst vergeben jedem, der uns schuldig ist*; und führe uns nicht in Versuchung*.", footnotes: ["℘ Mk 11,25", "℘ Joh 17,15"] },
      { number: 5, text: "Und er sprach zu ihnen: Wer von euch wird einen Freund haben und wird um Mitternacht zu ihm gehen und zu ihm sagen: Freund, leihe mir drei Brote, *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 186"] },
      { number: 6, text: "da mein Freund von der Reise bei mir angekommen ist und ich nichts habe, was ich ihm vorsetzen soll!" },
      { number: 7, text: "Und jener würde von innen antworten und sagen: Mach mir keine Mühe! Die Tür ist schon geschlossen, und meine Kinder sind bei mir im Bett; ich kann nicht aufstehen und dir geben?" },
      { number: 8, text: "Ich sage euch, wenn er auch nicht aufstehen und ihm geben wird, weil er sein Freund ist, so wird er wenigstens um seiner Unverschämtheit willen aufstehen und ihm geben, so viel er braucht*.", footnotes: ["℘ Kap. 18,5"] },
      { number: 9, text: "Und ich sage euch: Bittet, und es wird euch gegeben werden*; sucht, und ihr werdet finden*; klopft an, und es wird euch geöffnet werden!", footnotes: ["℘ Ps 37,4", "℘ Jer 29,13 ⇨Esyn: Synopse Nr. 187"] },
      { number: 10, text: "Denn jeder Bittende empfängt, und der Suchende findet, und dem Anklopfenden wird geöffnet werden*.", footnotes: ["℘ 2Chr 33,13; Esr 8,23"] },
      { number: 11, text: "Wen von euch, der Vater ist, wird der Sohn um einen Fisch bitten — und wird er ihm statt des Fisches <etwa> eine Schlange geben?" },
      { number: 12, text: "Oder auch, wenn er um ein Ei bäte — er wird ihm doch nicht einen Skorpion geben?" },
      { number: 13, text: "Wenn nun ihr, die ihr böse seid, euren Kindern gute Gaben zu geben wisst, wie viel mehr wird der Vater, der vom Himmel <gibt>, <den> Heiligen Geist geben* denen, die ihn bitten!", footnotes: ["mit anderen Handschr.: wie viel mehr wird der Vater vom Himmel Heiligen Geist geben"] },
      { number: 14, text: "*Und er trieb einen Dämon aus, der stumm war. Es geschah aber, als der Dämon ausgefahren war, redete der Stumme; und die Volksmengen wunderten sich*.", heading: "Dämonenaustreibung", footnotes: ["℘ Mt 12,22-37; Mk 3,22-30", "℘ Mk 9,17 ⇨Esyn: Synopse Nr. 188"] },
      { number: 15, text: "Einige aber von ihnen sagten: Durch Beelzebul*, den Obersten der Dämonen, treibt er die Dämonen aus*.", footnotes: ["im Judentum der Name für den Obersten der Dämonen; die Bedeutung des Namens ist umstritten", "℘ Kap. 7,33"] },
      { number: 16, text: "Andere aber versuchten ihn und forderten von ihm ein Zeichen aus dem Himmel*.", footnotes: ["℘ V. 29; Mt 12,38 ⇨Esyn: Synopse Nr. 119"] },
      { number: 17, text: "Da er aber ihre Gedanken wusste*, sprach er zu ihnen: Jedes Reich*, das mit sich selbst entzweit ist, wird verwüstet, und Haus gegen Haus <entzweit>, stürzt ein*.", footnotes: ["℘ Kap. 5,22", "o. Jede Königsherrschaft", "℘ Jes 19,2; Gal 5,15"] },
      { number: 18, text: "Wenn aber auch der Satan mit sich selbst entzweit ist, wie wird sein Reich* bestehen? Denn ihr sagt, dass ich durch Beelzebul die Dämonen austreibe.", footnotes: ["o. seine Königsherrschaft"] },
      { number: 19, text: "Wenn aber ich durch Beelzebul die Dämonen austreibe, durch wen treiben eure Söhne sie aus? Darum werden sie eure Richter sein." },
      { number: 20, text: "Wenn ich aber durch den Finger Gottes* die Dämonen austreibe, so ist also das Reich* Gottes zu euch gekommen*.", footnotes: ["℘ 2Mo 8,15", "o. Königsherrschaft", "℘ Kap. 17,21"] },
      { number: 21, text: "Wenn der Starke bewaffnet seinen Hof bewacht, so ist seine Habe in Frieden;" },
      { number: 22, text: "wenn aber ein Stärkerer als er über ihn kommt und ihn besiegt, so nimmt er seine ganze Waffenrüstung weg, auf die er vertraute, und seine Beute verteilt er*.", footnotes: ["℘ Kol 2,15; 1Jo 4,4"] },
      { number: 23, text: "Wer nicht mit mir ist, ist gegen mich; und wer nicht mit mir sammelt, zerstreut*.", footnotes: ["℘ Kap. 9,50"] },
      { number: 24, text: "*Wenn der unreine Geist von dem Menschen ausgefahren ist, so durchwandert er dürre Orte und sucht Ruhe; und da er sie nicht findet, spricht er: Ich will in mein Haus zurückkehren, von wo ich ausgegangen bin. *", heading: "Von der Rückkehr unreiner Geister", footnotes: ["℘ Mt 12,43-45", "℘ ⇨Esyn: Synopse Nr. 189"] },
      { number: 25, text: "Und wenn er kommt, findet er es gekehrt und geschmückt." },
      { number: 26, text: "Dann geht er hin und nimmt sieben andere Geister mit, böser als er selbst, und sie gehen hinein und wohnen dort; und das Ende jenes Menschen wird schlimmer als der Anfang*.", footnotes: ["℘ Joh 5,14"] },
      { number: 27, text: "Es geschah aber, als er dies sagte, da erhob eine Frau aus der Volksmenge ihre Stimme und sprach zu ihm: Glückselig der Leib, der dich getragen, und die Brüste, die du gesogen hast*!", heading: "Wahre Glückseligkeit", footnotes: ["℘ Kap. 1,48 ⇨Esyn: Synopse Nr. 190"] },
      { number: 28, text: "Er aber sprach: Gewiss, doch glückselig, die das Wort Gottes hören und befolgen*!", footnotes: ["o. beachten, festhalten\n℘ Kap. 8,15.21; Ps 119,1.2; Joh 13,17; Offb 1,3"] },
      { number: 29, text: "*Als aber die Volksmengen sich herzudrängten, fing er an zu sagen: Dieses Geschlecht ist ein böses Geschlecht*; es fordert ein Zeichen*, und kein Zeichen wird ihm gegeben werden als nur das Zeichen Jonas.", heading: "Das Zeichen Jonas", footnotes: ["℘ Mt 12,38-42", "℘ Ps 95,10", "℘ V. 16; Kap. 23,8 ⇨Esyn: Synopse Nr. 191"] },
      { number: 30, text: "Denn wie Jona den Niniviten ein Zeichen war, so wird es auch der Sohn des Menschen diesem Geschlecht sein*.", footnotes: ["℘ Mt 16,4"] },
      { number: 31, text: "Eine Königin des Südens wird auftreten im Gericht mit den Männern dieses Geschlechts und wird sie verdammen; denn sie kam von den Enden der Erde, um die Weisheit Salomos zu hören*; und siehe, hier ist mehr als Salomo.", footnotes: ["℘ 2Chr 9,1"] },
      { number: 32, text: "Männer von Ninive werden aufstehen im Gericht mit diesem Geschlecht und werden es verdammen; denn sie taten Buße auf die Predigt Jonas hin*; und siehe, hier ist mehr als Jona.", footnotes: ["℘ Jon 3,5"] },
      { number: 33, text: "*Niemand aber, der eine Leuchte angezündet hat, stellt sie ins Versteck, auch nicht unter den Scheffel*, sondern auf das Lampengestell, damit die Hereinkommenden den Schein sehen*.", heading: "Gleichnis vom Auge", footnotes: ["℘ vgl. Mt 5,15; 6,22.23", "w. Modios; s. Tabelle »Maße«", "℘ Kap. 8,16"] },
      { number: 34, text: "Die Leuchte des Leibes ist dein Auge; wenn dein Auge lauter ist, so ist auch dein ganzer Leib licht; wenn es aber böse ist, so ist auch dein Leib finster. *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 193"] },
      { number: 35, text: "Sieh nun zu, dass das Licht, welches in dir ist, nicht Finsternis ist." },
      { number: 36, text: "Wenn nun dein ganzer Leib licht ist und keinen finsteren Teil hat, so wird er ganz licht sein, wie wenn die Leuchte mit ihrem Strahl dich beleuchtete." },
      { number: 37, text: "*Als er aber redete, bat ihn ein Pharisäer, dass er bei ihm zu Mittag essen möchte; er ging aber hinein und legte sich zu Tisch*.", heading: "Weherufe gegen die Pharisäer und Schriftgelehrten", footnotes: ["℘ vgl. Mt 23,4-7.23-36", "℘ Kap. 7,36 ⇨Esyn: Synopse Nr. 194"] },
      { number: 38, text: "Als aber der Pharisäer es sah, wunderte er sich, dass er sich nicht erst vor dem Essen gewaschen hatte*.", footnotes: ["℘ Mt 15,2"] },
      { number: 39, text: "Der Herr aber sprach zu ihm: Nun, ihr Pharisäer, ihr reinigt das Äußere des Bechers und der Schüssel*, euer Inneres aber ist voller Raub und Bosheit.", footnotes: ["℘ Mk 7,4.8"] },
      { number: 40, text: "Toren! Hat nicht der, welcher das Äußere gemacht hat, auch das Innere gemacht?" },
      { number: 41, text: "Gebt jedoch als Almosen*, was darin ist, und siehe, alles ist euch rein*.", footnotes: ["℘ Kap. 12,33; 18,22", "℘ Tit 1,15"] },
      { number: 42, text: "Aber wehe euch Pharisäern! Denn ihr verzehntet die Minze und die Raute* und alles Kraut* und übergeht das Gericht* und die Liebe Gottes; diese Dinge hättet ihr tun und jene nicht lassen sollen.", footnotes: ["Gewürzkräuter", "℘ Kap. 18,12", "o. Recht"] },
      { number: 43, text: "Wehe euch Pharisäern! Denn ihr liebt den ersten Sitz in den Synagogen und die Begrüßungen auf den Märkten*.", footnotes: ["℘ Kap. 14,7; 20,46"] },
      { number: 44, text: "Wehe euch! Denn ihr seid wie die Grüfte, die verborgen sind, und die Menschen, die darüber hingehen, wissen es nicht." },
      { number: 45, text: "Aber einer der Gesetzesgelehrten antwortete und spricht zu ihm: Lehrer, indem du dies sagst, schmähst du auch uns." },
      { number: 46, text: "Er aber sprach: Auch euch Gesetzesgelehrten: Wehe! Denn ihr belastet die Menschen mit schwer zu tragenden Lasten*, und selbst rührt ihr die Lasten nicht mit einem eurer Finger an.", footnotes: ["℘ Apg 15,10"] },
      { number: 47, text: "Wehe euch! Denn ihr baut die Grabmäler der Propheten, eure Väter aber haben sie getötet*.", footnotes: ["℘ Apg 7,52"] },
      { number: 48, text: "So seid ihr Zeugen und stimmt den Werken eurer Väter bei; denn sie haben sie getötet, ihr aber baut *ihre Grabmäler*.", footnotes: ["in wesentlichen alten Handschr. nicht enthalten", "in wesentlichen alten Handschr. nicht enthalten"] },
      { number: 49, text: "Darum hat auch die Weisheit Gottes gesagt: Ich werde Propheten und Apostel zu ihnen senden, und einige von ihnen werden sie töten und verfolgen*,", footnotes: ["℘ Apg 12,2"] },
      { number: 50, text: "damit das Blut aller Propheten, das von Grundlegung der Welt an vergossen worden ist, von diesem Geschlecht gefordert werde:" },
      { number: 51, text: "von dem Blut Abels* an bis zu dem Blut des Secharja, der zwischen dem Altar und dem Haus umkam*; ja, sage ich euch, es wird von diesem Geschlecht gefordert werden.", footnotes: ["℘ 1Mo 4,10", "℘ 2Chr 24,21"] },
      { number: 52, text: "Wehe euch Gesetzesgelehrten! Denn ihr habt den Schlüssel der Erkenntnis weggenommen; ihr selbst seid nicht hineingegangen, und die hineingehen wollten, habt ihr gehindert*.", footnotes: ["℘ Mt 23,13"] },
      { number: 53, text: "Als er von dort hinausgegangen war*, fingen die Schriftgelehrten und die Pharisäer an, hart auf ihn einzudringen und ihn über vieles auszufragen;", footnotes: ["mit anderen Handschr.: Als er aber dies zu ihnen sagte"] },
      { number: 54, text: "und sie lauerten auf ihn, etwas aus seinem Mund zu erjagen*.", footnotes: ["℘ Kap. 6,7; 10,25; Mt 22,15"] },
    ]},
    { number: 12, verses: [
      { number: 1, text: "*Als sich unterdessen viele Tausende der Volksmenge versammelt hatten, so dass sie einander traten*, fing er an, zuerst zu seinen Jüngern zu sagen: Hütet euch vor dem Sauerteig der Pharisäer*, das heißt vor der Heuchelei*.", heading: "Warnung vor Heuchelei — Ermutigung zu furchtlosem Bekenntnis — Warnung vor Lästerung des Geistes", footnotes: ["℘ vgl. Mt 10,26-33", "℘ Kap. 5,1", "religiöse Partei im Judentum, die auf genaue Einhaltung des Gesetzes Wert legte; s. auch Anm. zu Mt 3,7", "w. der Heuchelei ist\n℘ Mt 16,6; 23,28; 1Kor 5,8 ⇨Esyn: Synopse Nr. 195"] },
      { number: 2, text: "Es ist aber nichts verdeckt, was nicht aufgedeckt, und <nichts> verborgen, was nicht erkannt werden wird*;", footnotes: ["℘ Kap. 8,17 ⇨Esyn: Synopse Nr. 196"] },
      { number: 3, text: "deswegen wird alles, was ihr in der Finsternis gesprochen haben werdet, im Licht gehört werden, und was ihr ins Ohr gesprochen haben werdet in den Kammern, wird auf den Dächern ausgerufen werden*.", footnotes: ["℘ 1Tim 5,24"] },
      { number: 4, text: "Ich sage aber euch, meinen Freunden*: Fürchtet euch nicht vor denen, die den Leib töten und nach diesem nichts weiter zu tun vermögen!", footnotes: ["℘ Joh 15,15"] },
      { number: 5, text: "Ich will euch aber zeigen, wen ihr fürchten sollt: Fürchtet den, der nach dem Töten Macht* hat, in die Hölle zu werfen; ja, sage ich euch, diesen fürchtet*!", footnotes: ["o. Vollmacht", "℘ Jes 8,13"] },
      { number: 6, text: "Werden nicht fünf Sperlinge für zwei Münzen* verkauft? Und nicht einer von ihnen ist vor Gott vergessen*.", footnotes: ["w. zwei Assarion; s. Tabelle »Münzen und Geldeinheiten«", "℘ Ps 104,27"] },
      { number: 7, text: "Aber selbst die Haare eures Hauptes sind alle gezählt*. Fürchtet euch nicht! Ihr seid mehr als viele Sperlinge*.", footnotes: ["℘ Kap. 21,18", "℘ V. 24"] },
      { number: 8, text: "Ich sage euch aber: Jeder, der sich vor den Menschen zu mir bekennen wird, zu dem wird sich auch der Sohn des Menschen vor den Engeln Gottes bekennen;" },
      { number: 9, text: "wer mich aber vor den Menschen verleugnet haben wird, der wird vor den Engeln Gottes verleugnet werden*.", footnotes: ["℘ Kap. 9,26 ⇨Esyn: Synopse Nr. 160"] },
      { number: 10, text: "Und jeder, der ein Wort sagen wird gegen den Sohn des Menschen, dem wird vergeben werden; dem aber, der gegen den Heiligen Geist lästert, wird nicht vergeben werden*.", footnotes: ["℘ Mt 12,31.32 ⇨Esyn: Synopse Nr. 197"] },
      { number: 11, text: "Wenn sie euch aber vor die Synagogen und die Obrigkeiten und die Machthaber* führen, so sorgt nicht, wie oder womit ihr euch verantworten oder was ihr sagen sollt! *", footnotes: ["w. Mächte", "℘ ⇨Esyn: Synopse Nr. 198"] },
      { number: 12, text: "Denn der Heilige Geist wird euch in jener Stunde lehren, was ihr sagen sollt*.", footnotes: ["℘ Kap. 21,12-15; Mt 10,19.20"] },
      { number: 13, text: "Einer aus der Volksmenge aber sprach zu ihm: Lehrer, sage meinem Bruder, dass er das Erbe mit mir teile! *", heading: "Gleichnis vom reichen Toren", footnotes: ["℘ ⇨Esyn: Synopse Nr. 199"] },
      { number: 14, text: "Er aber sprach zu ihm: Mensch, wer hat mich als Richter oder <Erb>teiler über euch eingesetzt?" },
      { number: 15, text: "Er sprach aber zu ihnen: Seht zu und hütet euch vor aller Habsucht*! Denn <auch> wenn jemand Überfluss hat, besteht sein Leben nicht aus seiner Habe.", footnotes: ["℘ Mk 4,19; 1Tim 6,10"] },
      { number: 16, text: "Er sagte aber ein Gleichnis zu ihnen und sprach: Das Land eines reichen Menschen trug viel ein. *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 200"] },
      { number: 17, text: "Und er überlegte bei sich selbst und sprach: Was soll ich tun? Denn ich habe nicht, wohin ich meine Früchte einsammeln soll." },
      { number: 18, text: "Und er sprach: Dies will ich tun: Ich will meine Scheunen niederreißen und größere bauen und will dahin all mein Korn und meine Güter einsammeln;" },
      { number: 19, text: "und ich will zu meiner Seele sagen: Seele, du hast viele Güter liegen auf viele Jahre. Ruhe aus, iss, trink, sei fröhlich*!", footnotes: ["℘ Ps 62,11; Spr 18,11; Jer 9,22"] },
      { number: 20, text: "Gott aber sprach zu ihm: Du Tor! In dieser Nacht wird man deine Seele von dir fordern*. Was du aber bereitet hast, für wen wird es sein*?", footnotes: ["w. fordern sie deine Seele von dir zurück\n℘ Jak 4,14", "℘ Ps 39,7; 49,18; Pred 4,8"] },
      { number: 21, text: "So ist, der für sich Schätze sammelt* und nicht reich ist im Blick auf Gott*.", footnotes: ["℘ Hab 2,9", "℘ Mt 6,19"] },
      { number: 22, text: "*Er sprach aber zu seinen Jüngern: Deshalb sage ich euch: Seid nicht besorgt für das Leben, was ihr essen, noch für den Leib, was ihr anziehen sollt*!", heading: "Warnung vor Sorgen", footnotes: ["℘ vgl. Mt 6,19-21.25-34", "℘ Phil 4,6 ⇨Esyn: Synopse Nr. 201"] },
      { number: 23, text: "Das Leben ist mehr als die Nahrung und der Leib mehr als die Kleidung." },
      { number: 24, text: "Betrachtet die Raben, die nicht säen noch ernten, die weder Vorratskammer noch Scheune haben, und Gott ernährt sie*. Wie viel seid ihr mehr als die Vögel*!", footnotes: ["℘ Hi 38,41", "℘ V. 7; Mt 12,12"] },
      { number: 25, text: "Wer aber unter euch kann mit Sorgen seiner Lebenslänge* eine Elle zusetzen?", footnotes: ["o. Lebensalter; o. Körpergröße"] },
      { number: 26, text: "Wenn ihr nun auch das Geringste nicht könnt, warum seid ihr um das Übrige besorgt?" },
      { number: 27, text: "Betrachtet die Lilien, wie sie wachsen; sie mühen sich nicht und spinnen auch nicht. Ich sage euch aber, selbst Salomo in all seiner Herrlichkeit war nicht bekleidet wie eine von ihnen." },
      { number: 28, text: "Wenn aber Gott das Gras, das heute auf dem Feld steht und morgen in den Ofen geworfen wird, so kleidet, wie viel mehr euch, Kleingläubige!" },
      { number: 29, text: "Und ihr, trachtet nicht <danach>, was ihr essen oder was ihr trinken sollt, und seid nicht in Unruhe!" },
      { number: 30, text: "Denn nach diesem allen trachten die Nationen der Welt; euer Vater aber weiß, dass ihr dies benötigt*.", footnotes: ["℘ Mt 6,8"] },
      { number: 31, text: "Trachtet jedoch nach seinem Reich*! Und dies wird euch hinzugefügt werden*.", footnotes: ["o. seiner Königsherrschaft", "℘ 1Kö 3,13"] },
      { number: 32, text: "Fürchte dich nicht, du kleine Herde*! Denn es hat eurem Vater wohlgefallen, euch das Reich* zu geben*.", footnotes: ["℘ Jes 41,14", "o. die Königsherrschaft", "℘ Kap. 6,20; Dan 7,27; Mt 25,34; Hebr 12,28"] },
      { number: 33, text: "Verkauft eure Habe und gebt Almosen*; macht euch Beutel, die nicht veralten, einen unvergänglichen Schatz in den Himmeln, wo kein Dieb sich naht und keine Motte zerstört*!", footnotes: ["℘ Kap. 11,41; Mk 10,21; Apg 2,45", "℘ Hag 1,6 ⇨Esyn: Synopse Nr. 202"] },
      { number: 34, text: "Denn wo euer Schatz ist, da wird auch euer Herz sein." },
      { number: 35, text: "*Eure Lenden sollen umgürtet* und die Lampen brennend sein*!", heading: "Ermahnung zur Wachsamkeit und Treue — Gleichnis vom treuen und untreuen Knecht", footnotes: ["℘ vgl. Mt 24,42-51", "℘ 2Mo 12,11; Eph 6,14; 1Petr 1,13", "℘ Mt 25,4.8 ⇨Esyn: Synopse Nr. 298"] },
      { number: 36, text: "Und ihr, seid Menschen gleich, die auf ihren Herrn warten, wann er aufbrechen mag von der Hochzeit, damit, wenn er kommt und anklopft, sie ihm sogleich öffnen." },
      { number: 37, text: "Glückselig jene Knechte*, die der Herr, wenn er kommt, wachend finden wird*! Wahrlich, ich sage euch: Er wird sich umgürten* und sie sich zu Tisch legen lassen und wird hinzutreten und sie bedienen.", footnotes: ["w. Sklaven; so auch V. 43—47", "℘ Mk 13,37; Offb 16,15", "℘ Joh 13,4 ⇨Esyn: Synopse Nr. 309"] },
      { number: 38, text: "Und wenn er in der zweiten Wache* und wenn er in der dritten Wache kommt und findet sie so — glückselig sind jene*!", footnotes: ["In neutestamentlicher Zeit galt die griech.-röm. Einteilung der Nacht in vier Nachtwachen (Abend/Mitternacht/Hahnenschrei/ Morgen) zu je drei Stunden.", "℘ Mk 13,35"] },
      { number: 39, text: "Dies aber erkennt: Wenn der Hausherr gewusst hätte, zu welcher Stunde der Dieb kommen würde*, so hätte er gewacht und nicht erlaubt, dass sein Haus durchgraben würde.", footnotes: ["℘ 1Thes 5,2"] },
      { number: 40, text: "Auch ihr, seid bereit! Denn der Sohn des Menschen kommt in der Stunde, da ihr es nicht meint*.", footnotes: ["℘ Mt 25,13; Mk 13,33"] },
      { number: 41, text: "Petrus aber sprach zu ihm: Herr, sagst du dieses Gleichnis zu uns oder auch zu allen?" },
      { number: 42, text: "Der Herr aber sprach: Wer ist nun der treue und kluge Verwalter*, den der Herr über seine Dienerschaft setzen wird, um <ihm> die zugemessene Speise zu geben zur <rechten> Zeit*?", footnotes: ["℘ 1Kor 4,2", "℘ 1Petr 4,10"] },
      { number: 43, text: "Glückselig jener Knecht, den sein Herr, wenn er kommt, bei solchem Tun finden wird!" },
      { number: 44, text: "In Wahrheit sage ich euch, dass er ihn über seine ganze Habe setzen wird*.", footnotes: ["℘ Mt 25,21"] },
      { number: 45, text: "Wenn aber jener Knecht in seinem Herzen sagt: Mein Herr lässt sich Zeit mit dem Kommen*, und anfängt, die Knechte und Mägde zu schlagen und zu essen und zu trinken und sich zu berauschen*,", footnotes: ["o. zögert (o. säumt) zu kommen", "℘ Kap. 21,34"] },
      { number: 46, text: "so wird der Herr jenes Knechtes kommen an einem Tag, an dem er es nicht erwartet, und in einer Stunde, die er nicht weiß, und wird ihn entzweischneiden und ihm sein Teil festsetzen bei den Ungläubigen." },
      { number: 47, text: "Jener Knecht aber, der den Willen seines Herrn wusste und sich nicht bereitet noch nach seinem Willen getan hat, wird mit vielen <Schlägen> geschlagen werden*;", footnotes: ["℘ Jak 4,17"] },
      { number: 48, text: "wer ihn aber nicht wusste, aber getan hat, was der Schläge wert ist, wird mit wenigen geschlagen werden*. Jedem aber, dem viel gegeben ist — viel wird von ihm verlangt werden; und wem man viel anvertraut hat, von dem wird man desto mehr fordern*.", footnotes: ["℘ 5Mo 25,2; Mt 11,22", "℘ Röm 2,12; Jak 3,1; 2Petr 2,21"] },
      { number: 49, text: "*Ich bin gekommen, Feuer auf die Erde zu werfen, und wie wünschte ich, es wäre schon angezündet! *", heading: "Entzweiung um Jesu willen", footnotes: ["℘ vgl. Mt 10,34-36", "℘ ⇨Esyn: Synopse Nr. 204"] },
      { number: 50, text: "Ich habe aber eine Taufe, womit ich getauft werden muss*, und wie bin ich bedrängt*, bis sie vollbracht ist*!", footnotes: ["℘ Mk 10,38", "℘ Joh 12,27", "℘ Joh 19,30"] },
      { number: 51, text: "Denkt ihr, dass ich gekommen sei, Frieden auf der Erde zu geben? Nein, sage ich euch, sondern vielmehr Entzweiung*.", footnotes: ["℘ Joh 7,12; Apg 14,2.4"] },
      { number: 52, text: "Denn es werden von nun an fünf in einem Haus entzweit sein; drei mit zweien und zwei mit dreien;" },
      { number: 53, text: "es werden entzweit sein Vater mit Sohn und Sohn mit Vater, Mutter mit der Tochter und Tochter mit der Mutter, Schwiegermutter mit ihrer Schwiegertochter und Schwiegertochter mit der Schwiegermutter*.", footnotes: ["℘ Mk 13,12"] },
      { number: 54, text: "*Er sprach aber auch zu den Volksmengen: Wenn ihr eine Wolke von Westen aufsteigen seht, so sagt ihr sogleich: Ein Regenguss kommt. Und es geschieht so. *", heading: "Zeichen der Zeit — Ermahnung zur Versöhnung und Buße — Gleichnis vom Feigenbaum", footnotes: ["℘ V. 54-56: Mt 16,1-3", "℘ ⇨Esyn: Synopse Nr. 205"] },
      { number: 55, text: "Und wenn <ihr> den Südwind wehen <seht>, so sagt ihr: Es wird Hitze geben. Und es geschieht." },
      { number: 56, text: "Heuchler! Das Aussehen der Erde und des Himmels wisst ihr zu beurteilen. Wie aber kommt es, dass ihr diese Zeit nicht zu beurteilen wisst?" },
      { number: 57, text: "*Warum richtet ihr aber auch von euch selbst aus nicht, was recht ist? *", footnotes: ["℘ V. 57-59: Mt 5,25.26", "℘ ⇨Esyn: Synopse Nr. 206"] },
      { number: 58, text: "Denn wenn du mit deinem Gegner vor die Obrigkeit gehst, so gib dir auf dem Weg Mühe, von ihm loszukommen, damit er dich nicht etwa zu dem Richter hinschleppe; und der Richter wird dich dem Gerichtsdiener überliefern und der Gerichtsdiener dich ins Gefängnis werfen." },
      { number: 59, text: "Ich sage dir: Du wirst nicht von dort herauskommen, bis du auch die letzte Münze* bezahlt hast.", footnotes: ["w. Lepton; s. Tabelle »Münzen und Geldeinheiten«"] },
    ]},
    { number: 13, verses: [
      { number: 1, text: "Zu dieser Zeit waren aber einige zugegen, die ihm von den Galiläern berichteten, deren Blut Pilatus* mit ihren Schlachtopfern vermischt hatte. *", footnotes: ["kaiserlicher Statthalter von ca. 26—36 n. Chr. in Judäa und Samaria", "℘ ⇨Esyn: Synopse Nr. 207"] },
      { number: 2, text: "Und er antwortete und sprach zu ihnen: Meint ihr, dass diese Galiläer vor allen Galiläern Sünder waren, weil sie dies erlitten haben*?", footnotes: ["℘ Joh 9,2"] },
      { number: 3, text: "Nein, sage ich euch, sondern wenn ihr nicht Buße tut, werdet ihr alle ebenso umkommen*.", footnotes: ["℘ Offb 2,22"] },
      { number: 4, text: "Oder jene achtzehn, auf die der Turm in Siloah fiel und sie tötete; meint ihr, dass sie vor allen Menschen, die in Jerusalem wohnen, Schuldner waren?" },
      { number: 5, text: "Nein, sage ich euch, sondern wenn ihr nicht Buße tut, werdet ihr alle ebenso umkommen*.", footnotes: ["℘ Hes 18,30-32"] },
      { number: 6, text: "Er sagte aber dieses Gleichnis: Es hatte jemand einen Feigenbaum, der in seinem Weinberg gepflanzt war; und er kam und suchte Frucht an ihm und fand keine*.", footnotes: ["℘ Mt 21,19"] },
      { number: 7, text: "Er sprach aber zu dem Weingärtner: Siehe, drei Jahre komme ich und suche Frucht an diesem Feigenbaum und finde keine. Hau ihn ab*! Wozu macht er auch das Land unbrauchbar?", footnotes: ["℘ Mt 3,10"] },
      { number: 8, text: "Er aber antwortet und sagt zu ihm: Herr, lass ihn noch dieses Jahr, bis ich um ihn graben und Dünger legen werde!" },
      { number: 9, text: "Und wenn er künftig Frucht bringen wird, <gut,> wenn aber nicht, so magst du ihn abhauen*.", footnotes: ["℘ Jes 5,5.6"] },
      { number: 10, text: "Er lehrte aber am Sabbat in einer der Synagogen*.", heading: "Heilung einer Frau am Sabbat", footnotes: ["℘ Kap. 4,31 ⇨Esyn: Synopse Nr. 208"] },
      { number: 11, text: "Und siehe, da war eine Frau, die achtzehn Jahre einen Geist der Schwäche hatte; und sie war zusammengekrümmt und völlig unfähig, sich aufzurichten." },
      { number: 12, text: "Als aber Jesus sie sah, rief er ihr zu und sprach zu ihr: Frau, du bist gelöst von deiner Schwäche!" },
      { number: 13, text: "Und er legte ihr die Hände auf*, und sofort wurde sie gerade* und verherrlichte Gott*.", footnotes: ["℘ Kap. 4,40", "℘ Ps 33,9; 146,8", "℘ Ps 116,16.17"] },
      { number: 14, text: "Der Synagogenvorsteher aber, unwillig, dass Jesus am Sabbat heilte*, begann* und sprach zu der Volksmenge: Sechs Tage sind es, an denen man arbeiten soll*. An diesen nun kommt und lasst euch heilen und nicht am Tag des Sabbats!", footnotes: ["℘ Kap. 6,7; Joh 5,16", "w. antwortete; hier in semitisierender Redeweise für den Anfang einer Rede gebraucht", "℘ 2Mo 20,9; 5Mo 5,13"] },
      { number: 15, text: "Der Herr nun antwortete ihm und sprach: Heuchler! Bindet nicht jeder von euch am Sabbat seinen Ochsen oder Esel von der Krippe los und führt ihn hin und tränkt ihn*?", footnotes: ["℘ Kap. 14,5; Mt 12,11.12"] },
      { number: 16, text: "Diese aber, die eine Tochter Abrahams ist*, die der Satan gebunden hat, siehe, achtzehn Jahre lang, sollte sie nicht von dieser Fessel gelöst werden am Tag des Sabbats*?", footnotes: ["℘ Kap. 19,9", "℘ Kap. 6,9"] },
      { number: 17, text: "Und als er dies sagte, wurden alle seine Widersacher beschämt*; und die ganze Volksmenge freute sich über all die herrlichen Dinge, die durch ihn geschahen*.", footnotes: ["℘ Jes 45,24", "℘ Kap. 18,43; 19,37"] },
      { number: 18, text: "*Er sprach aber: Wem ist das Reich* Gottes gleich, und wem soll ich es vergleichen? *", heading: "Gleichnisse vom Senfkorn und Sauerteig", footnotes: ["℘ Mt 13,31-33; Mk 4,30-34", "o. die Königsherrschaft", "℘ ⇨Esyn: Synopse Nr. 209"] },
      { number: 19, text: "Es gleicht einem Senfkorn, das ein Mensch nahm und in seinen Garten warf; und es wuchs und wurde zu einem Baum, und die Vögel des Himmels nisteten in seinen Zweigen." },
      { number: 20, text: "Und wieder sprach er: Wem soll ich das Reich* Gottes vergleichen? *", footnotes: ["o. die Königsherrschaft", "℘ ⇨Esyn: Synopse Nr. 210"] },
      { number: 21, text: "Es gleicht einem Sauerteig, den eine Frau nahm und unter drei Maß* Mehl mengte, bis es ganz durchsäuert war*.", footnotes: ["w. Saton; ein Hohlmaß von etwa 13 l", "℘ 1Kor 5,6; Gal 5,9"] },
      { number: 22, text: "Und lehrend durchzog er nacheinander Städte und Dörfer* und reiste nach Jerusalem*.", heading: "Die enge Pforte — Erste und Letzte", footnotes: ["℘ Kap. 8,1", "℘ Kap. 9,51 ⇨Esyn: Synopse Nr. 211"] },
      { number: 23, text: "Es sprach aber jemand zu ihm: Herr, sind es wenige, die gerettet werden? Er aber sprach zu ihnen:" },
      { number: 24, text: "Ringt danach, durch die enge Pforte hineinzugehen; denn viele, sage ich euch, werden hineinzugehen suchen und werden es nicht können*.", footnotes: ["℘ Mt 7,13.14"] },
      { number: 25, text: "Sobald der Hausherr aufgestanden ist und die Tür verschlossen hat und ihr anfangen werdet, draußen zu stehen und an der Tür zu klopfen und zu sagen: Herr, öffne uns!, wird er antworten und zu euch sagen: Ich kenne euch nicht <und weiß nicht>, woher ihr seid*.", footnotes: ["℘ Mt 25,10-12"] },
      { number: 26, text: "Dann werdet ihr anfangen zu sagen: Wir haben vor dir gegessen und getrunken, und auf unseren Straßen hast du gelehrt." },
      { number: 27, text: "Und er wird sagen: Ich sage euch, ich kenne euch nicht <und weiß nicht>, woher ihr seid*. Weicht von mir, alle ihr Übeltäter*!", footnotes: ["℘ Mt 25,10-12", "℘ Ps 6,9"] },
      { number: 28, text: "Da wird das Weinen und das Zähneknirschen sein, wenn ihr Abraham und Isaak und Jakob und alle Propheten im Reich* Gottes sehen werdet, euch aber draußen hinausgeworfen.", footnotes: ["o. in der Königsherrschaft"] },
      { number: 29, text: "Und sie werden kommen von Osten und Westen und von Norden und Süden und zu Tisch liegen im Reich* Gottes*.", footnotes: ["o. in der Königsherrschaft", "℘ Kap. 14,15; Jes 49,12; Mt 8,11.12"] },
      { number: 30, text: "Und siehe, es sind Letzte, die Erste sein werden, und es sind Erste, die Letzte sein werden*.", footnotes: ["℘ Mt 19,30"] },
      { number: 31, text: "*In derselben Stunde kamen einige Pharisäer herbei und sagten zu ihm: Geh hinaus und zieh fort! Denn Herodes* will dich töten*.", heading: "Klage über Jerusalem", footnotes: ["℘ vgl. Mt 23,37-39", "Herodes Antipas (4 v. Chr. bis 39 n. Chr.); s. auch Anm. zu Mt 14,1", "℘ Mt 2,13 ⇨Esyn: Synopse Nr. 212"] },
      { number: 32, text: "Und er sprach zu ihnen: Geht hin und sagt diesem Fuchs: Siehe, ich treibe Dämonen aus und vollbringe Heilungen heute und morgen, und am dritten <Tag> werde ich vollendet." },
      { number: 33, text: "Doch ich muss heute und morgen und am folgenden <Tag> wandern; denn es geht nicht an, dass ein Prophet außerhalb Jerusalems umkomme*.", footnotes: ["℘ Mt 20,18"] },
      { number: 34, text: "Jerusalem, Jerusalem, das da tötet die Propheten* und steinigt, die zu ihm gesandt sind*! Wie oft habe ich deine Kinder versammeln wollen wie eine Henne ihre Brut unter die Flügel, und ihr habt nicht gewollt*!", footnotes: ["℘ 1Thes 2,15", "℘ 2Chr 24,21; Jer 2,30; Apg 7,52", "℘ Jes 42,24 ⇨Esyn: Synopse Nr. 213"] },
      { number: 35, text: "Siehe, euer Haus wird euch überlassen*. Ich sage euch aber: Ihr werdet mich nicht sehen, bis es geschieht, dass ihr sprecht: »Gepriesen <sei>, der da kommt im Namen des Herrn!«*", footnotes: ["℘ Jer 12,7; 22,5", "℘ Kap. 19,38; Ps 118,26"] },
    ]},
    { number: 14, verses: [
      { number: 1, text: "Und es geschah, als er am Sabbat in das Haus eines der Obersten der Pharisäer* kam, zu essen*, dass sie auf ihn lauerten*.", heading: "Heilung eines Wassersüchtigen am Sabbat", footnotes: ["religiöse Partei im Judentum, die auf genaue Einhaltung des Gesetzes Wert legte, s. auch Anm. zu Mt 3,7", "w. Brot essen\n℘ Kap. 7,36", "℘ Kap. 6,7 ⇨Esyn: Synopse Nr. 214"] },
      { number: 2, text: "Und siehe, ein wassersüchtiger Mensch war vor ihm." },
      { number: 3, text: "Und Jesus begann* und sprach zu den Gesetzesgelehrten und Pharisäern und sagte: Ist es erlaubt, am Sabbat zu heilen oder nicht*?", footnotes: ["w. antwortete; hier in semitisierender Redeweise für den Anfang einer Rede gebraucht", "℘ Kap. 6,9"] },
      { number: 4, text: "Sie aber schwiegen. Und er fasste ihn an und heilte ihn und entließ ihn." },
      { number: 5, text: "Und er sprach zu ihnen: Wer unter euch, dessen Sohn oder Ochse in einen Brunnen fällt, zieht ihn nicht sogleich heraus am Tag des Sabbats*?", footnotes: ["℘ Kap. 13,15"] },
      { number: 6, text: "Und sie konnten ihm darauf nicht antworten*.", footnotes: ["℘ Mt 22,46; Mk 3,4"] },
      { number: 7, text: "Er sprach aber zu den Eingeladenen ein Gleichnis, als er bemerkte, wie sie die ersten Plätze wählten*, und sagte zu ihnen:", heading: "Warnung vor Ehrsucht", footnotes: ["℘ Kap. 11,43 ⇨Esyn: Synopse Nr. 215"] },
      { number: 8, text: "Wenn du von jemandem zur Hochzeit eingeladen wirst, so lege dich nicht auf den ersten Platz, damit nicht etwa ein Geehrterer als du von ihm eingeladen sei" },
      { number: 9, text: "und der, welcher dich und ihn eingeladen hat, komme und zu dir spreche: Mach diesem Platz! Und dann wirst du anfangen, mit Schande den letzten Platz einzunehmen*.", footnotes: ["℘ Spr 25,7"] },
      { number: 10, text: "Sondern wenn du eingeladen bist, so geh hin und lege dich auf den letzten Platz, damit, wenn der, welcher dich eingeladen hat, kommt, er zu dir spricht: Freund, rücke höher hinauf! Dann wirst du Ehre haben vor allen, die mit dir zu Tisch liegen*.", footnotes: ["℘ Spr 15,33"] },
      { number: 11, text: "Denn jeder, der sich selbst erhöht, wird erniedrigt werden, und wer sich selbst erniedrigt, wird erhöht werden*.", footnotes: ["℘ Kap. 18,14; Mt 18,4"] },
      { number: 12, text: "Er sprach aber auch zu dem, der ihn eingeladen hatte: Wenn du ein Mittag- oder ein Abendessen machst, so lade nicht deine Freunde ein noch deine Brüder noch deine Verwandten noch reiche Nachbarn, damit nicht etwa auch sie dich wieder einladen und dir Vergeltung zuteil werde*.", footnotes: ["℘ Kap. 6,34"] },
      { number: 13, text: "Sondern wenn du ein Mahl machst, so lade Arme*, Krüppel, Lahme, Blinde ein*!", footnotes: ["℘ 5Mo 14,29", "℘ V. 21"] },
      { number: 14, text: "Und glückselig wirst du sein*, weil sie nichts haben, um dir zu vergelten; denn es wird dir vergolten werden bei der Auferstehung der Gerechten*.", footnotes: ["℘ Apg 20,35", "℘ Kap. 6,35"] },
      { number: 15, text: "*Als aber einer von denen, die mit zu Tisch lagen, dies hörte, sprach er zu ihm: Glückselig, wer essen* wird im Reich* Gottes*!", heading: "Gleichnis vom großen Gastmahl", footnotes: ["℘ vgl. Mt 22,2-10", "w. Brot essen", "o. in der Königsherrschaft", "℘ Kap. 13,29 ⇨Esyn: Synopse Nr. 216"] },
      { number: 16, text: "Er aber sprach zu ihm: Ein Mensch machte ein großes Gastmahl* und lud viele ein.", footnotes: ["Das griech. Wort bezeichnet die abendliche Hauptmahlzeit, zu der oft Gäste geladen wurden."] },
      { number: 17, text: "Und er sandte seinen Knecht* zur Stunde des Gastmahls, um den Eingeladenen zu sagen: Kommt! Denn schon ist alles bereit.", footnotes: ["w. Sklaven; so auch V. 21—23"] },
      { number: 18, text: "Und sie fingen alle ohne Ausnahme an, sich zu entschuldigen. Der erste sprach zu ihm: Ich habe einen Acker gekauft und muss unbedingt hinausgehen und ihn besehen; ich bitte dich, halte mich für entschuldigt." },
      { number: 19, text: "Und ein anderer sprach: Ich habe fünf Joch Ochsen gekauft, und ich gehe hin, sie zu erproben; ich bitte dich, halte mich für entschuldigt." },
      { number: 20, text: "Und ein anderer sprach: Ich habe eine Frau geheiratet, und darum kann ich nicht kommen*.", footnotes: ["℘ 1Kor 7,33"] },
      { number: 21, text: "Und der Knecht kam herbei und berichtete dies seinem Herrn. Da wurde der Hausherr zornig* und sprach zu seinem Knecht: Geh schnell hinaus auf die Straßen und Gassen der Stadt und bringe die Armen und Krüppel und Blinden und Lahmen hier herein*!", footnotes: ["℘ Spr 1,24", "℘ V. 13"] },
      { number: 22, text: "Und der Knecht sprach: Herr, es ist geschehen, wie du befohlen hast, und es ist noch Raum." },
      { number: 23, text: "Und der Herr sprach zu dem Knecht: Geh hinaus auf die Wege und <an die> Zäune und nötige <sie> hereinzukommen, dass mein Haus voll werde!" },
      { number: 24, text: "Denn ich sage euch, dass nicht einer jener Männer, die eingeladen waren, mein Gastmahl* schmecken wird.", footnotes: ["Das griech. Wort bezeichnet die abendliche Hauptmahlzeit, zu der oft Gäste geladen wurden."] },
      { number: 25, text: "Es gingen aber große Volksmengen mit ihm; und er wandte sich um und sprach zu ihnen: *", heading: "Bedingungen der Nachfolge", footnotes: ["℘ ⇨Esyn: Synopse Nr. 217"] },
      { number: 26, text: "Wenn jemand zu mir kommt und hasst nicht seinen Vater und die Mutter und die Frau und die Kinder und die Brüder und die Schwestern*, dazu aber auch sein eigenes Leben*, so kann er nicht mein Jünger sein;", footnotes: ["℘ Kap. 18,29; 5Mo 33,9; Mt 10,37", "o. seine eigene Seele\n℘ Mt 10,39; Offb 12,11"] },
      { number: 27, text: "und wer nicht sein Kreuz trägt und mir nachkommt, kann nicht mein Jünger sein*.", footnotes: ["℘ Kap. 9,23 ⇨Esyn: Synopse Nr. 160"] },
      { number: 28, text: "Denn wer unter euch, der einen Turm bauen will, setzt sich nicht vorher hin und berechnet die Kosten, ob er <das Nötige> zur Ausführung habe?" },
      { number: 29, text: "Damit nicht etwa, wenn er den Grund gelegt hat und nicht vollenden kann, alle, die es sehen, anfangen, ihn zu verspotten," },
      { number: 30, text: "und sagen: Dieser Mensch hat angefangen zu bauen und konnte nicht vollenden." },
      { number: 31, text: "Oder welcher König, der auszieht, um sich mit einem anderen König in Krieg einzulassen, setzt sich nicht vorher hin und ratschlagt, ob er imstande sei, dem mit zehntausend entgegenzutreten, der gegen ihn mit zwanzigtausend anrückt*?", footnotes: ["℘ Spr 20,18"] },
      { number: 32, text: "Wenn aber nicht, so sendet er, während er noch fern ist, eine Gesandtschaft und bittet um die Friedensbedingungen." },
      { number: 33, text: "So kann nun keiner von euch, der nicht allem entsagt, was er hat, mein Jünger sein*.", footnotes: ["℘ Kap. 5,11"] },
      { number: 34, text: "Das Salz nun ist gut. Wenn aber auch das Salz kraftlos geworden ist, womit soll es gewürzt werden*?", footnotes: ["℘ Mt 5,13 ⇨Esyn: Synopse Nr. 218"] },
      { number: 35, text: "Es ist weder für das Land noch für den Dünger tauglich; man wirft es hinaus. Wer Ohren hat zu hören, der höre*!", footnotes: ["℘ Kap. 8,8"] },
    ]},
    { number: 15, verses: [
      { number: 1, text: "*Es nahten sich* aber zu ihm alle Zöllner und Sünder, ihn zu hören*;", heading: "Gleichnisse vom verlorenen Schaf und von der verlorenen Drachme", footnotes: ["℘ V. 1-7: vgl. Mt 18,11-13", "o. pflegten sich ihm zu nahen. — Der griech. Ausdruck bezeichnet eine fortgesetzte Handlung.", "℘ Mk 2,15 ⇨Esyn: Synopse Nr. 219"] },
      { number: 2, text: "und die Pharisäer und die Schriftgelehrten murrten und sprachen: Dieser nimmt Sünder auf und isst mit ihnen*.", footnotes: ["℘ Kap. 5,30"] },
      { number: 3, text: "Er sprach aber zu ihnen dieses Gleichnis und sagte: *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 169"] },
      { number: 4, text: "Welcher Mensch unter euch, der hundert Schafe hat und eins von ihnen verloren hat, lässt nicht die neunundneunzig in der Wüste und geht dem verlorenen nach, bis er es findet?" },
      { number: 5, text: "Und wenn er es gefunden hat, so legt er es mit Freuden auf seine Schultern*;", footnotes: ["℘ Hes 34,16"] },
      { number: 6, text: "und wenn er nach Hause kommt, ruft er die Freunde und die Nachbarn zusammen und spricht zu ihnen: Freut euch mit mir! Denn ich habe mein Schaf gefunden, das verloren war*.", footnotes: ["℘ Kap. 19,10; Mt 18,11"] },
      { number: 7, text: "Ich sage euch: So wird Freude im Himmel sein über einen Sünder, der Buße tut, <mehr> als über neunundneunzig Gerechte, die die Buße nicht nötig haben*.", footnotes: ["℘ Kap. 5,32"] },
      { number: 8, text: "Oder welche Frau, die zehn Drachmen hat, zündet nicht, wenn sie eine Drachme verliert, eine Lampe an und kehrt das Haus und sucht sorgfältig, bis sie sie findet? *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 220"] },
      { number: 9, text: "Und wenn sie sie gefunden hat, ruft sie die Freundinnen und Nachbarinnen zusammen und spricht: Freut euch mit mir! Denn ich habe die Drachme gefunden, die ich verloren hatte." },
      { number: 10, text: "So, sage ich euch, ist Freude vor den Engeln Gottes über einen Sünder, der Buße tut*.", footnotes: ["℘ Hes 18,23"] },
      { number: 11, text: "Er sprach aber: Ein Mensch hatte zwei Söhne; *", heading: "Gleichnis vom verlorenen Sohn", footnotes: ["℘ ⇨Esyn: Synopse Nr. 221"] },
      { number: 12, text: "und der jüngere von ihnen sprach zu dem Vater: Vater, gib mir den Teil des Vermögens, der mir zufällt! Und er teilte ihnen die Habe." },
      { number: 13, text: "Und nach nicht vielen Tagen brachte der jüngere Sohn alles zusammen und reiste weg in ein fernes Land, und dort vergeudete er sein Vermögen, indem er verschwenderisch lebte*.", footnotes: ["℘ Spr 29,3"] },
      { number: 14, text: "Als er aber alles verzehrt hatte, kam eine gewaltige Hungersnot über jenes Land, und er selbst fing an, Mangel zu leiden*.", footnotes: ["℘ Spr 23,21"] },
      { number: 15, text: "Und er ging hin und hängte sich an einen der Bürger jenes Landes, der schickte ihn auf seine Äcker, Schweine zu hüten." },
      { number: 16, text: "Und er begehrte seinen Bauch zu füllen mit den Schoten*, die die Schweine fraßen; und niemand gab <sie> ihm.", footnotes: ["des Johannisbrotbaumes; ein Nahrungsmittel für Tiere und wohl auch für arme Leute"] },
      { number: 17, text: "Als er aber zu sich kam, sprach er: Wie viele Tagelöhner meines Vaters haben Überfluss an Brot, ich aber komme hier um vor Hunger." },
      { number: 18, text: "Ich will mich aufmachen und zu meinem Vater gehen und will zu ihm sagen: Vater, ich habe gesündigt gegen den Himmel und vor dir*;", footnotes: ["℘ Ps 32,5"] },
      { number: 19, text: "ich bin nicht mehr würdig, dein Sohn zu heißen! Mach mich wie einen deiner Tagelöhner!" },
      { number: 20, text: "Und er machte sich auf und ging zu seinem Vater. Als er aber noch fern war, sah ihn sein Vater und wurde innerlich bewegt* und lief hin und fiel ihm um seinen Hals und küsste ihn*.", footnotes: ["℘ Kap. 7,13; Jer 31,20", "o. küsste ihn zärtlich o. mehrfach\n℘ Jes 55,7"] },
      { number: 21, text: "Der Sohn aber sprach zu ihm: Vater, ich habe gesündigt gegen den Himmel und vor dir*; ich bin nicht mehr würdig, dein Sohn zu heißen.", footnotes: ["℘ Hi 33,27; Spr 28,13; Mi 7,9; 1Jo 1,9"] },
      { number: 22, text: "Der Vater aber sprach zu seinen Sklaven: Bringt schnell das beste Gewand heraus und zieht es ihm an und tut einen Ring an seine Hand und Sandalen an seine Füße*;", footnotes: ["℘ Jes 61,10; Sach 3,3-5"] },
      { number: 23, text: "und bringt das gemästete Kalb her und schlachtet es, und lasst uns essen und fröhlich sein!" },
      { number: 24, text: "Denn dieser mein Sohn war tot und ist wieder lebendig geworden*, war verloren und ist gefunden worden. Und sie fingen an, fröhlich zu sein.", footnotes: ["℘ Eph 2,1.5"] },
      { number: 25, text: "Sein älterer Sohn aber war auf dem Feld; und als er kam und sich dem Haus näherte, hörte er Musik und Reigen." },
      { number: 26, text: "Und er rief einen der Diener herbei und erkundigte sich, was das sei." },
      { number: 27, text: "Der aber sprach zu ihm: Dein Bruder ist gekommen, und dein Vater hat das gemästete Kalb geschlachtet, weil er ihn gesund wiedererhalten hat." },
      { number: 28, text: "Er aber wurde zornig und wollte nicht hineingehen. Sein Vater aber ging hinaus und redete ihm zu." },
      { number: 29, text: "Er aber antwortete und sprach zu dem Vater: Siehe, so viele Jahre diene ich dir, und niemals habe ich ein Gebot von dir übertreten; und mir hast du niemals ein Böckchen gegeben, dass ich mit meinen Freunden fröhlich gewesen wäre;" },
      { number: 30, text: "da aber dieser dein Sohn gekommen ist, der deine Habe mit Huren durchgebracht hat, hast du ihm das gemästete Kalb geschlachtet." },
      { number: 31, text: "Er aber sprach zu ihm: Kind, du bist allezeit bei mir, und alles, was mein ist, ist dein." },
      { number: 32, text: "Aber man muss <doch jetzt> fröhlich sein und sich freuen; denn dieser dein Bruder war tot und ist wieder lebendig geworden* und verloren und ist gefunden worden.", footnotes: ["℘ Eph 2,1.5"] },
    ]},
    { number: 16, verses: [
      { number: 1, text: "Er sprach aber auch zu den Jüngern: Es war ein reicher Mann, der einen Verwalter hatte; und dieser wurde bei ihm angeklagt, als verschwende er seine Habe. *", heading: "Gleichnis vom ungerechten Verwalter", footnotes: ["℘ ⇨Esyn: Synopse Nr. 222"] },
      { number: 2, text: "Und er rief ihn und sprach zu ihm: Was ist es, das ich von dir höre? Lege die Rechnung von deiner Verwaltung ab! Denn du wirst nicht mehr Verwalter sein können." },
      { number: 3, text: "Der Verwalter aber sprach bei sich selbst: Was soll ich tun? Denn mein Herr nimmt mir die Verwaltung ab. Graben kann ich nicht, zu betteln schäme ich mich." },
      { number: 4, text: "Ich weiß, was ich tun werde, damit sie mich, wenn ich der Verwaltung enthoben bin, in ihre Häuser aufnehmen." },
      { number: 5, text: "Und er rief jeden Einzelnen der Schuldner seines Herrn herbei und sprach zu dem ersten: Wie viel bist du meinem Herrn schuldig?" },
      { number: 6, text: "Der aber sprach: Hundert Bat Öl. Und er sprach zu ihm: Nimm deinen Schuldbrief und setze dich schnell hin und schreibe fünfzig!" },
      { number: 7, text: "Danach sprach er zu einem anderen: Du aber, wie viel bist du schuldig? Der aber sprach: Hundert Kor Weizen. Und er spricht zu ihm: Nimm deinen Schuldbrief und schreibe achtzig!" },
      { number: 8, text: "Und der Herr lobte den ungerechten Verwalter*, weil er klug gehandelt hatte; denn die Söhne dieser Welt* sind klüger als die Söhne des Lichts* gegen ihr eigenes Geschlecht.", footnotes: ["w. den Haushalter der Ungerechtigkeit", "o. dieses Zeitalters (griech. Äon)", "℘ Joh 12,36"] },
      { number: 9, text: "Und ich sage euch: Macht euch Freunde mit dem ungerechten Mammon*, damit, wenn er zu Ende geht, man euch aufnehme in die ewigen Zelte*!", footnotes: ["d. h. Besitz, o. Vermögen", "℘ 1Tim 6,19"] },
      { number: 10, text: "Wer im Geringsten treu ist, ist auch in vielem treu*, und wer im Geringsten ungerecht ist, ist auch in vielem ungerecht.", footnotes: ["℘ Kap. 19,17 ⇨Esyn: Synopse Nr. 223"] },
      { number: 11, text: "Wenn ihr nun mit dem ungerechten Mammon* nicht treu gewesen seid, wer wird euch das Wahrhaftige anvertrauen?", footnotes: ["d. h. Besitz, o. Vermögen"] },
      { number: 12, text: "Und wenn ihr mit dem Fremden nicht treu gewesen seid, wer wird euch das Eure geben?" },
      { number: 13, text: "Kein Haussklave kann zwei Herren dienen; denn entweder wird er den einen hassen und den anderen lieben, oder er wird dem einen anhängen und den anderen verachten. Ihr könnt nicht Gott dienen und dem Mammon*.", footnotes: ["d. h. Besitz, o. Vermögen\n℘ Mt 6,24 ⇨Esyn: Synopse Nr. 224"] },
      { number: 14, text: "Dies alles hörten aber auch die Pharisäer, die geldliebend waren, und sie verhöhnten ihn. *", heading: "Gesetz und Evangelium", footnotes: ["℘ ⇨Esyn: Synopse Nr. 225"] },
      { number: 15, text: "Und er sprach zu ihnen: Ihr seid es, die sich selbst rechtfertigen vor den Menschen*, Gott aber kennt eure Herzen*; denn was unter den Menschen hoch ist, ist ein Gräuel vor Gott*.", footnotes: ["℘ Kap. 10,29", "℘ Kap. 5,22; Ps 7,10", "℘ Spr 6,16.17"] },
      { number: 16, text: "Das Gesetz und die Propheten <gehen> bis auf Johannes; von da an wird die gute Botschaft vom Reich* Gottes verkündigt*, und jeder dringt mit Gewalt hinein*.", footnotes: ["o. der Königsherrschaft", "o. wird das Reich Gottes <als Evangelium> verkündigt\n℘ Kap. 10,9", "℘ Mt 11,12.13 ⇨Esyn: Synopse Nr. 226"] },
      { number: 17, text: "Es ist aber leichter, dass der Himmel und die Erde vergehen, als dass ein Strichlein des Gesetzes wegfalle*.", footnotes: ["℘ Kap. 21,33; Mt 5,18"] },
      { number: 18, text: "Jeder, der seine Frau entlässt und eine andere heiratet, begeht Ehebruch; und jeder, der die von einem Mann Entlassene heiratet, begeht Ehebruch*.", footnotes: ["℘ Mt 5,32; Röm 7,2.3"] },
      { number: 19, text: "Es war aber ein reicher Mann, und er kleidete sich in Purpur und feine Leinwand und lebte alle Tage fröhlich und in Prunk*.", heading: "Der reiche Mann und der arme Lazarus", footnotes: ["℘ Jak 5,5 ⇨Esyn: Synopse Nr. 228"] },
      { number: 20, text: "Ein Armer aber, mit Namen Lazarus, lag an dessen Tor, voller Geschwüre," },
      { number: 21, text: "und er begehrte, sich mit den Abfällen vom Tisch des Reichen zu sättigen; aber auch die Hunde kamen und leckten seine Geschwüre." },
      { number: 22, text: "Es geschah aber, dass der Arme starb und von den Engeln in Abrahams Schoß getragen wurde*. Es starb aber auch der Reiche und wurde begraben*.", footnotes: ["℘ Hebr 1,14", "℘ Hi 21,13"] },
      { number: 23, text: "Und als er im Hades* seine Augen aufschlug und in Qualen war, sieht er Abraham von weitem und Lazarus in seinem Schoß.", footnotes: ["d. i. das Totenreich"] },
      { number: 24, text: "Und er rief und sprach: Vater Abraham, erbarme dich meiner und sende Lazarus, dass er die Spitze seines Fingers ins Wasser tauche und meine Zunge kühle! Denn ich leide Pein in dieser Flamme*.", footnotes: ["℘ Mt 8,12; 25,41.46; Mk 9,48"] },
      { number: 25, text: "Abraham aber sprach: Kind, gedenke, dass du dein Gutes völlig empfangen hast in deinem Leben* und Lazarus ebenso das Böse; jetzt aber wird er hier getröstet*, du aber leidest Pein*.", footnotes: ["℘ Ps 17,14", "℘ Mt 5,4", "℘ Kap. 6,24"] },
      { number: 26, text: "Und zu diesem allen ist zwischen uns und euch eine große Kluft festgelegt, damit die, welche von hier zu euch hinübergehen wollen, es nicht können, noch die, welche von dort zu uns herüberkommen wollen." },
      { number: 27, text: "Er sprach aber: Ich bitte dich nun, Vater, dass du ihn in das Haus meines Vaters sendest," },
      { number: 28, text: "denn ich habe fünf Brüder, dass er ihnen eindringlich Zeugnis ablege*, damit sie nicht auch an diesen Ort der Qual kommen!", footnotes: ["o. dass er sie dringend ermahne; o. dass er sie beschwöre"] },
      { number: 29, text: "Abraham aber spricht: Sie haben Mose und die Propheten. Mögen sie die hören*!", footnotes: ["℘ Jes 8,20; 2Tim 3,15"] },
      { number: 30, text: "Er aber sprach: Nein, Vater Abraham, sondern wenn jemand von den Toten zu ihnen geht, so werden sie Buße tun." },
      { number: 31, text: "Er sprach aber zu ihm: Wenn sie Mose und die Propheten nicht hören*, so werden sie auch nicht überzeugt werden, wenn jemand aus den Toten aufersteht*.", footnotes: ["℘ Joh 5,47", "℘ Joh 12,10"] },
    ]},
    { number: 17, verses: [
      { number: 1, text: "Er sprach aber zu seinen Jüngern: Es ist unmöglich, dass nicht Verführungen* kommen. Wehe aber dem, durch den sie kommen*!", heading: "Warnung vor Verführung zur Sünde — Ermahnungen vom Vergeben, Glauben und Dienen", footnotes: ["o. Anlässe zur Sünde; o. Ärgernisse", "℘ Kap. 22,22; Mt 18,7 ⇨Esyn: Synopse Nr. 229"] },
      { number: 2, text: "Es wäre ihm nützlicher, wenn ein Mühlstein um seinen Hals gelegt und er ins Meer geworfen würde, als dass er einem dieser Kleinen Anlass zur Sünde gäbe*!", footnotes: ["o. Anstoß gäbe; o. eines . . . ärgerte\n℘ Mt 18,6.10"] },
      { number: 3, text: "Habt acht auf euch selbst*: Wenn dein Bruder sündigt*, so weise ihn zurecht*, und wenn er es bereut, so vergib ihm*!", footnotes: ["℘ Apg 20,28; 1Tim 4,16; 2Jo 8", "℘ Mt 18,15", "℘ 3Mo 19,17", "℘ Eph 4,32; Kol 3,13 ⇨Esyn: Synopse Nr. 230"] },
      { number: 4, text: "Und wenn er siebenmal am Tag an dir sündigt und siebenmal zu dir umkehrt und spricht: Ich bereue es; so sollst du ihm vergeben*.", footnotes: ["℘ Mt 18,21.22"] },
      { number: 5, text: "Und die Apostel sprachen zu dem Herrn: Mehre uns den Glauben*!", footnotes: ["℘ Mk 9,24 ⇨Esyn: Synopse Nr. 231"] },
      { number: 6, text: "Der Herr aber sprach: Wenn ihr Glauben habt wie ein Senfkorn, so würdet ihr zu diesem Maulbeerfeigenbaum sagen: Entwurzele dich und pflanze dich ins Meer! Und er würde euch gehorchen*.", footnotes: ["℘ Mt 17,20"] },
      { number: 7, text: "Wer aber von euch, der einen Sklaven hat, der pflügt oder hütet, wird zu ihm, wenn er vom Feld hereinkommt, sagen: Komm und leg dich sogleich zu Tisch? *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 232"] },
      { number: 8, text: "Wird er nicht vielmehr zu ihm sagen: Richte zu, was ich zu Abend essen soll, und gürte dich und diene mir, bis ich gegessen und getrunken habe; und danach sollst du essen und trinken?" },
      { number: 9, text: "Dankt er etwa dem Sklaven, dass er das Befohlene getan hat? *Ich meine nicht.*", footnotes: ["in mehreren alten Handschr. nicht enthalten", "in mehreren alten Handschr. nicht enthalten"] },
      { number: 10, text: "So sprecht auch ihr, wenn ihr alles getan habt, was euch befohlen ist: Wir sind unnütze Sklaven; wir haben getan, was wir zu tun schuldig waren." },
      { number: 11, text: "Und es geschah, als er nach Jerusalem reiste, dass er mitten durch Samaria* und Galiläa ging.", heading: "Heilung von zehn Aussätzigen", footnotes: ["℘ Kap. 9,51.52 ⇨Esyn: Synopse Nr. 233"] },
      { number: 12, text: "Und als er in ein Dorf einzog, begegneten ihm zehn aussätzige* Männer, die von fern standen*.", footnotes: ["»Aussatz« umfasste in bibl. Zeit mehrere Hautkrankheiten; s. auch Anm. zu Mt 8,2", "℘ 3Mo 13,46; 4Mo 5,2"] },
      { number: 13, text: "Und sie erhoben ihre Stimme und sprachen: Jesus, Meister, erbarme dich unser*!", footnotes: ["℘ Kap. 18,38"] },
      { number: 14, text: "Und als er <sie> sah, sprach er zu ihnen: Geht hin und zeigt euch den Priestern*! Und es geschah, während sie hingingen, wurden sie gereinigt.", footnotes: ["℘ Kap. 5,14"] },
      { number: 15, text: "Einer aber von ihnen kehrte zurück, als er sah, dass er geheilt war, und verherrlichte Gott mit lauter Stimme*;", footnotes: ["℘ Kap. 5,26"] },
      { number: 16, text: "und er fiel aufs Angesicht zu seinen Füßen und dankte ihm; und das war ein Samariter." },
      { number: 17, text: "Jesus aber antwortete und sprach: Sind nicht die Zehn gereinigt worden? Wo sind die Neun?" },
      { number: 18, text: "Haben sich sonst keine gefunden, die zurückkehrten, um Gott Ehre zu geben, außer diesem Fremdling?" },
      { number: 19, text: "Und er sprach zu ihm: Steh auf und geh hin! Dein Glaube hat dich gerettet*.", footnotes: ["℘ Kap. 7,50"] },
      { number: 20, text: "*Und als er von den Pharisäern gefragt wurde: Wann kommt das Reich* Gottes*?, antwortete er ihnen und sprach: Das Reich* Gottes kommt nicht so, dass man es beobachten könnte*;", heading: "Das Reich Gottes und der Tag des Menschensohnes", footnotes: ["℘ V. 22-36: vgl. Mt 24,17.18.23-28.37-41", "o. die Königsherrschaft", "℘ Kap. 11,2; 19,11; Apg 1,6", "o. die Königsherrschaft", "w. mit Beobachtung\n℘ Joh 18,36 ⇨Esyn: Synopse Nr. 291"] },
      { number: 21, text: "auch wird man nicht sagen: Siehe hier! Oder: Siehe dort*! Denn siehe, das Reich* Gottes ist mitten unter* euch*.", footnotes: ["℘ Mt 24,23", "o. die Königsherrschaft", "o. ist innerhalb von", "℘ Kap. 11,20 ⇨Esyn: Synopse Nr. 235"] },
      { number: 22, text: "Er sprach aber zu den Jüngern: Es werden Tage kommen, da ihr begehren werdet, einen der Tage des Sohnes des Menschen zu sehen, und ihr werdet <ihn> nicht sehen. *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 235"] },
      { number: 23, text: "Und man wird zu euch sagen: Siehe dort!, oder: Siehe hier! Geht nicht hin, folgt auch nicht*!", footnotes: ["℘ Kap. 21,8"] },
      { number: 24, text: "Denn wie der Blitz blitzend leuchtet von einem <Ende> unter dem Himmel bis zum anderen <Ende> unter dem Himmel, so wird der Sohn des Menschen sein an seinem Tag." },
      { number: 25, text: "Vorher aber muss er vieles leiden und verworfen werden von diesem Geschlecht*.", footnotes: ["℘ Kap. 9,22; Dan 9,26"] },
      { number: 26, text: "Und wie es in den Tagen Noahs geschah, so wird es auch sein in den Tagen des Sohnes des Menschen:" },
      { number: 27, text: "Sie aßen, sie tranken, sie heirateten, sie wurden verheiratet bis zu dem Tag, da Noah in die Arche ging und die Flut kam und alle umbrachte*.", footnotes: ["℘ 1Mo 7,23; 1Thes 5,2.3"] },
      { number: 28, text: "Ebenso auch, wie es geschah in den Tagen Lots: Sie aßen, sie tranken, sie kauften, sie verkauften, sie pflanzten, sie bauten;" },
      { number: 29, text: "an dem Tag aber, da Lot von Sodom hinausging, regnete es Feuer und Schwefel vom Himmel und brachte alle um*.", footnotes: ["℘ 1Mo 19,24.25"] },
      { number: 30, text: "Ebenso wird es an dem Tag sein, da der Sohn des Menschen offenbart wird*.", footnotes: ["℘ 2Thes 1,7-10"] },
      { number: 31, text: "An jenem Tag — wer auf dem Dach sein wird und sein Gerät im Haus hat, der steige nicht hinab, um es zu holen; und wer auf dem Feld ist, wende sich ebenso wenig zurück*.", footnotes: ["℘ 1Mo 19,17; Mk 13,15.16"] },
      { number: 32, text: "Gedenkt an Lots Frau*!", footnotes: ["℘ 1Mo 19,26"] },
      { number: 33, text: "Wer sein Leben* zu retten sucht, wird es verlieren; und wer es verliert, wird es erhalten*.", footnotes: ["o. seine Seele", "℘ Kap. 9,24 ⇨Esyn: Synopse Nr. 302"] },
      { number: 34, text: "Ich sage euch: In jener Nacht werden zwei auf einem Bett sein; einer wird genommen und der andere gelassen werden." },
      { number: 35, text: "Zwei werden zusammen mahlen; die eine wird genommen, die andere gelassen werden." },
      { number: 36, text: "[T>]*", footnotes: ["Andere Handschr. fügen hinzu: Zwei <Männer> werden auf dem Feld sein; einer wird genommen werden, und der andere wird zurückgelassen werden."] },
      { number: 37, text: "Und sie antworten und sagen zu ihm: Wo, Herr? Er aber sprach zu ihnen: Wo der Leichnam ist, da sammeln sich auch die Adler*.", footnotes: ["o. Geier\n℘ Hi 39,30"] },
    ]},
    { number: 18, verses: [
      { number: 1, text: "Er sagte ihnen aber auch ein Gleichnis dafür, dass sie allezeit beten und nicht ermatten sollten*,", heading: "Gleichnis vom ungerechten Richter", footnotes: ["℘ Kap. 21,36; Apg 1,14; Röm 12,12; Eph 6,18; Kol 4,2; 1Thes 5,17 ⇨Esyn: Synopse Nr. 236"] },
      { number: 2, text: "und sprach: Es war ein Richter in einer Stadt, der Gott nicht fürchtete und vor keinem Menschen sich scheute." },
      { number: 3, text: "Es war aber eine Witwe in jener Stadt; und sie kam zu ihm und sprach: Schaffe mir Recht gegenüber meinem Widersacher*!", footnotes: ["℘ Jes 1,17"] },
      { number: 4, text: "Und eine Zeit lang wollte er nicht*; danach aber sprach er bei sich selbst: Wenn ich auch Gott nicht fürchte und vor keinem Menschen mich scheue,", footnotes: ["℘ Jes 1,23"] },
      { number: 5, text: "so will ich doch, weil diese Witwe mir Mühe macht, ihr Recht verschaffen, damit sie nicht am Ende komme und mir ins Gesicht fahre*.", footnotes: ["℘ Kap. 11,8"] },
      { number: 6, text: "Der Herr aber sprach: Hört, was der ungerechte Richter sagt!" },
      { number: 7, text: "Gott aber, sollte er das Recht seiner Auserwählten nicht ausführen, die Tag und Nacht zu ihm schreien*, und sollte er es bei ihnen lange hinziehen?", footnotes: ["℘ Ps 55,18; 88,2"] },
      { number: 8, text: "Ich sage euch, dass er ihr Recht ohne Verzug ausführen wird. Doch wird wohl der Sohn des Menschen, wenn er kommt, den Glauben finden auf der Erde?" },
      { number: 9, text: "Er sprach aber auch zu einigen, die auf sich selbst vertrauten, dass sie gerecht seien, und die Übrigen verachteten, dieses Gleichnis: *", heading: "Gleichnis vom Pharisäer und Zöllner", footnotes: ["℘ ⇨Esyn: Synopse Nr. 237"] },
      { number: 10, text: "Zwei Menschen gingen hinauf in den Tempel, um zu beten, der eine ein Pharisäer* und der andere ein Zöllner.", footnotes: ["religiöse Partei im Judentum, die auf genaue Einhaltung des Gesetzes Wert legte; s. auch Anm. zu Mt 3,7"] },
      { number: 11, text: "Der Pharisäer stand und betete bei sich selbst so: Gott, ich danke dir, dass ich nicht bin wie die Übrigen der Menschen: Räuber, Ungerechte, Ehebrecher oder auch wie dieser Zöllner." },
      { number: 12, text: "Ich faste zweimal in der Woche, ich verzehnte alles, was ich erwerbe*.", footnotes: ["℘ Kap. 11,42; Mt 9,14; 23,23"] },
      { number: 13, text: "Der Zöllner aber stand weitab und wollte sogar die Augen nicht aufheben zum Himmel, sondern schlug an seine Brust und sprach: Gott, sei mir, dem Sünder, gnädig*!", footnotes: ["℘ Esr 9,6; Ps 51,3"] },
      { number: 14, text: "Ich sage euch: Dieser ging gerechtfertigt hinab in sein Haus, im Gegensatz zu jenem*; denn jeder, der sich selbst erhöht, wird erniedrigt werden; wer aber sich selbst erniedrigt, wird erhöht werden*.", footnotes: ["℘ Mt 21,31", "℘ Kap. 14,11"] },
      { number: 15, text: "*Sie brachten aber auch die <kleinen> Kinder* zu ihm, dass er sie anrühre. Als aber die Jünger es sahen, fuhren sie sie an. *", heading: "Jesus und die Kinder", footnotes: ["℘ Mt 19,13-15; Mk 10,13-16", "w. Säuglinge", "℘ ⇨Esyn: Synopse Nr. 253"] },
      { number: 16, text: "Jesus aber rief sie herbei und sprach: Lasst die Kinder zu mir kommen und wehrt ihnen nicht! Denn solchen gehört das Reich* Gottes.", footnotes: ["o. die Königsherrschaft"] },
      { number: 17, text: "Wahrlich, ich sage euch: Wer das Reich* Gottes nicht annehmen wird wie ein Kind, wird nicht hineinkommen.", footnotes: ["o. die Königsherrschaft"] },
      { number: 18, text: "*Und es fragte ihn ein Oberster und sprach: Guter Lehrer, was muss ich getan haben, um ewiges Leben zu erben*?", heading: "Frage eines Reichen nach dem ewigen Leben", footnotes: ["℘ Mt 19,16-30; Mk 10,17-31", "℘ Kap. 10,25 ⇨Esyn: Synopse Nr. 254"] },
      { number: 19, text: "Jesus aber sprach zu ihm: Was nennst du mich gut? Niemand ist gut als nur einer, Gott." },
      { number: 20, text: "Die Gebote weißt du: »Du sollst nicht ehebrechen*; du sollst nicht töten*; du sollst nicht stehlen; du sollst nicht falsches Zeugnis geben; ehre deinen Vater und die Mutter!«*", footnotes: ["℘ Mt 5,27", "℘ Mt 5,21", "℘ 2Mo 20,12-16; Mt 15,4"] },
      { number: 21, text: "Er aber sprach: Dies alles habe ich befolgt* von meiner Jugend an.", footnotes: ["o. beachtet, eingehalten"] },
      { number: 22, text: "Als aber Jesus dies hörte, sprach er zu ihm: Eins fehlt dir noch: Verkaufe alles, was du hast, und verteile <den Erlös> an die Armen, und du wirst einen Schatz in den Himmeln haben, und komm, folge mir nach*!", footnotes: ["℘ Kap. 12,33; Mt 6,20"] },
      { number: 23, text: "Als er aber dies hörte, wurde er sehr betrübt, denn er war sehr reich." },
      { number: 24, text: "Als aber Jesus sah, dass er sehr betrübt wurde, sprach er: Wie schwer werden die, welche Güter haben, in das Reich* Gottes hineinkommen! *", footnotes: ["o. der/die Königsherrschaft", "℘ ⇨Esyn: Synopse Nr. 255"] },
      { number: 25, text: "Denn es ist leichter, dass ein Kamel durch ein Nadelöhr geht, als dass ein Reicher in das Reich* Gottes hineinkommt.", footnotes: ["o. der/die Königsherrschaft"] },
      { number: 26, text: "Es sprachen aber, die es hörten: Und wer kann <dann> gerettet werden?" },
      { number: 27, text: "Er aber sprach: Was bei Menschen unmöglich ist, ist möglich bei Gott*.", footnotes: ["℘ Kap. 1,37"] },
      { number: 28, text: "Petrus aber sprach: Siehe, wir haben alles verlassen und sind dir nachgefolgt*.", footnotes: ["℘ Kap. 5,11"] },
      { number: 29, text: "Er aber sprach zu ihnen: Wahrlich, ich sage euch: Es ist niemand, der Haus oder Frau oder Brüder oder Eltern oder Kinder verlassen hat* um des Reiches* Gottes willen,", footnotes: ["℘ Kap. 14,26", "o. der/die Königsherrschaft"] },
      { number: 30, text: "der nicht Vielfältiges empfangen wird in dieser Zeit und in dem kommenden Zeitalter* ewiges Leben.", footnotes: ["griech. Äon"] },
      { number: 31, text: "*Er nahm aber die Zwölf zu sich und sprach zu ihnen: Siehe, wir gehen hinauf nach Jerusalem*, und es wird alles vollendet werden, was durch die Propheten auf den Sohn des Menschen hin geschrieben ist*;", heading: "Dritte Leidensankündigung", footnotes: ["℘ Mt 20,17-19; Mk 10,32-34", "℘ Kap. 9,51", "℘ Kap. 24,44; Mt 26,24 ⇨Esyn: Synopse Nr. 262"] },
      { number: 32, text: "denn er wird den Nationen überliefert werden und wird verspottet und geschmäht und angespien werden*;", footnotes: ["℘ Kap. 22,63; 23,11"] },
      { number: 33, text: "und wenn sie ihn gegeißelt haben, werden sie ihn töten, und am dritten Tag wird er auferstehen*.", footnotes: ["℘ Kap. 9,22; Mt 16,21"] },
      { number: 34, text: "Und sie verstanden nichts von diesen <Worten>*, und diese Rede war vor ihnen verborgen, und sie begriffen das Gesagte nicht*.", footnotes: ["℘ Joh 12,16", "℘ Kap. 2,50; Mk 9,10"] },
      { number: 35, text: "*Es geschah aber, als er sich Jericho näherte, saß ein Blinder bettelnd am Weg. *", heading: "Heilung eines Blinden", footnotes: ["℘ Mt 20,29-34; Mk 10,46-52; vgl. Mt 9,27-31; Mk 8,22-26", "℘ ⇨Esyn: Synopse Nr. 264"] },
      { number: 36, text: "Und als er eine Volksmenge vorbeiziehen hörte, erkundigte er sich, was das sei." },
      { number: 37, text: "Sie verkündeten ihm aber, dass Jesus, der Nazoräer*, vorübergehe.", footnotes: ["s. Anm. zu Mt 2,23\n℘ Mt 2,23"] },
      { number: 38, text: "Und er rief und sprach: Jesus, Sohn Davids, erbarme dich meiner*!", footnotes: ["℘ Kap. 17,13"] },
      { number: 39, text: "Und die Vorangehenden bedrohten ihn, dass er schweigen sollte; er aber schrie umso mehr: Sohn Davids, erbarme dich meiner*!", footnotes: ["℘ Kap. 17,13"] },
      { number: 40, text: "Jesus aber blieb stehen und befahl, dass er zu ihm gebracht werde. Als er sich aber näherte, fragte er ihn:" },
      { number: 41, text: "Was willst du, dass ich dir tun soll? Er aber sprach: Herr, dass ich sehend werde!" },
      { number: 42, text: "Und Jesus sprach zu ihm: Sei sehend! Dein Glaube hat dich geheilt*.", footnotes: ["w. gerettet\n℘ Kap. 7,50"] },
      { number: 43, text: "Und sofort wurde er sehend, folgte ihm nach und verherrlichte Gott*. Und das ganze Volk, das es sah, gab Gott Lob*.", footnotes: ["℘ Kap. 5,26", "℘ Kap. 13,17; Ps 50,23"] },
    ]},
    { number: 19, verses: [
      { number: 1, text: "Und er ging hinein und zog durch Jericho. *", heading: "Zachäus, der Oberzöllner", footnotes: ["℘ ⇨Esyn: Synopse Nr. 265"] },
      { number: 2, text: "Und siehe, <da war> ein Mann, mit Namen Zachäus genannt, und der war ein Oberzöllner und war reich." },
      { number: 3, text: "Und er suchte Jesus zu sehen*, wer er sei; und er konnte es nicht wegen der Volksmenge, denn er war klein von Gestalt.", footnotes: ["℘ Joh 12,21"] },
      { number: 4, text: "Und er lief voraus und stieg auf einen Maulbeerfeigenbaum, damit er ihn sehe; denn er sollte dort durchkommen." },
      { number: 5, text: "Und als er an den Ort kam, sah Jesus auf und erblickte ihn und sprach zu ihm: Zachäus, steig eilends herab! Denn heute muss ich in deinem Haus bleiben." },
      { number: 6, text: "Und er stieg eilends herab und nahm ihn auf mit Freuden." },
      { number: 7, text: "Und als sie es sahen, murrten alle und sagten: Er ist eingekehrt, um bei einem sündigen Mann zu herbergen*.", footnotes: ["℘ Kap. 5,30"] },
      { number: 8, text: "Zachäus aber stand und sprach zu dem Herrn: Siehe, Herr, die Hälfte meiner Güter gebe ich den Armen, und wenn ich von jemand etwas durch falsche Anklage genommen habe, so erstatte ich es vierfach*.", footnotes: ["℘ 2Mo 21,37; 2Sam 12,6"] },
      { number: 9, text: "Jesus aber sprach zu ihm: Heute ist diesem Haus Heil* widerfahren, weil auch er ein Sohn Abrahams ist*;", footnotes: ["o. Rettung", "℘ Kap. 13,16"] },
      { number: 10, text: "denn der Sohn des Menschen ist gekommen, zu suchen und zu retten, was verloren ist*.", footnotes: ["℘ Kap. 15,6; Mk 2,17"] },
      { number: 11, text: "*Während sie aber dies hörten, fügte er noch ein Gleichnis hinzu*, weil er nahe bei Jerusalem war, und sie meinten, dass das Reich* Gottes sogleich erscheinen sollte*.", heading: "Gleichnis von den anvertrauten Pfunden", footnotes: ["℘ vgl. Mt 25,14-30", "w. sprach er hinzufügend ein Gleichnis", "o. der/die Königsherrschaft", "℘ Kap. 17,20 ⇨Esyn: Synopse Nr. 266"] },
      { number: 12, text: "Er sprach nun: Ein hochgeborener Mann zog in ein fernes Land*, um ein Reich* für sich zu empfangen und wiederzukommen.", footnotes: ["℘ Mk 13,34", "o. eine Königsherrschaft"] },
      { number: 13, text: "Er berief aber zehn seiner Knechte* und gab ihnen zehn Pfunde* und sprach zu ihnen: Handelt <damit>, bis ich <wieder>komme!", footnotes: ["w. Sklaven; so auch V. 15—22", "w. Minen; s. Tabelle »Münzen und Geldeinheiten«; so auch V. 16—25"] },
      { number: 14, text: "Seine Bürger aber hassten ihn und schickten eine Gesandtschaft hinter ihm her und ließen sagen: Wir wollen nicht, dass dieser über uns König sei*!", footnotes: ["℘ Mk 5,17"] },
      { number: 15, text: "Und es geschah, als er zurückkam, nachdem er das Reich* empfangen hatte, da sagte er, man solle diese Knechte, denen er das Geld gegeben hatte, zu ihm rufen, damit er erfahre, was ein jeder erhandelt habe.", footnotes: ["o. die Königsherrschaft"] },
      { number: 16, text: "Der erste aber kam herbei und sagte: Herr, dein Pfund hat zehn Pfunde hinzugewonnen." },
      { number: 17, text: "Und er sprach zu ihm: Recht so, du guter Knecht! Weil du im Geringsten treu warst*, sollst du Vollmacht über zehn Städte haben.", footnotes: ["℘ Kap. 16,10"] },
      { number: 18, text: "Und der zweite kam und sagte: Herr, dein Pfund hat fünf Pfunde eingetragen." },
      { number: 19, text: "Er sprach aber auch zu diesem: Und du, sei über fünf Städte!" },
      { number: 20, text: "Und der andere kam und sagte: Herr, siehe, <hier ist> dein Pfund, das ich in einem Schweißtuch verwahrt hielt;" },
      { number: 21, text: "denn ich fürchtete dich, weil du ein strenger Mann bist; du nimmst, was du nicht hingelegt, und du erntest, was du nicht gesät hast." },
      { number: 22, text: "Er spricht zu ihm: Aus deinem Mund werde ich dich richten*, du böser Knecht! Du wusstest, dass ich ein strenger Mann bin, der ich nehme, was ich nicht hingelegt, und ernte, was ich nicht gesät habe?", footnotes: ["℘ 2Sam 1,16; Hi 15,6; Mt 12,37"] },
      { number: 23, text: "Und warum hast du mein Geld nicht auf eine Bank gegeben, und wenn ich kam, hätte ich es mit Zinsen eingefordert?" },
      { number: 24, text: "Und er sprach zu den Dabeistehenden: Nehmt das Pfund von ihm und gebt es dem, der die zehn Pfunde hat!" },
      { number: 25, text: "Und sie sprachen zu ihm: Herr, er hat <ja schon> zehn Pfunde!" },
      { number: 26, text: "Ich sage euch: Jedem, der da hat, wird gegeben werden; von dem aber, der nicht hat, von dem wird selbst, was er hat, weggenommen werden*.", footnotes: ["℘ Kap. 8,18 ⇨Esyn: Synopse Nr. 123"] },
      { number: 27, text: "Doch jene meine Feinde, die nicht wollten, dass ich über sie König würde, bringt her und erschlagt sie vor mir*!", footnotes: ["℘ Ps 2,9; Jes 66,6; Mt 21,41"] },
      { number: 28, text: "*Und als er dies gesagt hatte, zog er voran und ging hinauf nach Jerusalem*.", heading: "Einzug in Jerusalem — Ankündigung der Zerstörung Jerusalems", footnotes: ["℘ V. 28-40: Mt 21,1-11; Mk 11,1-10; Joh 12,12-19", "℘ Kap. 9,51 ⇨Esyn: Synopse Nr. 269"] },
      { number: 29, text: "Und es geschah, als er sich Betfage und Betanien näherte, gegen den Berg hin, der Ölberg genannt wird, sandte er zwei von den Jüngern" },
      { number: 30, text: "und sprach: Geht hin in das Dorf gegenüber, und wenn ihr hineinkommt, werdet ihr ein Fohlen darin angebunden finden, auf dem kein Mensch je gesessen hat; bindet es los und führt es <her>!" },
      { number: 31, text: "Und wenn jemand euch fragt: Warum bindet ihr es los?, sprecht so zu ihm: Der Herr braucht es." },
      { number: 32, text: "Und die Abgesandten gingen hin und fanden es, wie er ihnen gesagt hatte*.", footnotes: ["℘ Kap. 22,13"] },
      { number: 33, text: "Als sie aber das Fohlen losbanden, sprachen dessen Herren zu ihnen: Warum bindet ihr das Fohlen los?" },
      { number: 34, text: "Sie aber sprachen: Der Herr braucht es." },
      { number: 35, text: "Und sie führten es zu Jesus; und sie warfen ihre Kleider auf das Fohlen und setzten Jesus darauf*.", footnotes: ["℘ Sach 9,9"] },
      { number: 36, text: "Während er aber hinzog, breiteten sie ihre Kleider aus auf den Weg*.", footnotes: ["℘ 2Kö 9,13"] },
      { number: 37, text: "Und als er sich schon dem Abhang des Ölbergs näherte, fing die ganze Menge der Jünger an, mit lauter Stimme freudig Gott zu loben über alle die Wunderwerke*, die sie gesehen hatten*,", footnotes: ["o. Machttaten; griech. dynamis", "℘ Kap. 13,17"] },
      { number: 38, text: "und sie sagten: »Gepriesen <sei> der König, der da kommt im Namen des Herrn!«* Friede im Himmel und Herrlichkeit in der Höhe*!", footnotes: ["℘ Kap. 13,35", "℘ Kap. 2,14; Ps 148,1"] },
      { number: 39, text: "Und einige der Pharisäer aus der Volksmenge sprachen zu ihm: Lehrer, weise deine Jünger zurecht*!", footnotes: ["℘ Mt 21,16"] },
      { number: 40, text: "Und er antwortete und sprach zu ihnen: Ich sage euch, wenn diese schweigen, so werden die Steine schreien*.", footnotes: ["℘ Hab 2,11"] },
      { number: 41, text: "*Und als er sich näherte und die Stadt sah, weinte er über sie*", footnotes: ["℘ V. 41-44: Mt 23,37-39", "℘ 2Kö 8,11; Jer 8,23; 14,17; Kla 3,48.49; Joh 11,35 ⇨Esyn: Synopse Nr. 270"] },
      { number: 42, text: "und sprach: Wenn auch du an diesem Tag erkannt hättest, was zum Frieden <dient>! Jetzt aber ist es vor deinen Augen verborgen*.", footnotes: ["℘ 5Mo 32,29; Jes 6,9.10"] },
      { number: 43, text: "Denn Tage werden über dich kommen, da werden deine Feinde einen Wall um dich aufschütten und dich umzingeln und dich von allen Seiten einengen*;", footnotes: ["℘ Kap. 21,20; 5Mo 28,52; Jes 29,3; Jer 6,6"] },
      { number: 44, text: "und sie werden dich und deine Kinder in dir zu Boden werfen und werden in dir nicht einen Stein auf dem anderen* lassen*, dafür, dass du die Zeit deiner Heimsuchung nicht erkannt hast.", footnotes: ["w. Stein auf Stein", "℘ Kap. 21,6; Jes 6,11; Mi 3,12"] },
      { number: 45, text: "*Und als er in den Tempel eingetreten war, fing er an, die Verkäufer hinauszutreiben, *", heading: "Tempelreinigung — Die Frage nach der Vollmacht Jesu", footnotes: ["℘ Mt 21,12-16; Mk 11,15-18; vgl. Joh 2,13-17", "℘ ⇨Esyn: Synopse Nr. 273"] },
      { number: 46, text: "und sprach zu ihnen: Es steht geschrieben: »Mein Haus ist ein Bethaus«*; ihr aber habt es zu einer »Räuberhöhle« gemacht*.", footnotes: ["℘ Jes 56,7", "℘ Jer 7,11"] },
      { number: 47, text: "Und er lehrte täglich im Tempel*; die Hohenpriester aber und die Schriftgelehrten und die Ersten des Volkes suchten ihn umzubringen*.", footnotes: ["℘ Kap. 21,37; 22,53", "℘ Kap. 20,19; 22,2; Mt 12,14; Joh 11,53 ⇨Esyn: Synopse Nr. 332"] },
      { number: 48, text: "Und sie fanden nicht, was sie tun sollten, denn das ganze Volk hing ihm an und hörte auf ihn*.", footnotes: ["℘ Kap. 21,38; Mk 12,37"] },
    ]},
    { number: 20, verses: [
      { number: 1, text: "*Und es geschah an einem der Tage, als er das Volk im Tempel lehrte und <die> gute Botschaft verkündigte, da traten die Hohenpriester und die Schriftgelehrten mit den Ältesten herbei *", footnotes: ["℘ Mt 21,23-27; Mk 11,27-33", "℘ ⇨Esyn: Synopse Nr. 276"] },
      { number: 2, text: "und sprachen zu ihm und sagten: Sage uns, in welcher Vollmacht tust du diese Dinge? Oder wer ist es, der dir diese Vollmacht gegeben hat?" },
      { number: 3, text: "Er aber antwortete und sprach zu ihnen: Auch ich will euch ein Wort fragen; und sagt mir:" },
      { number: 4, text: "War die Taufe des Johannes vom Himmel oder von Menschen?" },
      { number: 5, text: "Sie aber überlegten miteinander und sprachen: Wenn wir sagen: vom Himmel, so wird er sagen: Warum habt ihr ihm nicht geglaubt*?", footnotes: ["℘ Mt 21,32"] },
      { number: 6, text: "Wenn wir aber sagen: von Menschen, so wird das ganze Volk uns steinigen*, denn es ist überzeugt, dass Johannes ein Prophet ist*.", footnotes: ["℘ Apg 5,26", "℘ Kap. 1,76"] },
      { number: 7, text: "Und sie antworteten, sie wüssten nicht, woher*.", footnotes: ["℘ 1Kor 1,19"] },
      { number: 8, text: "Und Jesus sprach zu ihnen: So sage auch ich euch nicht, in welcher Vollmacht ich dies tue." },
      { number: 9, text: "*Er fing aber an, zu dem Volk dieses Gleichnis zu sagen: Ein Mensch pflanzte einen Weinberg und verpachtete ihn an Weingärtner und reiste für lange Zeit außer Landes. *", heading: "Gleichnis von den Weingärtnern", footnotes: ["℘ Mt 21,33-46; Mk 12,1-12", "℘ ⇨Esyn: Synopse Nr. 278"] },
      { number: 10, text: "Und zur bestimmten Zeit sandte er einen Knecht* zu den Weingärtnern, damit sie ihm von der Frucht des Weinbergs gäben; die Weingärtner aber schlugen ihn und schickten ihn leer fort*.", footnotes: ["w. Sklaven", "℘ Jes 5,7; Jer 7,25.26"] },
      { number: 11, text: "Und er fuhr fort und sandte einen anderen Knecht*; sie aber schlugen auch den und behandelten ihn verächtlich und schickten ihn leer fort*.", footnotes: ["w. Sklaven", "℘ Jes 5,7; Jer 7,25.26"] },
      { number: 12, text: "Und er fuhr fort und sandte einen dritten; sie aber verwundeten auch diesen und warfen ihn hinaus*.", footnotes: ["℘ Jes 5,7; Jer 7,25.26"] },
      { number: 13, text: "Der Herr des Weinbergs aber sprach: Was soll ich tun? Ich will meinen geliebten Sohn senden*; vielleicht, wenn sie diesen sehen, werden sie sich scheuen.", footnotes: ["℘ Hebr 1,1"] },
      { number: 14, text: "Als aber die Weingärtner ihn sahen, überlegten sie miteinander und sagten: Dieser ist der Erbe; lasst uns ihn töten, dass das Erbe unser werde*.", footnotes: ["℘ Joh 11,53"] },
      { number: 15, text: "Und als sie ihn aus dem Weinberg hinausgeworfen hatten, töteten sie ihn*. Was wird nun der Herr des Weinbergs ihnen tun?", footnotes: ["℘ Joh 19,17.18"] },
      { number: 16, text: "Er wird kommen und diese Weingärtner umbringen* und den Weinberg anderen geben. Als sie aber <das> hörten, sprachen sie: Das sei fern!", footnotes: ["℘ Mt 22,7"] },
      { number: 17, text: "Er aber sah sie an und sprach: Was ist denn das, was geschrieben steht: »Der Stein, den die Bauleute verworfen haben, der ist zum Eckstein* geworden«*?", footnotes: ["w. zum Haupt der Ecke", "℘ Ps 118,22"] },
      { number: 18, text: "Jeder, der auf jenen Stein fällt, wird zerschmettert werden*; auf wen er aber fallen wird, den wird er zermalmen*.", footnotes: ["℘ Jes 8,15", "℘ Dan 2,44"] },
      { number: 19, text: "Und die Hohenpriester und die Schriftgelehrten suchten zu dieser Stunde die Hände an ihn zu legen — und sie fürchteten das Volk* —, denn sie erkannten, dass er dieses Gleichnis auf sie hin gesagt hatte.", footnotes: ["℘ Kap. 19,47.48"] },
      { number: 20, text: "*Und sie beobachteten <ihn> und sandten Auflauerer aus*, die sich stellten, als ob sie fromm* seien*, um ihn in der Rede zu fangen, damit sie ihn der Obrigkeit und der Macht des Statthalters überliefern könnten*.", heading: "Die Frage nach der Steuer", footnotes: ["℘ Mt 22,15-22; Mk 12,13-17", "℘ Kap. 6,7", "o. gerecht", "℘ Ps 12,3", "℘ Joh 8,6 ⇨Esyn: Synopse Nr. 280"] },
      { number: 21, text: "Und sie fragten ihn und sagten: Lehrer, wir wissen, dass du recht redest und lehrst und die Person nicht ansiehst*, sondern den Weg Gottes in Wahrheit lehrst.", footnotes: ["℘ Apg 10,34"] },
      { number: 22, text: "Ist es uns erlaubt, dem Kaiser Steuer zu geben oder nicht?" },
      { number: 23, text: "Aber er nahm ihre Arglist wahr und sprach zu ihnen:*", footnotes: ["Andere Handschr. fügen hinzu: Was versucht ihr mich?"] },
      { number: 24, text: "Zeigt mir einen Denar! Wessen Bild und Aufschrift hat er? Sie aber antworteten und sprachen: Des Kaisers." },
      { number: 25, text: "Er aber sprach zu ihnen: Gebt daher dem Kaiser, was des Kaisers ist, und Gott, was Gottes ist*!", footnotes: ["℘ Kap. 23,2"] },
      { number: 26, text: "Und sie konnten ihn in <seinem> Wort vor dem Volk nicht fangen; und sie verwunderten sich über seine Antwort und schwiegen*.", footnotes: ["℘ Ps 31,19"] },
      { number: 27, text: "*Es kamen aber einige der Sadduzäer* herbei, die einwenden, es gebe keine Auferstehung, und fragten ihn *", heading: "Die Frage nach der Auferstehung", footnotes: ["℘ Mt 22,23-33; Mk 12,18-27", "religiöse Partei, der u. a. die vornehmen Priesterfamilien angehörten; s. auch Anm. zu Mt 3,7", "℘ ⇨Esyn: Synopse Nr. 281"] },
      { number: 28, text: "und sagten: Lehrer, Mose hat uns geschrieben: Wenn jemandes Bruder stirbt, der eine Frau hat und ist kinderlos, dass sein Bruder die Frau nehme und seinem Bruder Nachkommenschaft* erwecke.", footnotes: ["w. Samen"] },
      { number: 29, text: "Es waren nun sieben Brüder. Und der erste nahm eine Frau und starb kinderlos;" },
      { number: 30, text: "und der zweite" },
      { number: 31, text: "und der dritte nahm sie; ebenso aber auch die sieben, sie hinterließen keine Kinder und starben." },
      { number: 32, text: "Zuletzt aber starb auch die Frau." },
      { number: 33, text: "In der Auferstehung nun, wessen Frau von ihnen wird sie sein? Denn die sieben hatten sie zur Frau." },
      { number: 34, text: "Und Jesus sprach zu ihnen: Die Söhne dieser Welt* heiraten und werden verheiratet;", footnotes: ["o. dieses Zeitalters (griech. Äon)"] },
      { number: 35, text: "die aber, die für würdig gehalten werden, jener Welt* teilhaftig zu sein und der Auferstehung aus den Toten*, heiraten nicht, noch werden sie verheiratet;", footnotes: ["o. jenes Zeitalters (griech. Äon)", "℘ Phil 3,11"] },
      { number: 36, text: "denn sie können auch nicht mehr sterben*, denn sie sind Engeln gleich und sind Söhne Gottes, da sie Söhne der Auferstehung sind.", footnotes: ["℘ Offb 21,4"] },
      { number: 37, text: "Dass aber die Toten auferweckt werden, hat auch Mose beim Dornbusch angedeutet, wenn er den Herrn »den Gott Abrahams und den Gott Isaaks und den Gott Jakobs« nennt*.", footnotes: ["℘ 2Mo 3,6"] },
      { number: 38, text: "Er ist aber nicht der Gott von Toten, sondern von Lebenden; denn für ihn leben alle*.", footnotes: ["℘ Offb 20,12.13"] },
      { number: 39, text: "Einige der Schriftgelehrten aber antworteten und sprachen: Lehrer, du hast gut gesprochen." },
      { number: 40, text: "Denn sie wagten nicht mehr, ihn über irgendetwas zu befragen*.", footnotes: ["℘ Mt 22,46 ⇨Esyn: Synopse Nr. 283"] },
      { number: 41, text: "*Er aber sprach zu ihnen: Wie sagen sie, dass der Christus Davids Sohn sei*;", heading: "Die Frage nach dem Christus", footnotes: ["℘ Mt 22,41-46; Mk 12,35-37", "℘ Jer 33,15; Joh 7,42"] },
      { number: 42, text: "und David selbst sagt im Buch der Psalmen: »Der Herr sprach zu meinem Herrn: Setze dich zu meiner Rechten*,", footnotes: ["℘ Kap. 22,69"] },
      { number: 43, text: "bis ich deine Feinde zum Schemel deiner Füße lege«*?", footnotes: ["℘ Ps 110,1"] },
      { number: 44, text: "David also nennt ihn Herr. Und wie ist er sein Sohn?" },
      { number: 45, text: "*Während aber das ganze Volk zuhörte, sprach er zu seinen Jüngern: *", heading: "Warnung vor den Schriftgelehrten", footnotes: ["℘ Mt 23,1-7; Mk 12,38-40", "℘ ⇨Esyn: Synopse Nr. 284"] },
      { number: 46, text: "Hütet euch vor den Schriftgelehrten, die in langen Gewändern einhergehen wollen und die Begrüßungen auf den Märkten lieben und die ersten Sitze in den Synagogen und die ersten Plätze bei den Gastmählern*;", footnotes: ["℘ Kap. 11,43"] },
      { number: 47, text: "die die Häuser der Witwen verschlingen und zum Schein lange Gebete halten! Diese werden ein schwereres Gericht empfangen*.", footnotes: ["℘ Mt 10,15"] },
    ]},
    { number: 21, verses: [
      { number: 1, text: "*Er blickte aber auf und sah die Reichen ihre Gaben in den Schatzkasten legen. *", heading: "Die Gabe der armen Witwe", footnotes: ["℘ Mk 12,41-44", "℘ ⇨Esyn: Synopse Nr. 286"] },
      { number: 2, text: "Er sah aber auch eine arme Witwe zwei Scherflein* dort einlegen.", footnotes: ["w. Lepta; s. Tabelle »Münzen und Geldeinheiten«"] },
      { number: 3, text: "Und er sprach: In Wahrheit sage ich euch, dass diese arme Witwe mehr eingelegt hat als alle." },
      { number: 4, text: "Denn alle diese haben von ihrem Überfluss eingelegt zu den Gaben; diese aber hat aus ihrem Mangel heraus den ganzen Lebensunterhalt, den sie hatte, eingelegt." },
      { number: 5, text: "*Und als einige von dem Tempel sagten, dass er mit schönen Steinen und Weihgeschenken geschmückt sei, sprach er: *", heading: "Endzeitrede: Tempelzerstörung und Drangsale der Endzeit — Ankunft des Menschensohnes", footnotes: ["℘ Mt 24,1-30; Mk 13,1-26", "℘ ⇨Esyn: Synopse Nr. 287"] },
      { number: 6, text: "Diese Dinge, die ihr seht: Tage werden kommen, in denen nicht ein Stein auf dem anderen* gelassen wird, der nicht abgebrochen werden wird.*", footnotes: ["w. Stein auf Stein", "℘ Kap. 19,44"] },
      { number: 7, text: "Sie fragten ihn aber und sagten: Lehrer, wann wird denn dies sein, und was ist das Zeichen, wann dies geschehen soll? *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 288"] },
      { number: 8, text: "Er aber sprach: Seht zu, dass ihr nicht verführt werdet! Denn viele werden unter meinem Namen kommen und sagen: Ich bin's, und die Zeit ist nahe gekommen! Geht ihnen nicht nach*!", footnotes: ["℘ Kap. 17,23"] },
      { number: 9, text: "Wenn ihr aber von Kriegen und Empörungen hören werdet, so erschreckt nicht! Denn dies muss vorher geschehen, aber das Ende ist nicht sogleich da*.", footnotes: ["℘ Offb 6,4"] },
      { number: 10, text: "Dann sprach er zu ihnen: Es wird sich Nation gegen Nation erheben und Königreich gegen Königreich*;", footnotes: ["℘ 2Chr 15,6"] },
      { number: 11, text: "und es werden große Erdbeben sein und an verschiedenen Orten Hungersnöte und Seuchen; auch Schrecknisse und große Zeichen vom Himmel wird es geben." },
      { number: 12, text: "Vor diesem allem aber werden sie ihre Hände an euch legen und <euch> verfolgen, indem sie euch an die Synagogen und Gefängnisse überliefern, um euch vor Könige und Statthalter zu führen um meines Namens willen*.", footnotes: ["℘ Mt 10,17.18; Apg 4,3; Offb 2,10 ⇨Esyn: Synopse Nr. 289"] },
      { number: 13, text: "Es wird euch <aber> zu einem Zeugnis ausschlagen." },
      { number: 14, text: "Setzt es nun fest in euren Herzen, nicht vorher darauf zu sinnen, wie ihr euch verantworten sollt*!", footnotes: ["℘ Kap. 12,11; Mt 10,19"] },
      { number: 15, text: "Denn ich werde euch Mund und Weisheit geben*, der alle eure Widersacher nicht werden widerstehen oder widersprechen können*.", footnotes: ["℘ Kap. 12,12", "℘ Apg 6,10"] },
      { number: 16, text: "Ihr werdet aber sogar von Eltern und Brüdern und Verwandten und Freunden überliefert werden*, und sie werden einige von euch töten;", footnotes: ["℘ Jer 9,3; Mt 10,21"] },
      { number: 17, text: "und ihr werdet von allen gehasst werden um meines Namens willen*.", footnotes: ["℘ Joh 15,21"] },
      { number: 18, text: "Und nicht ein Haar von eurem Haupt wird verloren gehen*.", footnotes: ["℘ Kap. 12,7; Apg 27,34"] },
      { number: 19, text: "Gewinnt eure Seelen* durch euer Ausharren*!", footnotes: ["o. euer Leben", "℘ Hebr 10,36"] },
      { number: 20, text: "Wenn ihr aber Jerusalem von Heerscharen umzingelt seht, dann erkennt, dass seine Verwüstung nahe gekommen ist*!", footnotes: ["℘ Kap. 19,43 ⇨Esyn: Synopse Nr. 290"] },
      { number: 21, text: "Dann sollen die in Judäa auf die Berge fliehen, und die, die in seiner Mitte* sind, daraus fortgehen, und die, die auf dem Land sind, nicht dort hineingehen.", footnotes: ["d. h. in Jerusalem"] },
      { number: 22, text: "Denn dies sind Tage der Rache*, dass alles erfüllt werde, was geschrieben steht*.", footnotes: ["℘ 5Mo 32,35; Hos 9,7", "℘ Jer 5,29; Dan 9,26"] },
      { number: 23, text: "Wehe aber den Schwangeren und den Stillenden in jenen Tagen! Denn große Not wird auf der Erde* sein und Zorn gegen dieses Volk*.", footnotes: ["o. auf dem Land", "℘ Kap. 23,29"] },
      { number: 24, text: "Und sie werden fallen durch die Schärfe des Schwertes und gefangen weggeführt werden unter alle Nationen*; und Jerusalem wird zertreten werden von den Nationen*, bis die Zeiten der Nationen erfüllt sein werden.", footnotes: ["℘ 5Mo 28,64", "℘ Ps 79,1; Jes 63,18; Offb 11,2"] },
      { number: 25, text: "Und es werden Zeichen sein an Sonne und Mond und Sternen und auf der Erde Angst der Nationen in Ratlosigkeit bei brausendem und wogendem Meer*,", footnotes: ["w. in Ratlosigkeit des Brausens des Meeres und Gewoges\n℘ Offb 8,12 ⇨Esyn: Synopse Nr. 292"] },
      { number: 26, text: "während die Menschen verschmachten vor Furcht und Erwartung der Dinge, die über den Erdkreis kommen, denn die Kräfte der Himmel werden erschüttert werden*.", footnotes: ["℘ Offb 6,13"] },
      { number: 27, text: "Und dann werden sie den Sohn des Menschen kommen sehen in einer Wolke mit Macht und großer Herrlichkeit*.", footnotes: ["℘ Kap. 9,26; Dan 7,13.14; Mt 26,64"] },
      { number: 28, text: "Wenn aber diese Dinge anfangen zu geschehen, so blickt auf und hebt eure Häupter empor, weil eure Erlösung naht." },
      { number: 29, text: "*Und er sprach ein Gleichnis zu ihnen: Seht den Feigenbaum und alle Bäume! *", heading: "Endzeitrede: Ermahnung zur Wachsamkeit", footnotes: ["℘ V. 29-33: Mt 24,32-35; Mk 13,28-31", "℘ ⇨Esyn: Synopse Nr. 293"] },
      { number: 30, text: "Wenn sie schon ausschlagen, so erkennt ihr von selbst, da ihr es seht, dass der Sommer schon nahe ist." },
      { number: 31, text: "So erkennt auch ihr, wenn ihr dies geschehen seht, dass das Reich* Gottes nahe ist.", footnotes: ["o. die Königsherrschaft"] },
      { number: 32, text: "Wahrlich, ich sage euch, dass dieses Geschlecht nicht vergehen wird, bis alles geschehen ist." },
      { number: 33, text: "Der Himmel und die Erde werden vergehen, meine Worte aber werden nicht vergehen*.", footnotes: ["℘ Kap. 16,17"] },
      { number: 34, text: "Hütet euch aber, dass eure Herzen nicht etwa beschwert werden durch Völlerei* und Trunkenheit* und Lebenssorgen und jener Tag plötzlich über euch hereinbricht*", footnotes: ["o. Rausch", "℘ Kap. 12,45", "℘ Jes 5,11.12; Röm 13,13; 1Thes 5,6-8 ⇨Esyn: Synopse Nr. 295"] },
      { number: 35, text: "wie ein Fallstrick! Denn er wird über alle kommen, die auf dem ganzen Erdboden ansässig sind*.", footnotes: ["℘ Pred 9,12; Jes 24,17; 1Thes 5,2.3"] },
      { number: 36, text: "Wacht nun und betet zu aller Zeit*, dass ihr imstande seid*, diesem allem, was geschehen soll, zu entfliehen und vor dem Sohn des Menschen zu stehen!", footnotes: ["℘ Kap. 18,1; Mt 26,41; Mk 13,33", "℘ 2Thes 1,5"] },
      { number: 37, text: "Er lehrte aber des Tages in dem Tempel, und des Nachts ging er hinaus und übernachtete auf dem Berg, der Ölberg genannt wird*.", heading: "Anschlag der Hohenpriester und Verrat des Judas", footnotes: ["℘ Kap. 19,47; 22,39; Joh 8,1.2 ⇨Esyn: Synopse Nr. 301"] },
      { number: 38, text: "Und das ganze Volk kam frühmorgens im Tempel zu ihm, ihn zu hören*.", footnotes: ["℘ Kap. 19,48"] },
    ]},
    { number: 22, verses: [
      { number: 1, text: "*Es nahte aber das Fest der ungesäuerten Brote, das Passah genannt wird*.", footnotes: ["℘ Mt 26,1-5.14-16; Mk 14,1.2.10.11", "℘ V. 7; 3Mo 23,5.6 ⇨Esyn: Synopse Nr. 305"] },
      { number: 2, text: "Und die Hohenpriester und die Schriftgelehrten suchten, wie sie ihn heimlich umbringen könnten, denn sie fürchteten das Volk*.", footnotes: ["℘ Kap. 19,47"] },
      { number: 3, text: "Aber Satan fuhr in Judas, der Iskariot* genannt wurde <und> aus der Zahl der Zwölf war*.", footnotes: ["Der Beiname bedeutete wahrscheinlich »Mann aus Kariot« und diente viell. zur Unterscheidung von dem anderen Jünger namens Judas (vgl. Joh 14,22).\n℘ Joh 13,27", "℘ V. 47; Kap. 6,16; Apg 1,17 ⇨Esyn: Synopse Nr. 309"] },
      { number: 4, text: "Und er ging hin und besprach sich mit den Hohenpriestern und Hauptleuten, wie er ihn an sie überliefere*.", footnotes: ["℘ V. 47; Kap. 6,16; Apg 1,17"] },
      { number: 5, text: "Und sie waren erfreut und kamen überein, ihm Geld zu geben." },
      { number: 6, text: "Und er versprach es und suchte eine Gelegenheit, um ihn ohne Volksauflauf* an sie zu überliefern.", footnotes: ["w. ohne Menge"] },
      { number: 7, text: "*Es kam aber der Tag <des Festes> der ungesäuerten Brote, an dem das Passah<lamm> geschlachtet werden musste*.", heading: "Passahmahl", footnotes: ["℘ Mt 26,17-19; Mk 14,12-16", "℘ V. 1 ⇨Esyn: Synopse Nr. 308"] },
      { number: 8, text: "Und er sandte Petrus und Johannes und sprach: Geht hin und bereitet uns das Passah<mahl>, dass wir es essen!" },
      { number: 9, text: "Sie aber sprachen zu ihm: Wo willst du, dass wir es bereiten?" },
      { number: 10, text: "Er aber sprach zu ihnen: Siehe, wenn ihr in die Stadt kommt, wird euch ein Mensch begegnen, der einen Krug Wasser trägt. Folgt ihm in das Haus, wo er hineingeht!" },
      { number: 11, text: "Und ihr sollt zu dem Herrn des Hauses sagen: Der Lehrer sagt dir: Wo ist das Gastzimmer, wo ich mit meinen Jüngern das Passah<mahl> essen kann?" },
      { number: 12, text: "Und jener wird euch einen großen, <mit Polstern> ausgelegten* Obersaal zeigen. Dort bereitet!", footnotes: ["o. gedielten; o. getäfelten"] },
      { number: 13, text: "Als sie aber hingingen, fanden sie es, wie er ihnen gesagt hatte*; und sie bereiteten das Passah<mahl>.", footnotes: ["℘ Kap. 19,32"] },
      { number: 14, text: "Und als die Stunde gekommen war, legte er sich zu Tisch und die Apostel mit ihm." },
      { number: 15, text: "Und er sprach zu ihnen: Mit Sehnsucht habe ich mich gesehnt*, dieses Passah<mahl> mit euch zu essen, ehe ich leide. *", footnotes: ["o. Mit Verlangen (Begierde) habe ich danach verlangt (begehrt)", "℘ ⇨Esyn: Synopse Nr. 311"] },
      { number: 16, text: "Denn ich sage euch, dass ich es gewiss nicht <mehr> essen werde, bis es erfüllt sein wird im Reich* Gottes*.", footnotes: ["o. in der Königsherrschaft", "℘ V. 30"] },
      { number: 17, text: "Und er nahm einen Kelch, dankte und sprach: Nehmt diesen und teilt ihn unter euch!" },
      { number: 18, text: "Denn ich sage euch, dass ich von nun an nicht von dem Gewächs des Weinstocks trinken werde, bis das Reich* Gottes kommt*.", footnotes: ["o. die Königsherrschaft", "℘ V. 30"] },
      { number: 19, text: "*Und er nahm Brot, dankte, brach und gab es ihnen* und sprach: Dies ist mein Leib, der für euch gegeben wird. Dies tut zu meinem Gedächtnis*!", heading: "Einsetzung des Herrenmahls", footnotes: ["℘ Mt 26,26-28; Mk 14,22-24; 1Kor 11,23-25", "℘ Kap. 24,30", "℘ Apg 2,42"] },
      { number: 20, text: "Ebenso auch den Kelch nach dem Mahl* und sagte: Dieser Kelch ist der neue Bund* in meinem Blut, das für euch vergossen wird.", footnotes: ["w. nach dem Essen (Infinitiv)", "℘ Jer 31,31"] },
      { number: 21, text: "*Doch siehe, die Hand dessen, der mich überliefert, ist mit mir auf dem Tisch. *", heading: "Ankündigung des Verrats — Wahre Größe im Reich Gottes — Ankündigung der Verleugnung durch Petrus und der Vollendung Jesu", footnotes: ["℘ V. 21-23: Mt 26,21-25; Mk 14,18-21; Joh 13,18-30", "℘ ⇨Esyn: Synopse Nr. 312"] },
      { number: 22, text: "Und der Sohn des Menschen geht zwar dahin, wie es beschlossen ist*. Wehe aber jenem Menschen, durch den er überliefert wird*!", footnotes: ["℘ Apg 2,23; 1Kor 15,3", "℘ Kap. 17,1"] },
      { number: 23, text: "Und sie fingen an, sich untereinander zu befragen, wer es wohl von ihnen sein möchte, der dies tun werde." },
      { number: 24, text: "Es entstand aber auch ein Streit unter ihnen, wer von ihnen für den Größten zu halten sei*.", footnotes: ["℘ Kap. 9,46 ⇨Esyn: Synopse Nr. 313"] },
      { number: 25, text: "Er aber sprach zu ihnen: Die Könige der Nationen herrschen über sie, und die Gewalt über sie üben, lassen sich Wohltäter nennen*.", footnotes: ["℘ Mt 20,25"] },
      { number: 26, text: "Ihr aber nicht so! Sondern der Größte unter euch sei wie der Jüngste und der Führende wie der Dienende*.", footnotes: ["℘ Kap. 9,48; Mt 23,11; Phil 2,3; 1Petr 5,3"] },
      { number: 27, text: "Denn wer ist größer, der zu Tisch Liegende oder der Dienende? Nicht der zu Tisch Liegende? Ich aber bin in eurer Mitte wie der Dienende*.", footnotes: ["℘ Mt 20,28; Joh 13,5"] },
      { number: 28, text: "Ihr aber seid es, die mit mir ausgeharrt haben in meinen Versuchungen*;", footnotes: ["℘ 2Thes 3,5"] },
      { number: 29, text: "und ich verordne euch, wie mein Vater mir verordnet hat, ein Reich*,", footnotes: ["o. eine Königsherrschaft\n℘ Kap. 6,20"] },
      { number: 30, text: "dass ihr esst und trinkt an meinem Tisch in meinem Reich* und auf Thronen sitzt, die zwölf Stämme Israels zu richten*.", footnotes: ["o. in meiner Königsherrschaft\n℘ V. 16.18", "℘ Mt 19,28"] },
      { number: 31, text: "**Der Herr aber sprach:* Simon, Simon! Siehe, der Satan hat euer begehrt*, euch zu sichten wie den Weizen*.", footnotes: ["℘ V. 31-34: Mt 26,31-35; Mk 14,27-31; Joh 13,36-38", "in einigen alten Handschr. nicht enthalten", "in einigen alten Handschr. nicht enthalten", "℘ Hi 1,11", "℘ 2Kor 2,11 ⇨Esyn: Synopse Nr. 367"] },
      { number: 32, text: "Ich aber habe für dich gebetet, dass dein Glaube nicht aufhöre. Und wenn du einst zurückgekehrt bist, so stärke deine Brüder*!", footnotes: ["℘ Ps 51,15"] },
      { number: 33, text: "Er aber sprach zu ihm: Herr, mit dir bin ich bereit, auch ins Gefängnis und in den Tod zu gehen." },
      { number: 34, text: "Er aber sprach: Ich sage dir, Petrus, der Hahn wird heute nicht krähen, ehe du dreimal geleugnet hast, dass du mich kennst*.", footnotes: ["℘ V. 61"] },
      { number: 35, text: "Und er sprach zu ihnen: Als ich euch ohne Börse und Tasche und Sandalen sandte*, mangelte euch wohl etwas? Sie aber sagten: Nichts.", footnotes: ["℘ Kap. 9,3 ⇨Esyn: Synopse Nr. 316"] },
      { number: 36, text: "Er sprach nun zu ihnen: Aber jetzt, wer eine Börse hat, der nehme sie und ebenso eine Tasche, und wer nicht hat*, verkaufe sein Gewand und kaufe ein Schwert;", footnotes: ["d. h. entweder: wer keine Börse oder Tasche hat; oder: wer kein Schwert hat"] },
      { number: 37, text: "denn ich sage euch, dass noch dieses, was geschrieben steht, an mir erfüllt werden muss: »Und er ist unter die Gesetzlosen gerechnet worden«*; denn auch das, was mich betrifft, hat eine Vollendung.", footnotes: ["℘ Kap. 23,33; Jes 53,12; Mk 15,28"] },
      { number: 38, text: "Sie aber sprachen: Herr, siehe, hier sind zwei Schwerter. Er aber sprach zu ihnen: Es ist genug." },
      { number: 39, text: "*Und er ging hinaus und begab sich der Gewohnheit nach zum Ölberg*; es folgten ihm aber auch die Jünger*.", heading: "Gethsemane", footnotes: ["℘ Mt 26,30.36-46; Mk 14,26.32-42", "℘ Kap. 21,37", "℘ Joh 14,31 ⇨Esyn: Synopse Nr. 330"] },
      { number: 40, text: "Als er aber an den Ort gekommen war, sprach er zu ihnen: Betet, dass ihr nicht in Versuchung kommt!" },
      { number: 41, text: "Und er zog sich ungefähr einen Steinwurf weit von ihnen zurück und kniete nieder, betete *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 302"] },
      { number: 42, text: "und sprach: Vater, wenn du willst, nimm diesen Kelch von mir weg — doch nicht mein Wille, sondern der deine geschehe*!", footnotes: ["℘ Mt 6,10"] },
      { number: 43, text: "*Es erschien ihm aber ein Engel vom Himmel, der ihn stärkte*.", footnotes: ["Die Verse 43 und 44 sind in mehreren alten Handschr. nicht enthalten.", "℘ 1Kö 19,5; Mt 4,11"] },
      { number: 44, text: "Und als er in Angst* war, betete er heftiger. Es wurde aber sein Schweiß wie große Blutstropfen, die auf die Erde herabfielen.*", footnotes: ["o. im Kampf\n℘ Kol 1,29", "Die Verse 43 und 44 sind in mehreren alten Handschr. nicht enthalten."] },
      { number: 45, text: "Und er stand auf vom Gebet, kam zu den Jüngern und fand sie eingeschlafen vor Traurigkeit." },
      { number: 46, text: "Und er sprach zu ihnen: Was schlaft ihr? Steht auf und betet, damit ihr nicht in Versuchung kommt!" },
      { number: 47, text: "*Während er noch redete, siehe, <da kam> eine Volksmenge, und der, welcher Judas hieß, einer von den Zwölfen*, ging vor ihnen her und nahte sich Jesus, um ihn zu küssen*.", heading: "Gefangennahme", footnotes: ["℘ Mt 26,47-56; Mk 14,43-50; Joh 18,2-12", "℘ V. 3", "℘ Apg 1,16 ⇨Esyn: Synopse Nr. 331"] },
      { number: 48, text: "Jesus aber sprach zu ihm: Judas, überlieferst du den Sohn des Menschen mit einem Kuss*?", footnotes: ["℘ Kap. 6,16"] },
      { number: 49, text: "Als aber die, welche um ihn waren, sahen, was es werden würde, sprachen sie: Herr, sollen wir mit dem Schwert dreinschlagen?" },
      { number: 50, text: "Und einer von ihnen schlug den Knecht* des Hohenpriesters und hieb ihm das rechte Ohr ab.", footnotes: ["w. Sklaven"] },
      { number: 51, text: "Jesus aber antwortete und sprach: Lasst es soweit! Und er rührte sein Ohr an und heilte ihn." },
      { number: 52, text: "Jesus aber sprach zu den Hohenpriestern* und Hauptleuten des Tempels und Ältesten, die gegen ihn gekommen waren: Seid ihr ausgezogen wie gegen einen Räuber, mit Schwertern und Stöcken?", footnotes: ["Nicht nur der amtierende Hohepriester, sondern alle männlichen Mitglieder der hohenpriesterlichen Familien wurden zu den »Hohenpriestern« gerechnet."] },
      { number: 53, text: "Als ich täglich bei euch im Tempel war, habt ihr die Hände nicht gegen mich ausgestreckt; aber dies ist eure Stunde* und die Macht* der Finsternis*.", footnotes: ["℘ Joh 7,30", "o. der Machtbereich", "℘ Eph 6,12 ⇨Esyn: Synopse Nr. 332"] },
      { number: 54, text: "*Sie ergriffen ihn aber und führten ihn hin und brachten ihn in das Haus des Hohenpriesters. Petrus aber folgte von weitem.", heading: "Verleugnung durch Petrus", footnotes: ["℘ Mt 26,57.58.69-75; Mk 14,53.54.66-72; Joh 18,13-18.25-27"] },
      { number: 55, text: "Als sie aber mitten im Hof ein Feuer angezündet und sich zusammengesetzt hatten, setzte sich Petrus in ihre Mitte." },
      { number: 56, text: "Es sah ihn aber eine Magd bei dem Feuer sitzen und blickte ihn scharf an und sprach: Auch dieser war mit ihm." },
      { number: 57, text: "Er aber leugnete und sagte: Frau, ich kenne ihn nicht." },
      { number: 58, text: "Und kurz danach sah ihn ein anderer und sprach: Auch du bist <einer> von ihnen. Petrus aber sprach: Mensch, ich bin es nicht." },
      { number: 59, text: "Und nach Verlauf von etwa einer Stunde behauptete ein anderer und sagte: In Wahrheit, auch dieser war mit ihm, denn er ist auch ein Galiläer." },
      { number: 60, text: "Petrus aber sprach: Mensch, ich weiß nicht, was du sagst. Und sogleich, während er noch redete, krähte ein Hahn." },
      { number: 61, text: "Und der Herr wandte sich um und blickte Petrus an*; und Petrus gedachte an das Wort des Herrn, wie er zu ihm sagte: Bevor ein Hahn heute kräht, wirst du mich dreimal verleugnen*.", footnotes: ["℘ Joh 1,42", "℘ V. 34"] },
      { number: 62, text: "Und Petrus ging hinaus und weinte bitterlich." },
      { number: 63, text: "*Und die Männer, die ihn festhielten, verspotteten und schlugen ihn*.", heading: "Vor dem Hohen Rat", footnotes: ["℘ Mt 26,59-68; 27,1; Mk 14,55-65; 15,1; Joh 18,19-24", "℘ Kap. 18,32; Jes 50,6; Mt 20,19"] },
      { number: 64, text: "Und als sie ihn verhüllt hatten, fragten sie ihn und sprachen: Weissage, wer ist es, der dich schlug?" },
      { number: 65, text: "Und vieles andere sagten sie lästernd gegen ihn." },
      { number: 66, text: "Und als es Tag wurde, versammelte sich die Ältestenschaft des Volkes, Hohepriester* sowie Schriftgelehrte, und führten ihn hin in ihren Hohen Rat*", footnotes: ["Nicht nur der amtierende Hohepriester, sondern alle männlichen Mitglieder der hohenpriesterlichen Familien wurden zu den »Hohenpriestern« gerechnet.", "w. Synedrium, s. Anm. zu Mt 26,59\n℘ Apg 4,26"] },
      { number: 67, text: "und sagten: Wenn du der Christus bist, so sage es uns! Er aber sprach zu ihnen: Wenn ich es euch sagte, so würdet ihr nicht glauben*;", footnotes: ["℘ Joh 3,12"] },
      { number: 68, text: "wenn ich aber fragen würde, so würdet ihr mir nicht antworten." },
      { number: 69, text: "Von nun an aber wird der Sohn des Menschen sitzen zur Rechten der Macht Gottes*.", footnotes: ["℘ Kap. 20,43; Apg 7,56"] },
      { number: 70, text: "Sie sprachen aber alle: Du bist also der Sohn Gottes? Er aber sprach zu ihnen: Ihr sagt es; ich bin es*.", footnotes: ["℘ Mt 27,43"] },
      { number: 71, text: "Sie aber sprachen: Was brauchen wir noch Zeugnis? Denn wir selbst haben es aus seinem Mund gehört." },
    ]},
    { number: 23, verses: [
      { number: 1, text: "*Und die ganze Menge von ihnen stand auf, und sie führten ihn zu Pilatus*. *", heading: "Anklage vor Pilatus und Herodes", footnotes: ["℘ V. 1-5: Mt 27,2.11-14; Mk 15,1-5; Joh 18,28-38", "kaiserlicher Statthalter von ca. 26—36 n. Chr. in Judäa und Samaria", "℘ ⇨Esyn: Synopse Nr. 334"] },
      { number: 2, text: "Sie fingen aber an, ihn zu verklagen, und sagten: Diesen haben wir befunden als einen, der unsere Nation verführt und <sie davon> abbringt, dem Kaiser Steuer zu geben*, indem er sagt, dass er selbst Christus, ein König, sei*.", footnotes: ["℘ Kap. 20,20-25", "℘ Mt 27,42; Joh 19,12; Apg 17,7 ⇨Esyn: Synopse Nr. 336"] },
      { number: 3, text: "Pilatus aber fragte ihn und sprach: Bist du der König der Juden? Er aber antwortete ihm und sprach: Du sagst es." },
      { number: 4, text: "Pilatus aber sprach zu den Hohenpriestern und den Volksmengen: Ich finde keine Schuld an diesem Menschen*.", footnotes: ["℘ V. 14.22; Joh 19,4.6"] },
      { number: 5, text: "Sie aber bestanden darauf und sagten: Er wiegelt das Volk auf und lehrt durch ganz Judäa hin, angefangen von Galiläa bis hierher." },
      { number: 6, text: "Als aber Pilatus das hörte*, fragte er, ob der Mensch ein Galiläer sei. *", footnotes: ["mit anderen Handschr.: von Galiläa hörte", "℘ ⇨Esyn: Synopse Nr. 337"] },
      { number: 7, text: "Und als er erfahren hatte, dass er aus dem Machtbereich des Herodes* sei*, sandte er ihn zu Herodes, der auch selbst in jenen Tagen in Jerusalem war*.", footnotes: ["d. h. aus der Gerichtsbarkeit des Herodes Antipas (4 v. Chr. bis 39 n. Chr); vgl. Anm. zu Mt 14,1", "℘ Kap. 3,1", "℘ Apg 4,27"] },
      { number: 8, text: "Als aber Herodes Jesus sah, freute er sich sehr; denn er wünschte schon seit langer Zeit, ihn zu sehen*, weil er vieles über ihn gehört hatte*, und er hoffte, irgendein Zeichen* durch ihn geschehen zu sehen.", footnotes: ["℘ Kap. 9,9; Apg 25,22", "℘ Mt 14,1", "℘ Kap. 11,16"] },
      { number: 9, text: "Er befragte ihn aber mit vielen Worten; er jedoch antwortete ihm nichts*.", footnotes: ["℘ Mt 26,62"] },
      { number: 10, text: "Die Hohenpriester und die Schriftgelehrten standen nun auf und verklagten ihn heftig." },
      { number: 11, text: "Als aber Herodes mit seinen Soldaten ihn gering schätzend behandelt und verspottet hatte, warf er ihm ein glänzendes Gewand um und sandte ihn zu Pilatus zurück*.", footnotes: ["℘ Kap. 18,32; Mt 27,28"] },
      { number: 12, text: "Pilatus und Herodes aber wurden an diesem Tag Freunde miteinander; denn vorher waren sie gegeneinander in Feindschaft." },
      { number: 13, text: "*Als aber Pilatus die Hohenpriester und die Obersten und das Volk zusammengerufen hatte, *", heading: "Freilassung für Barabbas — Todesurteil für Jesus", footnotes: ["℘ Mt 27,15-26; Mk 15,6-15; Joh 18,39.40; 19,1.16", "℘ ⇨Esyn: Synopse Nr. 338"] },
      { number: 14, text: "sprach er zu ihnen: Ihr habt diesen Menschen zu mir gebracht, als mache er das Volk abspenstig; und siehe, ich habe ihn vor euch verhört und habe an diesem Menschen keine Schuld gefunden, worin ihr ihn anklagt*;", footnotes: ["℘ V. 4"] },
      { number: 15, text: "aber auch Herodes nicht, denn er hat ihn zu uns zurückgesandt*, und siehe, nichts Todeswürdiges ist von ihm getan.", footnotes: ["mit anderen Handschr.: denn ich habe euch zu ihm gesandt"] },
      { number: 16, text: "Ich will ihn nun züchtigen und losgeben*.", footnotes: ["℘ Apg 3,13"] },
      { number: 17, text: "[T>]* *", footnotes: ["Andere Handschr. fügen hinzu: Er musste ihnen aber zu jedem Fest einen losgeben.", "℘ ⇨Esyn: Synopse Nr. 339"] },
      { number: 18, text: "Sie schrien aber allesamt und sagten: Weg mit diesem*, gib uns aber den Barabbas los!", footnotes: ["℘ Apg 21,36"] },
      { number: 19, text: "Der war wegen eines Aufruhrs, der in der Stadt geschehen war, und wegen eines Mordes ins Gefängnis geworfen." },
      { number: 20, text: "Pilatus rief ihnen nun wieder zu, weil er Jesus losgeben wollte." },
      { number: 21, text: "Sie aber schrien dagegen und sagten: Kreuzige, kreuzige ihn*!", footnotes: ["℘ Joh 19,6"] },
      { number: 22, text: "Er aber sprach zum dritten Mal zu ihnen: Was hat dieser denn Böses getan? Ich habe keine Ursache des Todes an ihm gefunden*; ich will ihn nun züchtigen und losgeben.", footnotes: ["℘ V. 4"] },
      { number: 23, text: "Sie aber setzten ihm zu mit lautem Geschrei und forderten, dass er gekreuzigt werde*. Und ihr Geschrei nahm überhand.", footnotes: ["℘ Joh 19,15"] },
      { number: 24, text: "Pilatus aber entschied, dass ihre Forderung erfüllt werde*.", footnotes: ["℘ 2Mo 23,2 ⇨Esyn: Synopse Nr. 341"] },
      { number: 25, text: "Er gab aber den los, der eines Aufruhrs und Mordes wegen ins Gefängnis geworfen war, den sie forderten; Jesus aber übergab er ihrem Willen*.", footnotes: ["℘ Apg 7,52"] },
      { number: 26, text: "*Und als sie ihn wegführten, ergriffen sie einen gewissen Simon von Kyrene, der vom Feld kam, und legten das Kreuz auf ihn, damit er es Jesus nachtrug. *", heading: "Der Weg zum Kreuz", footnotes: ["℘ Mt 27,31.32; Mk 15,20-22; Joh 19,16.17", "℘ ⇨Esyn: Synopse Nr. 343"] },
      { number: 27, text: "Es folgte ihm aber eine große Menge Volks und Frauen, die wehklagten und ihn bejammerten." },
      { number: 28, text: "Jesus wandte sich aber zu ihnen und sprach: Töchter Jerusalems, weint nicht über mich, sondern weint über euch selbst und über eure Kinder!" },
      { number: 29, text: "Denn siehe, Tage kommen, an denen man sagen wird: Glückselig die Unfruchtbaren und die Leiber, die nicht geboren, und die Brüste, die nicht gestillt haben*!", footnotes: ["℘ Kap. 21,23"] },
      { number: 30, text: "Dann werden sie anfangen, zu den Bergen zu sagen: Fallt auf uns!, und zu den Hügeln: Bedeckt uns*!", footnotes: ["℘ Hos 10,8; Offb 6,16"] },
      { number: 31, text: "Denn wenn man dies tut an dem grünen Holz, was wird an dem dürren geschehen?*", footnotes: ["℘ 1Petr 4,17"] },
      { number: 32, text: "Es wurden aber auch zwei andere hingeführt, Übeltäter, um mit ihm hingerichtet zu werden." },
      { number: 33, text: "*Und als sie an den Ort kamen, der Schädel<stätte> genannt wird, kreuzigten sie dort ihn und die Übeltäter, den einen zur Rechten, den anderen zur Linken*.", heading: "Golgatha: Kreuzigung", footnotes: ["℘ V. 33-36: Mt 27,33-44; Mk 15,23-32; Joh 19,18-24", "℘ Kap. 22,37 ⇨Esyn: Synopse Nr. 344"] },
      { number: 34, text: "*Jesus aber sprach: Vater, vergib ihnen*! Denn sie wissen nicht, was sie tun*.* Sie aber verteilten seine Kleider und warfen das Los <darüber>*.", footnotes: ["in alten und wichtigen Handschr. nicht enthalten", "℘ Kap. 6,28; Apg 7,60", "℘ Apg 3,17; 1Tim 1,13", "in alten und wichtigen Handschr. nicht enthalten", "℘ Ps 22,19"] },
      { number: 35, text: "Und das Volk stand und sah zu. Es höhnten aber auch die Obersten und sagten: Andere hat er gerettet. Er rette sich selbst, wenn dieser der Christus Gottes ist, der Auserwählte*!", footnotes: ["℘ Ps 22,8.9; Jes 42,1 ⇨Esyn: Synopse Nr. 345"] },
      { number: 36, text: "Aber auch die Soldaten verspotteten ihn, indem sie hinzutraten, ihm Essig brachten*", footnotes: ["℘ Joh 19,29.30"] },
      { number: 37, text: "und sagten: Wenn du der König der Juden bist, so rette dich selbst!" },
      { number: 38, text: "Es war aber auch eine Aufschrift über ihm *in griechischen und lateinischen und hebräischen Buchstaben*: Dieser ist der König der Juden.", footnotes: ["in mehreren alten Handschr. nicht enthalten", "in mehreren alten Handschr. nicht enthalten"] },
      { number: 39, text: "Einer der gehenkten Übeltäter aber lästerte ihn: Bist du nicht der Christus? Rette dich selbst und uns! *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 346"] },
      { number: 40, text: "Der andere aber antwortete und wies ihn zurecht* und sprach: Auch du fürchtest Gott nicht, da du in demselben Gericht bist?", footnotes: ["o. fuhr ihn an"] },
      { number: 41, text: "Und wir zwar mit Recht, denn wir empfangen, was unsere Taten wert sind; dieser aber hat nichts Ungeziemendes getan*.", footnotes: ["℘ Mt 27,23; 1Petr 2,22"] },
      { number: 42, text: "Und er sprach: Jesus, gedenke meiner*, wenn du in dein Reich* kommst*!", footnotes: ["℘ Ps 106,4", "o. in deine Königsherrschaft", "℘ Mt 16,28"] },
      { number: 43, text: "Und er sprach zu ihm: Wahrlich, ich sage dir: Heute wirst du mit mir im Paradies sein*.", footnotes: ["℘ 2Kor 12,4; Phil 1,23; Offb 2,7"] },
      { number: 44, text: "*Und es war schon um die sechste Stunde*; und es kam eine Finsternis über das ganze Land* bis zur neunten Stunde, *", heading: "Golgatha: Tod", footnotes: ["℘ Mt 27,45-56; Mk 15,33-41; Joh 19,28-30", "d. i. zwischen 11 und 12 Uhr vormittags; vgl. auch Anm. zu Mt 27,45", "o. über die ganze Erde", "℘ ⇨Esyn: Synopse Nr. 347"] },
      { number: 45, text: "da sich die Sonne verfinsterte; der Vorhang* des Tempels aber riss mitten entzwei.", footnotes: ["℘ Hebr 10,20"] },
      { number: 46, text: "Und Jesus rief mit lauter Stimme und sprach: Vater, in deine Hände übergebe ich meinen Geist*! Und als er dies gesagt hatte, verschied er*.", footnotes: ["℘ Ps 31,6; Apg 7,59", "℘ Mt 27,19"] },
      { number: 47, text: "Als aber der Hauptmann sah, was geschah, verherrlichte er Gott und sagte: Wirklich, dieser Mensch war gerecht*.", footnotes: ["℘ Ps 38,12"] },
      { number: 48, text: "Und all die Volksmengen, die zu diesem Schauspiel zusammengekommen waren, schlugen sich, als sie sahen, was geschehen war, an die Brust und kehrten zurück." },
      { number: 49, text: "Aber alle seine Bekannten standen weitab*, auch die Frauen, die ihm von Galiläa nachgefolgt waren*, und sahen dies.", footnotes: ["℘ V. 55", "℘ Spr 14,32 ⇨Esyn: Synopse Nr. 348"] },
      { number: 50, text: "*Und siehe, ein Mann mit Namen Josef, der ein Ratsherr war, ein guter und gerechter Mann *", heading: "Grablegung", footnotes: ["℘ Mt 27,57-61; Mk 15,42-47; Joh 19,38-42", "℘ ⇨Esyn: Synopse Nr. 350"] },
      { number: 51, text: "— dieser hatte nicht eingewilligt in ihren Rat und in ihre Tat —, von Arimathäa, einer Stadt der Juden, der das Reich* Gottes erwartete;", footnotes: ["o. die Königsherrschaft"] },
      { number: 52, text: "dieser ging hin zu Pilatus und bat um den Leib Jesu." },
      { number: 53, text: "Und als er ihn abgenommen hatte, wickelte er ihn in ein Leinentuch und legte ihn in eine in Felsen gehauene Gruft worin noch nie jemand gelegen hatte." },
      { number: 54, text: "Und es war Rüsttag*, und der Sabbat brach an*.", footnotes: ["der Wochentag vor einem Sabbat oder Fest, in der Regel ein Freitag", "Der Tag beginnt mit Sonnenuntergang, also mit der ersten Nachtwache."] },
      { number: 55, text: "Es folgten aber die Frauen nach, die mit ihm aus Galiläa gekommen waren*, und besahen die Gruft und wie sein Leib hineingelegt wurde.", footnotes: ["℘ V. 49; Apg 1,14"] },
      { number: 56, text: "Als sie aber zurückgekehrt waren, bereiteten sie wohlriechende Öle und Salben; und den Sabbat über ruhten sie nach dem Gebot*.", footnotes: ["℘ 2Mo 20,8-10; Mk 16,1"] },
    ]},
    { number: 24, verses: [
      { number: 1, text: "*An dem ersten Wochentag* aber, ganz in der Frühe, kamen sie zu der Gruft und brachten die wohlriechenden Öle, die sie bereitet hatten.", heading: "Die Frauen am leeren Grab — Verkündigung der Auferstehung", footnotes: ["℘ Mt 28,1-10; Mk 16,1-11; Joh 20,1-18", "℘ Apg 20,7; 1Kor 16,2 ⇨Esyn: Synopse Nr. 352"] },
      { number: 2, text: "Sie fanden aber den Stein von der Gruft weggewälzt;" },
      { number: 3, text: "und als sie hineingingen, fanden sie den Leib des Herrn Jesus nicht." },
      { number: 4, text: "Und es geschah, als sie darüber in Verlegenheit waren, siehe, da standen zwei Männer in strahlendem Gewand bei ihnen*.", footnotes: ["℘ Apg 1,10"] },
      { number: 5, text: "Als sie aber von Furcht erfüllt wurden und das Gesicht zur Erde neigten, sprachen sie zu ihnen: Was sucht ihr den Lebenden unter den Toten?" },
      { number: 6, text: "Er ist nicht hier, sondern ist auferweckt worden*. Gedenkt daran, wie er zu euch geredet hat, als er noch in Galiläa war*,", footnotes: ["℘ 1Thes 4,14", "℘ V. 44"] },
      { number: 7, text: "indem er sagte: Der Sohn des Menschen muss in die Hände sündiger Menschen überliefert und gekreuzigt werden und am dritten Tag auferstehen*!", footnotes: ["℘ V. 26.46; Kap. 9,22; 18,32.33"] },
      { number: 8, text: "Und sie gedachten an seine Worte*.", footnotes: ["℘ Joh 2,22"] },
      { number: 9, text: "Und sie kehrten von der Gruft zurück und verkündeten dies alles den Elfen und den übrigen allen." },
      { number: 10, text: "Es waren aber die Maria Magdalena* und Johanna und Maria, des Jakobus' <Mutter>, und die Übrigen mit ihnen*. Sie sagten dies zu den Aposteln.", footnotes: ["d. h. die aus Magdala (Ort am See Genezareth)", "℘ Kap. 8,2.3"] },
      { number: 11, text: "Und diese Reden schienen ihnen wie Geschwätz, und sie glaubten ihnen nicht*.", footnotes: ["℘ Kap. 9,41; Apg 26,8"] },
      { number: 12, text: "*Petrus aber stand auf und lief zur Gruft; und als er sich hineinbeugt, sieht er nur die leinenen Tücher. Und er ging nach Hause und wunderte sich über das, was geschehen war.*", footnotes: ["in einigen anderen Handschr. nicht enthalten", "in einigen anderen Handschr. nicht enthalten"] },
      { number: 13, text: "*Und siehe, zwei von ihnen gingen an diesem Tag nach einem Dorf mit Namen Emmaus, sechzig Stadien* von Jerusalem entfernt. *", heading: "Erscheinung des Auferstandenen auf dem Weg nach Emmaus", footnotes: ["℘ Mk 16,12.13", "das sind ca. 11 km", "℘ ⇨Esyn: Synopse Nr. 355"] },
      { number: 14, text: "Und sie unterhielten sich miteinander über dies alles, was sich zugetragen hatte." },
      { number: 15, text: "Und es geschah, während sie sich unterhielten und miteinander überlegten, dass sich Jesus selbst nahte und mit ihnen ging;" },
      { number: 16, text: "aber ihre Augen wurden gehalten, so dass sie ihn nicht erkannten*.", footnotes: ["℘ Joh 20,14"] },
      { number: 17, text: "Er sprach aber zu ihnen: Was sind das für Reden, die ihr im Gehen miteinander wechselt? Und sie blieben niedergeschlagen stehen." },
      { number: 18, text: "Einer aber, mit Namen Kleopas, antwortete und sprach zu ihm: Bist du der Einzige, der in Jerusalem weilt* und nicht weiß, was dort geschehen ist in diesen Tagen?", footnotes: ["o. sich als Fremdling aufhält"] },
      { number: 19, text: "Und er sprach zu ihnen: Was denn? Sie aber sprachen zu ihm: Das von Jesus, dem Nazarener, der ein Prophet war*, mächtig im Werk* und Wort* vor Gott und dem ganzen Volk*;", footnotes: ["℘ Kap. 7,16", "℘ Joh 7,31", "℘ Mt 7,28.29; Apg 7,22", "℘ Kap. 4,32; Apg 2,22"] },
      { number: 20, text: "und wie ihn die Hohenpriester und unsere Obersten zum Todesurteil überlieferten und ihn kreuzigten*.", footnotes: ["℘ Apg 2,36"] },
      { number: 21, text: "Wir aber hofften, dass er der sei, der Israel erlösen solle*. Doch auch bei alledem ist es heute der dritte Tag, seitdem dies geschehen ist.", footnotes: ["℘ Kap. 1,68; 2,38"] },
      { number: 22, text: "Aber auch einige Frauen von uns haben uns aus der Fassung gebracht, die am frühen Morgen bei der Gruft gewesen sind" },
      { number: 23, text: "und, als sie seinen Leib nicht fanden, kamen und sagten, dass sie auch eine Erscheinung von Engeln gesehen hätten, die sagen, dass er lebe*.", footnotes: ["℘ V. 10"] },
      { number: 24, text: "Und einige von denen, die mit uns sind, gingen zu der Gruft und fanden es so, wie auch die Frauen gesagt hatten; ihn aber sahen sie nicht*.", footnotes: ["℘ Joh 20,2-10"] },
      { number: 25, text: "Und er sprach zu ihnen: Ihr Unverständigen* und im Herzen <zu> träge*, an alles zu glauben, was die Propheten geredet haben*!", footnotes: ["o. schwerfällig; w. langsam", "o. schwerfällig; w. langsam", "℘ V. 44"] },
      { number: 26, text: "Musste nicht der Christus dies leiden* und in seine Herrlichkeit hineingehen*?", footnotes: ["℘ V. 7; Jes 53,10; Apg 3,18", "℘ 1Petr 1,11"] },
      { number: 27, text: "Und von Mose und von allen Propheten anfangend, erklärte er ihnen in allen Schriften das, was ihn betraf*.", footnotes: ["℘ V. 45; Joh 1,45; Apg 13,27.29; 26,22"] },
      { number: 28, text: "Und sie näherten sich dem Dorf, wohin sie gingen; und er stellte sich, als wollte er weitergehen*.", footnotes: ["℘ Mk 6,48"] },
      { number: 29, text: "Und sie nötigten ihn und sagten: Bleibe bei uns! Denn es ist gegen Abend, und der Tag hat sich schon geneigt. Und er ging hinein, um bei ihnen zu bleiben*.", footnotes: ["℘ Joh 4,40"] },
      { number: 30, text: "Und es geschah, als er mit ihnen zu Tisch lag, nahm er das Brot und segnete es, und als er es gebrochen hatte, reichte er es ihnen*.", footnotes: ["℘ Kap. 22,19"] },
      { number: 31, text: "Ihre Augen aber wurden aufgetan, und sie erkannten ihn; und er wurde vor ihnen unsichtbar." },
      { number: 32, text: "Und sie sprachen zueinander: Brannte nicht unser Herz in uns, wie er auf dem Weg zu uns redete und wie er uns die Schriften öffnete?" },
      { number: 33, text: "Und sie standen zur gleichen Stunde auf und kehrten nach Jerusalem zurück. Und sie fanden die Elf und die, die mit ihnen waren, versammelt," },
      { number: 34, text: "die sagten: Der Herr ist wirklich auferweckt worden und dem Simon erschienen*.", footnotes: ["℘ 1Kor 15,5"] },
      { number: 35, text: "Und sie erzählten, was auf dem Weg <geschehen war> und wie er von ihnen erkannt worden war am Brechen des Brotes." },
      { number: 36, text: "*Während sie aber dies redeten, stand er selbst in ihrer Mitte* *und spricht zu ihnen: Friede euch!*", heading: "Erscheinung des Auferstandenen vor den Jüngern", footnotes: ["℘ Mk 16,14.15; Joh 20,19-23", "℘ 1Kor 15,5 ⇨Esyn: Synopse Nr. 356", "in einigen Handschr. nicht enthalten", "in einigen Handschr. nicht enthalten"] },
      { number: 37, text: "Sie aber erschraken und wurden von Furcht erfüllt und meinten, sie sähen einen Geist." },
      { number: 38, text: "Und er sprach zu ihnen: Was seid ihr bestürzt, und warum steigen Gedanken auf in euren Herzen?" },
      { number: 39, text: "Seht meine Hände und meine Füße, dass ich es selbst bin; betastet mich und seht! Denn ein Geist hat nicht Fleisch und Bein, wie ihr seht, dass ich habe*.", footnotes: ["℘ 1Jo 1,1"] },
      { number: 40, text: "*Und als er dies gesagt hatte, zeigte er ihnen die Hände und die Füße.*", footnotes: ["Dieser Vers ist in einigen Handschr. nicht enthalten.", "Dieser Vers ist in einigen Handschr. nicht enthalten."] },
      { number: 41, text: "Als sie aber noch nicht glaubten vor Freude* und sich wunderten, sprach er zu ihnen: Habt ihr hier etwas zu essen*?", footnotes: ["℘ Joh 16,22", "℘ Joh 21,5"] },
      { number: 42, text: "Sie aber reichten ihm ein Stück gebratenen Fisch*;", footnotes: ["Andere Handschriften fügen hinzu: und <etwas> von einer Honigwabe"] },
      { number: 43, text: "und er nahm und aß vor ihnen*.", footnotes: ["℘ Apg 10,41"] },
      { number: 44, text: "Er sprach aber zu ihnen: Dies sind meine Worte, die ich zu euch redete, als ich noch bei euch war*, dass alles erfüllt werden muss, was über mich geschrieben steht in dem Gesetz Moses und in den Propheten und Psalmen*.", footnotes: ["℘ V. 6", "℘ V. 25; Kap. 18,31; Ps 40,7.8; Joh 13,18; Apg 1,16; 13,27 ⇨Esyn: Synopse Nr. 365"] },
      { number: 45, text: "Dann öffnete er ihnen das Verständnis, damit sie die Schriften verständen*,", footnotes: ["℘ V. 27"] },
      { number: 46, text: "und sprach zu ihnen: So steht geschrieben, und so musste der Christus leiden und am dritten Tag auferstehen aus den Toten*", footnotes: ["℘ V. 7; Joh 20,9; 1Kor 15,3.4"] },
      { number: 47, text: "und in seinem Namen Buße zur* Vergebung der Sünden gepredigt werden* allen Nationen*, anfangend von Jerusalem*.", footnotes: ["mit anderen Handschr.: und", "℘ Apg 5,31; 1Jo 2,12", "℘ Jes 49,6; Mt 24,14; Apg 11,18", "℘ Apg 1,8"] },
      { number: 48, text: "Ihr seid Zeugen hiervon*;", footnotes: ["℘ 1Petr 5,1"] },
      { number: 49, text: "und siehe, ich sende die Verheißung meines Vaters auf euch*. Ihr aber, bleibt in der Stadt, bis ihr bekleidet werdet mit Kraft aus der Höhe!", footnotes: ["℘ Joh 7,39; Apg 1,4"] },
      { number: 50, text: "*Er führte sie aber hinaus bis gegen Betanien und hob seine Hände auf und segnete sie.", heading: "Himmelfahrt", footnotes: ["℘ Mk 16,19; Apg 1,9-12"] },
      { number: 51, text: "Und es geschah, während er sie segnete, schied er von ihnen und wurde hinaufgetragen in den Himmel*.", footnotes: ["℘ Joh 6,62"] },
      { number: 52, text: "Und sie warfen sich vor ihm nieder* und kehrten nach Jerusalem zurück mit großer Freude*;", footnotes: ["℘ Mt 28,17", "℘ Kap. 2,10"] },
      { number: 53, text: "und sie waren allezeit im Tempel und priesen Gott*.", footnotes: ["℘ Apg 2,46"] },
    ]},
  ]
};
